def render_tan_half_fov(cam, render):
    """tan of half the field of view across and up a render: the sensor fits the frame's larger
    side (Auto), its width or its height; the other follows the frame's aspect. (Blender's
    angle_y is the sensor height's, whatever the frame: 1.5x too narrow on a square render.)"""
    rx = render.resolution_x * render.pixel_aspect_x
    ry = render.resolution_y * render.pixel_aspect_y
    fit = cam.sensor_fit
    if fit == 'VERTICAL' or fit == 'AUTO' and ry > rx:
        ty = cam.sensor_height / 2.0 / cam.lens if fit == 'VERTICAL' else cam.sensor_width / 2.0 / cam.lens
        return ty * rx / ry, ty
    tx = cam.sensor_width / 2.0 / cam.lens
    return tx, tx * ry / rx


def custom_code(p):
    return " ".join(str(p.get("Code", "")).split())


def custom_handler(p):
    """The Translator method that rebuilds a Custom node's HLSL, or None."""
    code = custom_code(p)
    return CUSTOM_SNIPPETS.get(code) or CUSTOM_HASHES.get(hashlib.sha1(code.encode("utf-8")).hexdigest()[:8])


# Pins the translator never reads: texture derivatives and mips, and the
# scene inputs of renderer-only stand-ins. The coverage census skips them.
UNREAD_PINS = {
    "*": {"CoordinatesDX", "CoordinatesDY", "MipValue", "AutomaticViewMipBiasValue"},
    "DDX": {"Value"}, "DDY": {"Value"},
    "DepthFade": {"FadeDistance"}, "SceneDepth": {"Input"}, "SceneColor": {"Input"},
    "SceneDepthWithoutWater": {"Input"},
    "SceneTexture": {"Coordinates"}, "DistanceFieldApproxAO": {"BaseDistance", "Radius", "Normal", "Position"},
    "SkyAtmosphereLightIlluminance": {"WorldPosition"}, "SamplePhysicsVectorField": {"WorldPosition"},
    "RuntimeVirtualTextureSampleParameter": {"WorldPosition", "Coordinates"},
    "RuntimeVirtualTextureSample": {"WorldPosition", "Coordinates"},
}


def object_path(path, name):
    """"/Game/X/T_A.0" (CUE4Parse's export index) -> "/Game/X/T_A.T_A"."""
    base, _, tail = path.rpartition(".")
    if not base or not tail.isdigit():
        return path
    return "%s.%s" % (base, name.split(":")[-1].split(".")[-1])


def short_name(key):
    """A texture's label: "/Game/X/T_A.T_A" -> "T_A"."""
    return key.rsplit("/", 1)[-1].split(".")[0]


def linked(ref):
    return isinstance(ref, dict) and ref.get("ExpressionName") not in (None, "None")


def handled_types():
    """Every expression type the translator turns into nodes, read from its
    own source, so the coverage census can't drift from it."""
    src = open(__file__, encoding="utf-8").read()
    body = src[src.index("    def _expr_in"):]
    out = set(re.findall(r'\bt == "([A-Za-z0-9_]+)"', body))
    for grp in re.findall(r'\bt in \(([^)]*)\)', body):
        out |= set(re.findall(r'"([A-Za-z0-9_]+)"', grp))
    return out | set(COMPILE_SWITCHES) | {"Reroute", "NamedRerouteUsage", "NamedRerouteDeclaration"}


class TexRef:
    """A texture as a value: what TextureObject(Parameter) hands a sample."""
    __slots__ = ("name", "volume")

    def __init__(self, name, volume=False):
        # name: the env's key for it (an object path with env.asset_paths)
        self.name, self.volume = name, volume


class Val:
    """A value in the Blender graph: a socket (or a Python constant) and a
    width. Blender vectors have three components; a UE float4 keeps its
    fourth as `a`, a width-1 Val of its own."""
    __slots__ = ("s", "w", "a")

    def __init__(self, s, w, a=None):
        self.s, self.w, self.a = s, w, a

    @property
    def const(self):
        return not hasattr(self.s, "node")


def T(x):
    return (x.get("Type") or "").replace("MaterialExpression", "")


def _inner(object_name):
    """"Class'Pkg:Outer.Name'" -> "Pkg:Outer.Name"."""
    return object_name.split("'")[1] if "'" in object_name else object_name


_GRAPHS = {}


def load_graph(path):
    """A graph dump, parsed once per file version: a map's hundreds of
    materials share masters and functions, and parsing them was a tenth of
    the build (Graph objects are only read once made)."""
    try:
        st = os.stat(path)
        key = (path, st.st_mtime_ns, st.st_size)
    except OSError:
        return Graph(path)
    g = _GRAPHS.get(key)
    if g is None:
        if len(_GRAPHS) > 600:
            _GRAPHS.clear()
        g = _GRAPHS[key] = Graph(path)
    return g


PIXEL_NORMAL = "PixelNormalWS"     # a function group's PixelNormalWS input (env.group_input fills it)
NORMAL_PASS = "Normal pass"        # the frame the Normal's own pass is made in (Translator.normal_pass)


def _comps3(s):
    return tuple(s)[:3] if isinstance(s, (tuple, list)) else (s, s, s)


class TexKey(str):
    """A texture key that remembers the texture parameter it came from."""
    param = None

    @staticmethod
    def of(key, param):
        k = TexKey(key)
        k.param = param
        return k


class Graph:
    """One dumped graph. Expressions are found by name; a name used twice
    (a collapsed subgraph keeps its own numbering: its Reroute_13 isn't the
    material's) by its full object path instead - see key()."""

    def __init__(self, path):
        self.path = path
        self.name = os.path.splitext(os.path.basename(path))[0]
        self.o = json.load(open(path, encoding="utf-8"))
        seen, self.dups = set(), set()
        for x in self.o:
            n = x.get("Name")
            (self.dups if n in seen else seen).add(n)
        self.by = {}
        for x in self.o:
            self.by[self.full_name(x) if x.get("Name") in self.dups else x.get("Name")] = x
        self.decl = {k: x for k, x in self.by.items() if T(x) == "NamedRerouteDeclaration"}
        self.inputs = {x["Properties"].get("Id"): x for x in self.o if T(x) == "FunctionInput"}
        self.outputs = {x["Properties"].get("Id"): x for x in self.o if T(x) == "FunctionOutput"}
        # the author's comment boxes, smallest first: a node inside one is
        # framed under its text
        self.comments = []
        for x in self.o:
            if T(x) != "Comment":
                continue
            p = x.get("Properties") or {}
            x0, y0 = p.get("MaterialExpressionEditorX", 0), p.get("MaterialExpressionEditorY", 0)
            w, h = p.get("SizeX", 0), p.get("SizeY", 0)
            text = " ".join(str(p.get("Text", "")).split())[:40].strip()
            if w and h and text:
                self.comments.append((w * h, x0, y0, x0 + w, y0 + h, text))
        self.comments.sort()

    @staticmethod
    def full_name(x):
        outer = _inner(str((x.get("Outer") or {}).get("ObjectName", "")))
        return "%s%s%s" % (outer, "." if ":" in outer else ":", x.get("Name"))

    def key(self, ref):
        """The expression an input dict points at, as a key of `by`."""
        n = ref.get("ExpressionName")
        if n in self.dups:
            return _inner(str((ref.get("Expression") or {}).get("ObjectName", ""))) or n
        return n

    def comment_of(self, x):
        p = x.get("Properties") or {}
        if "MaterialExpressionEditorX" not in p:
            return None
        px, py = p["MaterialExpressionEditorX"], p.get("MaterialExpressionEditorY", 0)
        for _, x0, y0, x1, y1, text in self.comments:
            if x0 <= px <= x1 and y0 <= py <= y1:
                return text
        return None

    def editor_data(self):
        return next((x for x in self.o if T(x) in ("MaterialEditorOnlyData",)), None)


SOCKET_OF_WIDTH = {1: 'NodeSocketFloat', 2: 'NodeSocketVector', 3: 'NodeSocketVector', 4: 'NodeSocketColor'}
WIDTH_OF_SOCKET = {'NodeSocketFloat': 1, 'NodeSocketVector': 3, 'NodeSocketColor': 3}
INPUT_WIDTH = {"EFunctionInputType::FunctionInput_Scalar": 1, "EFunctionInputType::FunctionInput_Bool": 1,
               STATIC_BOOL_INPUT: 1, "EFunctionInputType::FunctionInput_Vector2": 2,
               "EFunctionInputType::FunctionInput_Vector3": 3, "EFunctionInputType::FunctionInput_Vector4": 4}


class FunctionTree:
    """One UE material function as one node group, shared by every call.

    Its FunctionInputs are the group's inputs and its outputs are built as they
    are first asked for. A call site gets its own group node and links only the
    inputs the asked-for output reaches - UE compiles each output on its own,
    and linking the rest can close a loop (the sky's horizon-hills mask feeds
    the chain that ends in the same function's colour input). What the body
    reads from the material (a parameter socket, the sun) becomes an input
    too, handed down by the caller: see env.group_input.

    Static bool inputs aren't sockets: UE compiles the function once per set
    of values, and so does this (`statics`, input id -> bool; `label` names
    the variant).
    """
    PREFIX = "FPv4 Sky - "

    def __init__(self, parent, fname, fg, statics=None, label=None):
        import bpy
        self.fname, self.fg = fname, fg
        self.statics = statics or {}
        self.prefix = getattr(parent.env, "function_prefix", self.PREFIX)
        name = self.prefix + (label or section_name(fname))
        # a rebuild replaces its old group (the sky); an env that builds
        # alongside other materials keeps them (env.replace_groups = False:
        # Blender numbers the new one)
        old = bpy.data.node_groups.get(name)
        if old is not None and getattr(parent.env, "replace_groups", True):
            bpy.data.node_groups.remove(old)
        self.tree = bpy.data.node_groups.new(name, "ShaderNodeTree")
        self.tr = Translator(self.tree, parent.env, parent=parent)
        self.tr.function = self
        self.tr.section = [section_name(fname)]
        self.gi = self.tree.nodes.new("NodeGroupInput")
        self.go = self.tree.nodes.new("NodeGroupOutput")
        self.gi[SECTION_KEY] = self.go[SECTION_KEY] = self.tr.section[0]
        self.kind = {}          # input socket name -> ("ue", input id) | ("env", name)
        self.ue_names = {}      # UE input id -> socket name
        self.previews = {}      # socket name -> preview expression ref, for callers that leave it
        self.outs = {}          # output id -> (socket name, width); width "attrs" for Material Attributes
        self.attr_outs = {}     # output id -> {attribute: ("socket", name, width) | ("const", Val)}
        self.needs = {}
        self.textures = {}      # closure input socket name -> (texture key, sampler, image, own sampler, address)

    def _new_input(self, name, width, kind):
        base, i = name, 2
        name = socket_name(name)
        while any(it.item_type == 'SOCKET' and it.in_out == 'INPUT' and it.name == name
                  for it in self.tree.interface.items_tree):
            if self.kind.get(name) == kind:
                return name
            name = socket_name("%s %d" % (base, i))
            i += 1
        self.tree.interface.new_socket(name, in_out='INPUT', socket_type=SOCKET_OF_WIDTH[width])
        self.kind[name] = kind
        return name

    def ue_input(self, x):
        """The group input standing for a FunctionInput expression."""
        p = x.get("Properties") or {}
        fid = p.get("Id")
        if p.get("InputType") == STATIC_BOOL_INPUT:
            return self.tr.const(1.0 if self.statics.get(fid) else 0.0)
        if p.get("InputType") == ATTRIBUTES_INPUT:
            return Val(OpenAttrs(self, fid, p.get("InputName") or "Material Attributes"), 0)
        if fid not in self.ue_names:
            w = INPUT_WIDTH.get(p.get("InputType"), 3)
            name = self._new_input(p.get("InputName") or "Input", w, ("ue", fid))
            self.ue_names[fid] = name
            item = next(it for it in self.tree.interface.items_tree
                        if it.item_type == 'SOCKET' and it.in_out == 'INPUT' and it.name == name)
            v = p.get("PreviewValue", {})
            dflt = (v.get("X", 0.0), v.get("Y", 0.0), v.get("Z", 0.0))
            if p.get("bUsePreviewValueAsDefault"):
                item.default_value = dflt[0] if w == 1 else (dflt + (1.0,) if w == 4 else dflt)
                if isinstance(p.get("Preview"), dict) and p["Preview"].get("ExpressionName") not in (None, "None"):
                    self.previews[name] = p["Preview"]
            if p.get("Description"):
                item.description = str(p.get("Description"))[:200]
        name = self.ue_names[fid]
        w = INPUT_WIDTH.get(p.get("InputType"), 3)
        if w == 4:
            aname = socket_name(name + " (A)")
            if aname not in self.kind:
                self.tree.interface.new_socket(aname, in_out='INPUT', socket_type='NodeSocketFloat')
                self.kind[aname] = ("ue_alpha", fid)
            return Val(self.gi.outputs[name], 4, Val(self.gi.outputs[aname], 1))
        return Val(self.gi.outputs[name], min(w, 3))

    def env_input(self, key, socket_type, default=None, description=""):
        # the socket's name may be cut (socket_name); the env gets its key back whole
        name = socket_name(key)
        if name not in self.kind:
            self.tree.interface.new_socket(name, in_out='INPUT', socket_type=socket_type)
            item = next(it for it in self.tree.interface.items_tree
                        if it.item_type == 'SOCKET' and it.in_out == 'INPUT' and it.name == name)
            if default is not None:
                try:
                    item.default_value = default
                except Exception:
                    pass
            item.description = description
            self.kind[name] = ("env", key)
        return Val(self.gi.outputs[name], WIDTH_OF_SOCKET.get(socket_type, 3))

    def texture_input(self, spec, tname, sampler, img, own, address):
        """The Closure input a texture the body samples arrives on (Vector -> Color, Alpha): the
        image node stays at the material's root, so the group holds no image and every material
        calling the function shares it. Named for the texture parameter (an instance's texture
        doesn't rename it), else the texture."""
        key = ("tex", spec)
        for name, k in self.kind.items():
            if k == key:
                return self.gi.outputs[name]
        taken = {it.name for it in self.tree.interface.items_tree if it.item_type == 'SOCKET' and it.in_out == 'INPUT'}
        base = getattr(tname, "param", None) or short_name(str(tname)) or "Texture"
        name, i = socket_name(base), 2
        while name in taken:
            name = socket_name("%s %d" % (base, i))
            i += 1
        item = self.tree.interface.new_socket(name, in_out='INPUT', socket_type='NodeSocketClosure')
        item.description = "UE texture %s: its image node is in the material's Textures frame" % base
        self.kind[name] = key
        self.textures[name] = (tname, sampler, img, own, address)
        return self.gi.outputs[name]

    def output(self, fo):
        """Build a FunctionOutput once; returns (socket name, width)."""
        p = fo["Properties"]
        oid = p.get("Id")
        if oid in self.outs:
            return self.outs[oid]
        prev = self.tr.activate()
        try:
            v = self.tr.input(self.fg, p.get("A"), {"_fn": self, "_id": ("fn", self.fname)}, self.tr.const(0.0))
            name = socket_name(p.get("OutputName") or "Result")
            if name in [o[0] for o in self.outs.values()]:
                name = socket_name("%s %d" % (name, len(self.outs) + 1))
            if isinstance(v.s, Attrs):
                self.outs[oid] = (name, "attrs")
                passes = self.tr.passthrough(self.fg, p.get("A"), {"_fn": self, "_id": ("fn", self.fname)})
                self.attr_outs[oid] = self.attribute_outputs(name, v.s, passes)
                return self.outs[oid]
            w = min(max(v.w, 1), 3)
            self.tree.interface.new_socket(name, in_out='OUTPUT', socket_type=SOCKET_OF_WIDTH[w])
            a = v.a if v.w == 4 else None
            if v.const:
                v = self.tr.solid(v)
            self.tr.L.new(v.s, self.go.inputs[name])
            if a is not None:
                # a float4: its fourth component on a socket of its own
                self.tree.interface.new_socket(socket_name(name + " (A)"), in_out='OUTPUT', socket_type='NodeSocketFloat')
                if a.const:
                    a = self.tr.solid(a)
                self.tr.L.new(a.s, self.go.inputs[socket_name(name + " (A)")])
                w = 4
        finally:
            prev.activate()
        self.outs[oid] = (name, w)
        return self.outs[oid]

    def attribute_outputs(self, name, attrs, passes):
        """A Material Attributes output: a socket per CARRIED attribute the
        function computes; constants go to the caller as data, and attributes
        that leave unchanged from a Material Attributes input (`passes`) don't
        enter the group at all - the caller keeps its own."""
        out = {}
        for a in self.tr.carried:
            if a in passes:
                out[a] = ("pass", passes[a])
                continue
            v = attrs.get(a)
            if v.const:
                out[a] = ("const", v)
                continue
            sock = socket_name("%s: %s" % (name, pretty(a)))
            w = min(max(v.w, 1), 3)
            self.tree.interface.new_socket(sock, in_out='OUTPUT', socket_type=SOCKET_OF_WIDTH[w])
            self.tr.L.new(v.s, self.go.inputs[sock])
            out[a] = ("socket", sock, w)
        return out

    def reached(self, out_name):
        """The input sockets an output depends on - through a nested group, only the inputs
        the output it reads depends on (a function passing Material Attributes through another
        read every attribute for its Normal: the Normal's own pass copied the whole material)."""
        if out_name not in self.needs:
            want = self.go.inputs[out_name].identifier
            names = {s.identifier: s.name for s in self.gi.outputs}
            self.needs[out_name] = {names[i] for i in _group_deps(self.tree, {}).get(want, ()) if i in names}
        return self.needs[out_name]


class Translator:
    def __init__(self, tree, env, x0=0, y0=0, parent=None):
        self.tree, self.env = tree, env
        self.N, self.L = tree.nodes, tree.links
        self.cache = {}
        # a function call's group node, shared by every output read from it: (node, inputs linked)
        self.call_sites = {}
        self.shared_calls = set()       # names of the call nodes more than one output reads
        self.graphs = parent.graphs if parent else {}
        # material functions become shared node groups (env.nest_functions)
        self.functions = parent.functions if parent else {}
        # the Material Attributes a function's group passes in and out: CARRIED, and what
        # this material's build reads besides (a moving one's World Position Offset)
        self.carried = parent.carried if parent else CARRIED
        self.function = None
        self.x, self.y = x0, y0
        self.warnings = []
        # the layout section new nodes go in (tools/layout.py): the material,
        # then one frame per material function it calls, nested as UE nests them
        self.section = []
        self._shared = {}
        # clip()s of the material's own graph: where one is 0 the pixel isn't drawn
        self.clips = []

    def activate(self):
        """Make this the translator the env builds nodes with; returns the
        one that was, to activate again after."""
        prev = getattr(self.env, "current", lambda: None)()
        if hasattr(self.env, "set_current"):
            self.env.set_current(self)
        return prev or self

    def solid(self, v):
        """A constant as a node, where a socket must be linked."""
        if v.w == 1:
            n = self.node("ShaderNodeValue", "constant")
            n.outputs[0].default_value = float(v.s)
            return Val(n.outputs[0], 1)
        n = self.node("ShaderNodeCombineXYZ", "constant")
        for i, c in enumerate(tuple(v.s)[:3]):
            n.inputs[i].default_value = c
        return Val(n.outputs[0], 3)

    @contextmanager
    def at(self, *path):
        """Make nodes under an absolute section path for a while."""
        saved = self.section
        self.section = list(path)
        try:
            yield
        finally:
            self.section = saved

    # ------------------------------------------------------------- nodes
    def node(self, kind, label="", **props):
        n = self.N.new(kind)
        n.location = (self.x, self.y)
        self.y -= 30
        n.label = label
        n[SECTION_KEY] = "/".join(self.section)
        for k, v in props.items():
            setattr(n, k, v)
        return n

    def link(self, val, sock):
        if val is None:
            return
        if isinstance(val.s, (Attrs, TexRef)):
            self.warnings.append("%s can't go into a socket (%s)" % (type(val.s).__name__, sock.name))
            return
        if val.const:
            v = val.s
            if sock.type == 'VECTOR' or sock.type == 'RGBA':
                if isinstance(v, (int, float)):
                    v = (v, v, v)
                v = tuple(v)[:3]
                if sock.type == 'RGBA':
                    v = v + (1.0,)
                sock.default_value = v
            else:
                sock.default_value = v if isinstance(v, (int, float)) else v[0]
        else:
            self.L.new(val.s, sock)

    def const(self, v, w=None):
        if isinstance(v, (int, float)):
            if w and w > 1:
                # a scalar asked for as a vector: broadcast (UE's cast)
                return self.const((float(v),) * (4 if w == 4 else 3), w)
            return Val(float(v), 1)
        if w == 1:
            return Val(float(tuple(v)[0]), 1)
        v = tuple(float(x) for x in v)
        if len(v) >= 4 and (w or 4) == 4:
            return Val(v[:3], 4, Val(v[3], 1))
        return Val(v + (0.0,) * (3 - len(v)) if len(v) < 3 else v[:3], w or len(v))

    def math(self, op, a, b=None, c=None, clamp=False, label=""):
        if a.const and (b is None or b.const) and (c is None or c.const) and not clamp and op in _PY:
            return Val(_PY[op](a.s, None if b is None else b.s), 1)
        n = self.node("ShaderNodeMath", label or op, operation=op, use_clamp=clamp)
        for i, v in enumerate((a, b, c)):
            if v is not None:
                self.link(v, n.inputs[i])
        return Val(n.outputs[0], 1)

    def vmath(self, op, a, b=None, c=None, label="", out_w=None):
        n = self.node("ShaderNodeVectorMath", label or op, operation=op)
        if op == 'SCALE':
            # the factor has its own socket; inputs[1] is hidden for SCALE,
            # and a link to a hidden socket is silently ignored
            self.link(a, n.inputs[0])
            self.link(b, n.inputs["Scale"])
            return Val(n.outputs["Vector"], out_w or a.w)
        for i, v in enumerate((a, b, c)):
            if v is not None:
                self.link(v, n.inputs[i])
        if op in ("DOT_PRODUCT", "LENGTH", "DISTANCE"):
            return Val(n.outputs["Value"], 1)
        return Val(n.outputs["Vector"], out_w or max(x.w for x in (a, b, c) if x is not None))

    def alpha(self, v):
        """The 4th component of a value: its own for a float4, the value
        itself for a float1 (UE broadcasts those)."""
        if v.w == 1:
            return v
        if v.a is not None:
            return v.a
        return self.const(0.0)

    def with_alpha(self, v, a):
        return Val(v.s, 4, a)

    def binop(self, op, a, b, label=""):
        w = max(a.w, b.w)
        if w == 1:
            return self.math(op, a, b, label=label)
        vop = {"FLOOR_DIVIDE": "DIVIDE"}.get(op, op)
        v = self.vmath(vop, a, b, label=label, out_w=w)
        if w == 4:
            v = self.with_alpha(v, self.math(op if op != "FLOOR_DIVIDE" else "DIVIDE", self.alpha(a), self.alpha(b)))
        return v

    def divide(self, a, b, label=""):
        """UE's A / B. Where B is zero the GPU gives an infinity of A's sign - which a saturate
        turns into 1 or 0: a fade over a length of 0 shows everything past its start - where a
        Blender Divide gives 0 (the material drew nothing). A divisor that is a socket (a
        parameter, a function's input) is checked as the material runs; one known when the
        material is built and not zero: a plain Divide."""
        big = 1e18
        if b.const:
            values = b.s if isinstance(b.s, (tuple, list)) else (b.s,)
            if all(float(v) != 0.0 for v in values):
                return self.binop('DIVIDE', a, b, label=label)
            if b.w == 1:
                return self.binop('MULTIPLY', a, self.const(big), label=label)
        if b.w == 4:
            return self.binop('DIVIDE', a, b, label=label)
        if b.w != 1:
            # the same per component (a scale of 0 put through Scale UVs By Center - a sprite's
            # missing mouth - pushes its UVs off the texture: Blender's 0 drew the mouth's middle
            # over the whole body): 1 - sign(|B|) is 1 where a component is 0
            zero = self.vmath('SUBTRACT', self.const(1.0, b.w),
                              self.vmath('SIGN', self.vmath('ABSOLUTE', b, out_w=b.w), out_w=b.w), out_w=b.w)
            return self.binop('ADD', self.binop('DIVIDE', a, b, label=label),
                              self.binop('MULTIPLY', a, self.vmath('MULTIPLY', zero, self.const(big, b.w), out_w=b.w)))
        # (1 where B is exactly 0) * big * A, added to the Divide's 0
        zero = self.math('COMPARE', b, self.const(0.0), self.const(0.0))
        return self.binop('ADD', self.binop('DIVIDE', a, b, label=label),
                          self.binop('MULTIPLY', a, self.math('MULTIPLY', zero, self.const(big))))

    def unary(self, op, a):
        if a.w == 1:
            mop = {"FRACTION": "FRACT", "NORMALIZE": "SIGN"}.get(op, op)
            return self.math(mop, a)
        v = self.vmath(op, a, out_w=a.w)
        if a.w == 4:
            mop = {"FRACTION": "FRACT", "NORMALIZE": "SIGN"}.get(op, op)
            v = self.with_alpha(v, self.math(mop, self.alpha(a)))
        return v

    def saturate(self, a):
        if a.w == 1:
            return self.math('MULTIPLY', a, self.const(1.0), clamp=True, label="saturate")
        v = self.vmath('MINIMUM', self.vmath('MAXIMUM', a, self.const(0.0)), self.const(1.0), out_w=a.w)
        if a.w == 4:
            v = self.with_alpha(v, self.math('MULTIPLY', self.alpha(a), self.const(1.0), clamp=True))
        return v

    def lerp(self, a, b, t, label="lerp"):
        if isinstance(a.s, Attrs) or isinstance(b.s, Attrs):
            if t.const and t.w == 1 and t.s in (0.0, 1.0):
                return b if t.s else a
            return self._attrs_op(lambda x, y: self.lerp(x, y, t, label=label), a, b)
        w = max(a.w, b.w, t.w)
        if w == 1:
            n = self.node("ShaderNodeMix", label, data_type='FLOAT', clamp_factor=False)
            self.link(t, n.inputs[0]); self.link(a, n.inputs[2]); self.link(b, n.inputs[3])
            return Val(n.outputs[0], 1)
        n = self.node("ShaderNodeMix", label, data_type='VECTOR', clamp_factor=False,
                      factor_mode='NON_UNIFORM' if t.w > 1 else 'UNIFORM')
        self.link(t, n.inputs[1] if t.w > 1 else n.inputs[0])
        self.link(a, n.inputs[4]); self.link(b, n.inputs[5])
        v = Val(n.outputs[1], w)
        if w == 4:
            ta = self.alpha(t) if t.w > 1 else t
            v = self.with_alpha(v, self.lerp(self.alpha(a), self.alpha(b), ta))
        return v

    def rgba_out(self, rgb, a, out):
        """A colour expression's outputs: RGB, R, G, B, A, RGBA."""
        if out == 5:
            return self.with_alpha(rgb, a)
        if out == 4:
            return a
        return rgb if out == 0 else self.mask(rgb, [out - 1])

    def comps(self, v):
        """[x, y, z] floats of a value (width 1 broadcasts)."""
        if v.w == 1:
            return [v, v, v]
        if v.const:
            return [Val(c, 1) for c in v.s[:3]]
        n = self.node("ShaderNodeSeparateXYZ", "split")
        self.link(v, n.inputs[0])
        return [Val(n.outputs[i], 1) for i in range(3)]

    def combine(self, parts):
        parts = list(parts)
        if len(parts) == 1:
            return parts[0]
        if len(parts) > 3:
            v = self.combine(parts[:3])
            return Val(v.s, 4, parts[3] if parts[3].w == 1 else self.comps(parts[3])[0])
        if all(p.const for p in parts):
            return self.const(tuple(p.s for p in parts) + (0.0,) * (3 - len(parts)), len(parts))
        n = self.node("ShaderNodeCombineXYZ", "append")
        for i, p in enumerate(parts):
            self.link(p, n.inputs[i])
        return Val(n.outputs[0], len(parts))

    def mask(self, v, idx):
        """Components idx (0=R..3=A) of v."""
        if v.w == 1:
            return v if len(idx) == 1 else self.combine([v] * len(idx))
        cs = self.comps(v)
        parts = []
        for i in idx:
            if i < 3:
                parts.append(cs[i])
            elif v.a is not None:
                parts.append(v.a)
            else:
                self.warnings.append("alpha of a computed vector read as 1")
                parts.append(self.const(1.0))
        return self.combine(parts)

    def zero_z(self, v):
        return self.combine(self.comps(v)[:2] + [self.const(0.0)]) if v.w == 2 else v

    def flat(self, a, b):
        """Two operands of a length or a distance: where the wider is 2 wide, both with Z 0 (a
        scalar against a float2 spreads over X and Y only)."""
        if max(a.w, b.w) != 2:
            return a, b
        return tuple(self.combine(self.comps(v)[:2] + [self.const(0.0)]) for v in (a, b))

    # -------------------------------------------------------- evaluation
    def graph(self, path):
        g = self.graphs.get(path)
        if g is None:
            g = self.graphs[path] = load_graph(path)
        return g

    def material_output(self, path, prop):
        g = self.graph(path)
        ed = g.editor_data()
        return self.input(g, ed["Properties"][prop], {}, None)

    def prune_unused(self):
        """Remove function groups no node uses (a function whose outputs all
        went to its callers as pass-throughs or constants)."""
        import bpy
        while True:
            dead = [k for k, ft in self.functions.items() if ft.tree.users == 0]
            if not dead:
                return
            # one pass over the file for all of them (a removal each walked every datablock)
            bpy.data.batch_remove([self.functions.pop(k).tree for k in dead])

    def material_attributes(self, path, names=CARRIED):
        """A material's attributes Blender has a place for, {name: Val}: from
        its MaterialAttributes pin, or its separate output pins (unlinked ones
        are UE's defaults)."""
        g = self.graph(path)
        pins = (g.editor_data() or {}).get("Properties") or {}
        self.carried = tuple(CARRIED) + tuple(n for n in names if n not in CARRIED)
        if linked(pins.get("MaterialAttributes")):
            v = self.input(g, pins["MaterialAttributes"], {}, None)
            attrs = v.s if v is not None and isinstance(v.s, Attrs) else Attrs()
            # what PixelNormalWS reads (pixel_normal): the Normal, made apart (its own scope: a
            # function's group node would carry both the Normal and what reads it - a loop UE,
            # compiling each property on its own, never has); merge_duplicates folds what it can
            def normal():
                with self.normal_pass():
                    nv = self.input(g, pins["MaterialAttributes"], {"_id": PIXEL_NORMAL}, None)
                    return (nv.s if nv is not None and isinstance(nv.s, Attrs) else Attrs()).get("Normal")
            self._normal_src = normal
            out = {n: attrs.get(n) for n in names}
            out.update(self.water_outputs(g))
            self.prune_unused()
            return out
        out = {}
        npin = next((k for k, a in PIN_ATTRIBUTE.items() if a == "Normal" and linked(pins.get(k))), None)
        def normal():
            with self.normal_pass():
                return self.input(g, pins[npin], {"_id": PIXEL_NORMAL}, None)
        self._normal_src = normal if npin else (lambda: None)
        for n in names:
            pin = next((k for k, a in PIN_ATTRIBUTE.items() if a == n and linked(pins.get(k))), None)
            out[n] = self.input(g, pins[pin], {}, None) if pin else attribute_default(n)
        out.update(self.water_outputs(g))
        return out

    @contextlib.contextmanager
    def normal_pass(self):
        """The Normal's own pass in a frame of its own: what it doesn't share with the rest
        (merge_duplicates folds what it does) is a second copy of the functions on the way -
        a group node can't feed its own PixelNormalWS input."""
        saved = self.section
        self.section = [NORMAL_PASS]
        try:
            yield
        finally:
            self.section = saved

    def water_outputs(self, g):
        """A water material's medium (its SingleLayerWaterMaterialOutput, a
        custom output beside the attributes), {WATER_OUTPUTS name: Val}; {}
        for a material without one."""
        x = next((x for x in g.o if T(x) == "SingleLayerWaterMaterialOutput"), None)
        if x is None:
            return {}
        p = x.get("Properties") or {}
        # a frame of its own: laid out apart from the attributes, its wires stay short
        with self.at("Water Medium"):
            return {name: self.input(g, p.get(pin), {}, self.const(d, 1 if isinstance(d, float) else 3))
                    for pin, name, d in WATER_OUTPUTS}

    def input(self, g, ref, scope, default):
        """Evaluate an FExpressionInput dict (or return default)."""
        if not (isinstance(ref, dict) and ref.get("ExpressionName") not in (None, "None")):
            return default
        v = self.expr(g, g.key(ref), ref.get("OutputIndex", 0) or 0, scope)
        if ref.get("Mask"):
            idx = [i for i, k in enumerate(("MaskR", "MaskG", "MaskB", "MaskA")) if ref.get(k)]
            v = self.mask(v, idx)
        return v

    def pin(self, g, x, name, scope, cls=None, fallback=0.0):
        p = x.get("Properties") or {}
        cls = cls or T(x)
        const_name = {"A": "ConstA", "B": "ConstB", "Alpha": "ConstAlpha", "Exponent": "ConstExponent",
                      "X": "ConstX", "Y": "ConstY", "Min": "ConstMin", "Max": "ConstMax", "Value": "ConstValue"}.get(name)
        dflt = p.get(const_name) if const_name and const_name in p and not isinstance(p.get(const_name), dict) \
            else UE_DEFAULTS.get((cls, const_name), fallback)
        v = self.input(g, p.get(name), scope, self.const(dflt))
        if isinstance(v.s, Attrs):
            # maths on Material Attributes: UE would compile it per property;
            # this reads Base Color
            self.warnings.append("Material Attributes used as a value in %s -> Base Color" % x.get("Name"))
            v = v.s.get("BaseColor")
        return v

    def expr(self, g, name, out, scope):
        key = (g.path, name, out, scope.get("_id", 0))
        if key in self.cache:
            return self.cache[key]
        stack = self.__dict__.setdefault("_stack", [])
        if key in stack:
            cyc = [k[1].replace("MaterialExpression", "") for k in stack[stack.index(key):]]
            raise RuntimeError("cycle in %s: %s" % (g.name, " -> ".join(cyc)))
        stack.append(key)
        try:
            return self._expr(g, name, out, scope, key)
        finally:
            stack.pop()

    def _expr(self, g, name, out, scope, key):
        x = g.by[name]
        comment = g.comment_of(x) if g.comments and self.section else None
        if comment is None:
            return self._expr_in(g, x, name, out, scope, key)
        saved = self.section
        self.section = self.section[:1] + [comment]
        try:
            return self._expr_in(g, x, name, out, scope, key)
        finally:
            self.section = saved

    @staticmethod
    def declaration(g, p):
        """The NamedRerouteDeclaration a usage reads: by its GUID (unique),
        else by its object path."""
        if p.get("DeclarationGuid"):
            d = next((d for d in g.decl.values()
                      if d["Properties"].get("VariableGuid") == p.get("DeclarationGuid")), None)
            if d is not None:
                return d
        if "Declaration" in p:
            full = _inner(str(p["Declaration"].get("ObjectName", "")))
            return g.decl.get(full) or g.decl.get(full.split(":")[-1].split(".")[-1])
        return None

    def _expr_in(self, g, x, name, out, scope, key):
        t = T(x)
        # reroutes are transparent
        if t == "Reroute":
            v = self.input(g, x["Properties"].get("Input"), scope, self.const(0.0))
        elif t == "NamedRerouteUsage":
            decl = self.declaration(g, x["Properties"])
            v = self.input(g, decl["Properties"].get("Input"), scope, self.const(0.0)) if decl \
                else self.const(0.0)
        elif t == "NamedRerouteDeclaration":
            v = self.input(g, x["Properties"].get("Input"), scope, self.const(0.0))
        else:
            v = self.evaluate(g, x, t, out, scope)
        self.cache[key] = v
        return v

    def evaluate(self, g, x, t, out, scope):
        p = x.get("Properties") or {}
        env = self.env
        P = lambda n, **k: self.pin(g, x, n, scope, **k)

        if t in ("Add", "Subtract", "Multiply", "Divide", "Max", "Min"):
            op = {"Add": "ADD", "Subtract": "SUBTRACT", "Multiply": "MULTIPLY", "Divide": "DIVIDE",
                  "Max": "MAXIMUM", "Min": "MINIMUM"}[t]
            if t == "Divide":
                return self.divide(P("A"), P("B"), label=x["Name"][18:])
            return self.binop(op, P("A"), P("B"), label=x["Name"][18:])
        if t == "Power":
            # UE's Power is pow(max(Base, 0), Exponent) (PositiveClampedPow, since 4.16): a negative
            # base gives 0, where Blender's Power squares it (a variant sprite's sphere mask, 1 - d / r
            # squared, came out 1 far from the sphere: its base look showed through)
            base, ex = P("Base", fallback=1.0), P("Exponent")
            if base.w == 1 and ex.w == 1:
                if not (base.const and float(base.s) >= 0.0):
                    base = self.math('MAXIMUM', base, self.const(0.0))
                return self.math('POWER', base, ex)
            if not (base.const and all(float(x) >= 0.0 for x in (base.s if isinstance(base.s, (tuple, list)) else (base.s,)))):
                base = self.binop('MAXIMUM', base, self.const(0.0))
            return self.vmath('POWER', base, ex, out_w=base.w)
        if t == "LinearInterpolate":
            return self.lerp(P("A"), P("B"), P("Alpha"))
        if t == "OneMinus":
            a = P("Input")
            return self.binop('SUBTRACT', self.const(1.0), a) if a.w == 1 else \
                self.vmath('SUBTRACT', self.const((1.0, 1.0, 1.0), a.w), a, out_w=a.w)
        if t == "Saturate":
            return self.saturate(P("Input"))
        if t in ("Abs", "Floor", "Ceil", "Frac"):
            return self.unary({"Abs": "ABSOLUTE", "Floor": "FLOOR", "Ceil": "CEIL", "Frac": "FRACTION"}[t], P("Input"))
        if t == "Sine":
            period = float(p.get("Period", 1.0))
            a = P("Input")
            return self.unary('SINE', self.binop('MULTIPLY', a, self.const(2 * math.pi / period)))
        if t == "SquareRoot":
            a = P("Input")
            return self.math('SQRT', a) if a.w == 1 else self.vmath('POWER', a, self.const(0.5), out_w=a.w)
        if t == "Normalize":
            return self.vmath('NORMALIZE', self.zero_z(P("VectorInput")), out_w=3)
        if t == "DotProduct":
            return self.vmath('DOT_PRODUCT', self.zero_z(P("A")), self.zero_z(P("B")))
        if t == "CrossProduct":
            return self.vmath('CROSS_PRODUCT', P("A"), P("B"), out_w=3)
        if t == "Distance":
            return self.vmath('DISTANCE', *self.flat(P("A"), P("B")))
        if t == "ComponentMask":
            idx = [i for i, k in enumerate("RGBA") if p.get(k)]
            return self.mask(P("Input"), idx)
        if t == "AppendVector":
            a, b = P("A"), P("B")
            parts = (self.comps(a)[:a.w] if a.w > 1 else [a]) + (self.comps(b)[:b.w] if b.w > 1 else [b])
            return self.combine(parts)
        if t == "Constant":
            return self.const(p.get("R", 0.0))
        if t == "Constant2Vector":
            return self.const((p.get("R", 0.0), p.get("G", 0.0)), 2)
        if t in ("Constant3Vector", "Constant4Vector"):
            c = p.get("Constant", {})
            if t == "Constant4Vector":
                return self.const((c.get("R", 0.0), c.get("G", 0.0), c.get("B", 0.0), c.get("A", 0.0)), 4)
            return self.const((c.get("R", 0.0), c.get("G", 0.0), c.get("B", 0.0)), 3)
        if t == "Step":
            y, xv = P("Y"), P("X")
            w = max(y.w, xv.w)
            if w == 1:
                return self.binop('SUBTRACT', self.const(1.0), self.math('LESS_THAN', xv, y))
            parts = [self.binop('SUBTRACT', self.const(1.0), self.math('LESS_THAN', a, b))
                     for a, b in zip(self.comps(xv), self.comps(y))][:w]
            return self.combine(parts)
        if t == "SmoothStep":
            return self.smoothstep(P("Min"), P("Max"), P("Value"))
        if t == "Rotator":
            uv = self.input(g, p.get("Coordinate"), scope, None) or env.uv(0)
            tm = self.input(g, p.get("Time"), scope, None) or env.time()
            ang = self.binop('MULTIPLY', tm, self.const(float(p.get("Speed", 0.25))))
            cx, cy = float(p.get("CenterX", 0.5)), float(p.get("CenterY", 0.5))
            u, v = self.comps(uv)[:2]
            du, dv = self.binop('SUBTRACT', u, self.const(cx)), self.binop('SUBTRACT', v, self.const(cy))
            c, s = self.math('COSINE', ang), self.math('SINE', ang)
            nu = self.binop('ADD', self.binop('SUBTRACT', self.binop('MULTIPLY', c, du),
                                              self.binop('MULTIPLY', s, dv)), self.const(cx))
            nv = self.binop('ADD', self.binop('ADD', self.binop('MULTIPLY', s, du),
                                              self.binop('MULTIPLY', c, dv)), self.const(cy))
            return self.combine([nu, nv])
        if t == "Time":
            return env.time()
        if t == "CloudSampleAttribute":
            # 0 Altitude, 1 AltitudeInLayer, 2 NormAltitudeInLayer, 3 ShadowSampleDistance
            return env.cloud_sample(out)
        if t == "VolumetricAdvancedMaterialInput":
            # the material's own Conservative Density (its VolumetricAdvancedMaterialOutput's pin):
            # UE evaluates it first (empty space skipping) and hands it back here
            vamo = next((y for y in g.o if T(y) == "VolumetricAdvancedMaterialOutput"), None)
            pin = ((vamo or {}).get("Properties") or {}).get("ConservativeDensity")
            if pin is None or not linked(pin):
                return self.const((1.0, 1.0, 1.0), 3)
            return self.input(g, pin, scope, self.const(1.0))
        if t == "CameraPositionWS":
            return env.camera_position()
        if t == "SphereMask":
            # UMaterialExpressionSphereMask::Compile: hardness in percent
            a, b = P("A"), P("B")
            radius = self.input(g, p.get("Radius"), scope, self.const(float(p.get("AttenuationRadius", 256.0))))
            hard = self.input(g, p.get("Hardness"), scope, self.const(float(p.get("HardnessPercent", 100.0))))
            d = self.vmath('LENGTH', self.vmath('SUBTRACT', *self.flat(a, b), out_w=3), out_w=1) if max(a.w, b.w) > 1 \
                else self.math('ABSOLUTE', self.binop('SUBTRACT', a, b))
            nd = self.binop('DIVIDE', d, self.math('MAXIMUM', radius, self.const(0.00001)))
            soft = self.binop('SUBTRACT', self.const(1.0), self.binop('MULTIPLY', hard, self.const(0.01)))
            inv = self.binop('DIVIDE', self.const(1.0), self.math('MAXIMUM', soft, self.const(0.00001)))
            return self.math('MULTIPLY', self.binop('SUBTRACT', self.const(1.0), nd), inv, clamp=True, label="SphereMask")
        if t == "InverseLinearInterpolate":
            a = self.input(g, p.get("A"), scope, self.const(float(p.get("ConstA", 0.0))))
            b = self.input(g, p.get("B"), scope, self.const(float(p.get("ConstB", 1.0))))
            v = self.input(g, p.get("Value"), scope, self.const(float(p.get("ConstValue", 0.0))))
            r = self.binop('DIVIDE', self.binop('SUBTRACT', v, a), self.binop('SUBTRACT', b, a))
            return self.saturate(r) if p.get("bClampResult") else r
        if t == "ConstantBiasScale":
            v = self.input(g, p.get("Input"), scope, self.const(0.0))
            return self.binop('MULTIPLY', self.binop('ADD', v, self.const(float(p.get("Bias", 1.0)))),
                              self.const(float(p.get("Scale", 0.5))))
        if t == "Arctangent2Fast" or t == "Arctangent2":
            return self.math('ARCTAN2', P("Y"), P("X"))
        if t == "Custom":
            return self.custom(g, x, scope, out)
        if t in ("TextureObject", "TextureObjectParameter"):
            tex = str((p.get("Texture") or {}).get("ObjectName", "")) if isinstance(p.get("Texture"), dict) \
                else str(p.get("Texture", ""))
            return Val(TexRef(self.tex_param(p, self.tex_key(p.get("Texture"))), "Volume" in tex), 0)
        if t == "TextureCoordinate":
            uv = env.uv(int(p.get("CoordinateIndex", 0)))
            ut, vt = float(p.get("UTiling", 1.0)), float(p.get("VTiling", 1.0))
            if ut != 1.0 or vt != 1.0:
                uv = self.vmath('MULTIPLY', uv, self.const((ut, vt, 0.0), 2), out_w=2)
            return uv
        if t == "VertexColor":
            rgb, a = env.vertex_color()
            return self.rgba_out(rgb, a, out)
        if t == "CameraVectorWS":
            return env.camera_vector()
        if t == "SkyAtmosphereLightDirection":
            return env.light_direction()
        if t == "SkyAtmosphereViewLuminance":
            d = self.input(g, p.get("WorldDirection"), scope, None)
            if d is None:
                d = self.vmath('SCALE', env.camera_vector(), self.const(-1.0), out_w=3)
            return env.view_luminance(d)
        if t == "SkyAtmosphereLightDiskLuminance":
            # the sun's disc: its light over the disc's solid angle where the view ray is within it
            # (UE also dims it by the atmosphere's transmittance, which the light's colour carries
            # at sunset); the disc is DiskAngularDiameterOverride degrees across, else the light's
            # default source angle (0.5357)
            diam = self.input(g, p.get("DiskAngularDiameterOverride"), scope, None)
            half = self.binop('MULTIPLY', diam, self.const(math.pi / 360.0)) if diam is not None \
                else self.const(0.5357 * math.pi / 360.0)
            view = self.vmath('SCALE', env.camera_vector(), self.const(-1.0), out_w=3)
            cos_view = self.vmath('DOT_PRODUCT', self.vmath('NORMALIZE', view, out_w=3),
                                  self.vmath('NORMALIZE', env.light_direction(), out_w=3))
            cos_half = self.math('COSINE', half)
            inside = self.math('GREATER_THAN', cos_view, cos_half)
            solid = self.binop('MULTIPLY', self.const(2.0 * math.pi), self.binop('SUBTRACT', self.const(1.0), cos_half))
            lum = self.vmath('SCALE', self.light_color(), self.binop('DIVIDE', inside, self.math('MAXIMUM', solid, self.const(1e-9))), out_w=3)
            return lum
        if t == "SkyAtmosphereAerialPerspective":
            # the atmosphere between the camera and a point (in-scattered light, transmittance): the
            # env's, else none
            pos = self.input(g, p.get("WorldPosition"), scope, None)
            if pos is None:
                pos = env.world_position(False)
            hook = getattr(env, "aerial_perspective", None)
            if hook is not None:
                rgb, a = hook(pos)
                return self.rgba_out(rgb, a, out)
            return self.rgba_out(self.stand_in("SkyAtmosphereAerialPerspective as none", self.const((0.0, 0.0, 0.0), 3)),
                                 self.const(1.0), out)
        if t == "SkyAtmosphereDistantLightScatteredLuminance":
            # the atmosphere's light far away (UE's DistantSkyLightLut, its mean luminance): the sky straight up
            return env.view_luminance(self.const((0.0, 0.0, 1.0), 3))
        if t == "WorldPosition":
            rel = "CameraRelative" in str(p.get("WorldPositionShaderOffset", ""))
            return env.world_position(rel)
        if t == "ActorPositionWS":
            return env.actor_position("CameraRelative" in str(p.get("OriginType", "")))
        if t == "CollectionParameter":
            if getattr(env, "asset_paths", False):
                return env.collection(p.get("ParameterName"), self.tex_key(p.get("Collection")))
            return env.collection(p.get("ParameterName"))
        if t == "ScalarParameter":
            v = env.scalar(p.get("ParameterName"), float(p.get("DefaultValue", 0.0)))
            if p.get("bUseCustomPrimitiveData") and hasattr(env, "primitive_data"):
                # UE's Custom Primitive Data: the placed component's own value
                v = env.primitive_data(v, int(p.get("PrimitiveDataIndex") or 0), 1)
            return v
        if t in ("VectorParameter", "DoubleVectorParameter"):
            # no DefaultValue: the class default (0, 0, 0, 0), which cooking
            # leaves out (no dumped graph stores it; (0, 0, 0, 1) is stored).
            # A double vector's is X Y Z W
            d = p.get("DefaultValue", {})
            rgba = (d.get("R", d.get("X", 0.0)), d.get("G", d.get("Y", 0.0)), d.get("B", d.get("Z", 0.0)),
                    d.get("A", d.get("W", 0.0)))
            rgb, a = env.vector(p.get("ParameterName"), rgba)
            if p.get("bUseCustomPrimitiveData") and hasattr(env, "primitive_data"):
                i = int(p.get("PrimitiveDataIndex") or 0)
                rgb, a = env.primitive_data(rgb, i, 3), env.primitive_data(a, i + 3, 1)
            return self.rgba_out(rgb, a, out)
        if t in ("TextureSample", "TextureSampleParameter2D", "TextureSampleParameterCube"):
            tex = (p.get("Texture") or {}).get("ObjectName", "") if isinstance(p.get("Texture"), dict) else str(p.get("Texture", ""))
            tname = self.tex_param(p, self.tex_key(p.get("Texture")))
            coords = self.input(g, p.get("Coordinates"), scope, None)
            ref = self.input(g, p.get("TextureObject"), scope, None)
            volume = "VolumeTexture" in tex
            if ref is not None and isinstance(ref.s, TexRef):
                tname, volume = ref.s.name, ref.s.volume or volume
            if volume:
                return self.sample_volume(tname, coords, out)
            if "TextureCube" in tex:
                return self.sample_cube(tname, coords if coords is not None else self.reflection(), out)
            if coords is None:
                coords = env.uv(0)
            # its own sampler (the default source) filters and addresses as the texture says; a
            # shared sampler (world group settings) wraps or clamps as its group does
            src = str(p.get("SamplerSource", "")).split("::")[-1]
            own = src in ("", "SSM_FromTextureAsset")
            address = None if own else ("Clamp", "Clamp") if "Clamp" in src or "Terrain" in src else ("Wrap", "Wrap")
            return self.sample(tname, coords, out, p.get("SamplerType", ""), own, address)
        if t == "Convert":
            # UE 5's component shuffle: typed outputs, filled from input
            # components by explicit mappings, defaults elsewhere
            width = {"Scalar": 1, "Vector2": 2, "Vector3": 3, "Vector4": 4}
            ins = []
            for ci in p.get("ConvertInputs", []):
                d = ci.get("DefaultValue", {})
                dv = self.const((d.get("R", 0.0), d.get("G", 0.0), d.get("B", 0.0)),
                                width.get(ci.get("Type", "").split("::")[-1], 1))
                v = self.input(g, ci.get("ExpressionInput"), scope, dv)
                ins.append(self.comps(v) if v.w > 1 else [v, v, v])
            outs = []
            for co in p.get("ConvertOutputs", []):
                d = co.get("DefaultValue", {})
                outs.append([self.const(d.get(k, 0.0)) for k in "RGB"][:width.get(co.get("Type", "").split("::")[-1], 1)])
            for mp in p.get("ConvertMappings", []):
                oi, oc = mp.get("OutputIndex", 0), mp.get("OutputComponentIndex", 0)
                ii, ic = mp.get("InputIndex", 0), mp.get("InputComponentIndex", 0)
                if oi < len(outs) and oc < len(outs[oi]) and ii < len(ins) and ic < 3:
                    outs[oi][oc] = ins[ii][ic]
            sel = outs[min(out, len(outs) - 1)] if outs else [self.const(0.0)]
            return self.combine(sel)
        if t == "FunctionInput" and scope.get("_fn") is not None:
            return scope["_fn"].ue_input(x)
        if t == "FunctionInput":
            bound = scope.get(p.get("Id"))
            if isinstance(bound, _Lazy):
                bound = bound.get(self)
            if bound is not None:
                return bound
            if p.get("InputType") == ATTRIBUTES_INPUT:
                pv = self.input(g, p.get("Preview"), scope, None)
                return pv if pv is not None and isinstance(pv.s, Attrs) else Val(Attrs(), 0)
            if p.get("bUsePreviewValueAsDefault"):
                pv = self.input(g, p.get("Preview"), scope, None)
                if pv is not None:
                    return pv
                v = p.get("PreviewValue", {})
                return self.const((v.get("X", 0.0), v.get("Y", 0.0), v.get("Z", 0.0)),
                                  {"EFunctionInputType::FunctionInput_Scalar": 1,
                                   "EFunctionInputType::FunctionInput_Vector2": 2}.get(p.get("InputType"), 3)) \
                    if p.get("InputType") != "EFunctionInputType::FunctionInput_Scalar" else self.const(v.get("X", 0.0))
            return self.const(0.0)
        if t == "FunctionOutput":
            return self.input(g, p.get("A"), scope, self.const(0.0))
        if t == "MaterialFunctionCall":
            return self.call(g, x, out, scope)
        for handler in (self.evaluate_static, self.evaluate_attributes, self.evaluate_math, self.evaluate_geometry,
                        self.evaluate_renderer):
            v = handler(g, x, t, out, scope, p, P)
            if v is not None:
                return v
        self.warnings.append("unsupported %s (%s) -> 0" % (t, x["Name"]))
        return self.const(0.0)

    # ------------------------------------------------------ compile time
    # Static bools never become nodes: UE picks the branch while compiling,
    # and so does the translator.
    def _hook(self, name, fallback, *args):
        """env.<name>(*args) when the env has it and answers, else fallback()."""
        f = getattr(self.env, name, None)
        if f is not None:
            v = f(*args)
            if v is not None:
                return v
        return fallback()

    def tex_key(self, prop):
        """A texture (or collection) reference as the env names it: the object
        path when it asks for paths (env.asset_paths), else the name."""
        if isinstance(prop, dict):
            name, path = _inner(str(prop.get("ObjectName", ""))), str(prop.get("ObjectPath", ""))
        else:
            name, path = _inner(str(prop or "")), ""
        if getattr(self.env, "asset_paths", False) and path:
            return object_path(path, name)
        return name

    def tex_param(self, p, key):
        """The texture a texture parameter holds: the env's (an instance
        override), else its default. The key remembers the parameter
        (TexKey.param), so the image node sampling it can say which it is."""
        name = p.get("ParameterName")
        if name is None:
            return key
        got = self._hook("texture_parameter", lambda: key, name, key)
        return TexKey.of(got, name) if isinstance(got, str) else got

    def shared(self, key, make):
        """One node (or value) per tree for a Blender input read in many places."""
        if key not in self._shared:
            self._shared[key] = make()
        return self._shared[key]

    def static_switch(self, name, default):
        return bool(self._hook("static_switch", lambda: default, name, default))

    def static_bool(self, g, ref, scope):
        """What a static bool input compiles to, or None when nothing is linked
        or the expression isn't a compile-time value."""
        if not linked(ref):
            return None
        x = g.by.get(g.key(ref))
        if x is None:
            return None
        t, p = T(x), x.get("Properties") or {}
        if t in ("Reroute", "NamedRerouteDeclaration"):
            return self.static_bool(g, p.get("Input"), scope)
        if t == "NamedRerouteUsage":
            decl = self.declaration(g, p)
            return self.static_bool(g, decl["Properties"].get("Input"), scope) if decl else None
        if t == "StaticBool":
            return bool(p.get("Value", False))
        if t == "StaticBoolParameter":
            return self.static_switch(p.get("ParameterName"), bool(p.get("DefaultValue", False)))
        if t in ("StaticSwitch", "StaticSwitchParameter"):
            return self.static_bool(g, p.get("A" if self.switch_value(g, x, scope) else "B"), scope)
        if t in COMPILE_SWITCHES or t == "LandscapeLayerSwitch":
            return self.static_bool(g, self.switch_pin(x), scope)
        if t == "FunctionInput":
            return self.static_input(g, x, scope)
        if t == "MaterialFunctionCall":
            found = self.function_graph(x)
            if found is None:
                return None
            fg = found[1]
            fo = self.function_output(fg, p.get("FunctionOutputs", []), ref.get("OutputIndex", 0) or 0)
            if fo is None:
                return None
            sub = {fi.get("ExpressionInputId"): _Lazy(g, fi.get("Input"), scope, self.section)
                   for fi in p.get("FunctionInputs", [])}
            sub["_id"] = ("static", id(x), g.path, scope.get("_id", 0))
            return self.static_bool(fg, fo["Properties"].get("A"), sub)
        return None

    def static_input(self, g, x, scope):
        """A static bool FunctionInput: what the call site binds, else its preview."""
        p = x.get("Properties") or {}
        fid = p.get("Id")
        v = None
        fn = scope.get("_fn")
        if fn is not None:
            v = fn.statics.get(fid)
        else:
            bound = scope.get(fid)
            if isinstance(bound, _Lazy):
                v = self.static_bool(bound.g, bound.ref, bound.scope)
        if v is None:
            v = self.static_bool(g, p.get("Preview"), scope)
        if v is None:
            v = float((p.get("PreviewValue") or {}).get("X", 0.0)) != 0.0
        return v

    def switch_value(self, g, x, scope):
        """True for a StaticSwitch(Parameter)'s A branch."""
        p = x.get("Properties") or {}
        if T(x) == "StaticSwitchParameter":
            return self.static_switch(p.get("ParameterName"), bool(p.get("DefaultValue", False)))
        v = self.static_bool(g, p.get("Value"), scope)
        if v is None:
            if linked(p.get("Value")):
                self.warnings.append("static switch %s: value isn't static, took its default" % x.get("Name"))
            return bool(p.get("DefaultValue", False))
        return v

    def switch_pin(self, x):
        """The input a compile-time switch compiles (COMPILE_SWITCHES)."""
        p = x.get("Properties") or {}
        t = T(x)
        if t == "LandscapeLayerSwitch":
            used = self._hook("landscape_layer", lambda: True, p.get("ParameterName"))
            return p.get("LayerUsed" if used else "LayerNotUsed")
        prefs = COMPILE_SWITCHES[t]
        for k in prefs:
            if linked(p.get(k)):
                return p[k]
        return p.get(prefs[-1])

    def function_statics(self, fg, ins):
        """Each static bool input of a function at one call site: what the
        caller links (evaluated at compile time), else the input's preview."""
        out = {}
        for fid, fi in fg.inputs.items():
            fp = fi.get("Properties") or {}
            if fp.get("InputType") != STATIC_BOOL_INPUT:
                continue
            lazy = ins.get(fid)
            v = self.static_bool(lazy.g, lazy.ref, lazy.scope) if lazy is not None else None
            if v is None and lazy is not None and linked(lazy.ref):
                self.warnings.append("static input %s of %s isn't static, took its preview"
                                     % (fp.get("InputName"), fg.name))
            if v is None:
                v = self.static_bool(fg, fp.get("Preview"), {})
            if v is None:
                v = float((fp.get("PreviewValue") or {}).get("X", 0.0)) != 0.0
            out[fid] = v
        return out

    def variant_label(self, fname, fg, statics):
        """A function's group name for one set of static values: the plain
        name at its defaults, else the inputs that differ ("Foo [+UseX -Y]")."""
        base = section_name(fname)
        dflt = self.function_statics(fg, {}) if statics else {}
        diff = ["%s%s" % ("+" if v else "-", (fg.inputs[f].get("Properties") or {}).get("InputName", "?"))
                for f, v in sorted(statics.items(), key=lambda kv: str(kv[0])) if v != dflt.get(f)]
        label = "%s [%s]" % (base, " ".join(diff)) if diff else base
        prefix = getattr(self.env, "function_prefix", FunctionTree.PREFIX)
        taken = {ft.tree.name for ft in self.functions.values()}
        if not statics or not diff:
            # a plain function whose name another function already has
            n = 2
            while prefix + label in taken:
                label = "%s %d" % (base, n)
                n += 1
            return label
        if len((prefix + label).encode("utf-8")) > 63 or prefix + label in taken:
            n = 2
            while "%s%s [v%d]" % (prefix, base, n) in taken:
                n += 1
            label = "%s [v%d]" % (base, n)
        return label

    def evaluate_static(self, g, x, t, out, scope, p, P):
        if t in ("StaticSwitch", "StaticSwitchParameter"):
            pin = "A" if self.switch_value(g, x, scope) else "B"
            return self.input(g, p.get(pin), scope, self.const(0.0))
        if t in ("StaticBool", "StaticBoolParameter"):
            v = bool(p.get("Value", False)) if t == "StaticBool" else \
                self.static_switch(p.get("ParameterName"), bool(p.get("DefaultValue", False)))
            return self.const(1.0 if v else 0.0)
        if t in COMPILE_SWITCHES or t == "LandscapeLayerSwitch":
            return self.input(g, self.switch_pin(x), scope, self.const(0.0))
        if t == "StaticComponentMaskParameter":
            dflt = tuple(bool(p.get("Default" + c, False)) for c in "RGBA")
            name = p.get("ParameterName")
            v = self.input(g, p.get("Input"), scope, self.const(0.0))
            m = self._hook("static_mask", lambda: None, name, dflt)
            if m is None:
                # the instance doesn't say (a cooked instance keeps no mask
                # choice: it's editor-only data): the env may tell from the
                # texture behind it, else the default
                m = self._hook("guess_mask", lambda: dflt, name, dflt, v)
            idx = [i for i, on in enumerate(m) if on]
            return self.mask(v, idx) if idx else self.const(0.0)
        if t == "ChannelMaskParameter":
            # a vector parameter (one-hot by default) dotted with the input
            ch = str(p.get("MaskChannel", "Red")).split("::")[-1]
            i = {"Red": 0, "Green": 1, "Blue": 2, "Alpha": 3}.get(ch, 0)
            rgb, a = self.env.vector(p.get("ParameterName"), tuple(1.0 if k == i else 0.0 for k in range(4)))
            v = self.input(g, p.get("Input"), scope, self.const(0.0))
            v3 = self.combine([v, v, v]) if v.w == 1 else self.zero_z(Val(v.s, min(v.w, 3)))
            d = self.vmath('DOT_PRODUCT', v3, rgb)
            if v.w in (1, 4):
                d = self.binop('ADD', d, self.binop('MULTIPLY', self.alpha(v), a))
            return d
        if t == "Switch":
            # floor(SwitchValue) picks an input; out of range, Default
            sv = self.input(g, p.get("SwitchValue"), scope, self.const(float(p.get("ConstSwitchValue", 0.0))))
            result = self.input(g, p.get("Default"), scope, self.const(float(p.get("ConstDefault", 0.0))))
            items = p.get("Inputs") or []
            if sv.const:
                i = int(math.floor(sv.s if sv.w == 1 else sv.s[0]))
                return self.input(g, items[i].get("Input"), scope, result) if 0 <= i < len(items) else result
            idx = self.math('FLOOR', self.mask(sv, [0]))
            for i, it in enumerate(items):
                v = self.input(g, it.get("Input"), scope, None)
                if v is not None:
                    hit = self.math('COMPARE', idx, self.const(float(i)), self.const(0.5))
                    result = self.lerp(result, v, hit, label="switch %d" % i)
            return result
        return None

    # ---------------------------------------------------- attributes
    def deferred(self, fn):
        """fn, to run later in this translator and the frame it'd run in now
        (an attribute's nodes are made when something reads it)."""
        section = list(self.section)

        def run():
            prev = self.activate()
            saved = self.section
            self.section = section
            try:
                return fn()
            finally:
                self.section = saved
                prev.activate()
        return run

    @staticmethod
    def attribute_value(v, name):
        """An attribute's value. UE compiles Material Attributes one property
        at a time, so Material Attributes wired into an attribute's pin give
        their own attribute of that name."""
        return v.s.get(name) if isinstance(v.s, Attrs) else v

    def passthrough(self, g, ref, scope):
        """{attribute: input id} for the attributes a Material Attributes value
        carries unchanged from one of its function's Material Attributes
        inputs (through Set nodes that don't touch them, reroutes, switches).
        Worked out without making nodes."""
        if not linked(ref):
            return {}
        x = g.by.get(g.key(ref))
        if x is None:
            return {}
        t, p = T(x), x.get("Properties") or {}
        if t in ("Reroute", "NamedRerouteDeclaration"):
            return self.passthrough(g, p.get("Input"), scope)
        if t == "NamedRerouteUsage":
            decl = self.declaration(g, p)
            return self.passthrough(g, decl["Properties"].get("Input"), scope) if decl else {}
        if t in ("StaticSwitch", "StaticSwitchParameter"):
            return self.passthrough(g, p.get("A" if self.switch_value(g, x, scope) else "B"), scope)
        if t in COMPILE_SWITCHES:
            return self.passthrough(g, self.switch_pin(x), scope)
        if t == "FunctionInput" and p.get("InputType") == ATTRIBUTES_INPUT and scope.get("_fn") is not None:
            return {a: p.get("Id") for a in self.carried}
        if t == "GetMaterialAttributes" and not (ref.get("OutputIndex") or 0):
            return self.passthrough(g, p.get("MaterialAttributes"), scope)
        if t == "SetMaterialAttributes":
            ins = p.get("Inputs") or []
            base = self.passthrough(g, ins[0], scope) if ins else {}
            for k, guid in enumerate(p.get("AttributeSetTypes") or []):
                r = ins[k + 1] if k + 1 < len(ins) else None
                if linked(r):
                    name = attribute_name(guid, r.get("InputName"))
                    if self.attribute_source(g, r, scope, name) != base.get(name):
                        base.pop(name, None)
            return base
        if t == "BlendMaterialAttributes":
            # UseA / UseB keep one side's attribute; a blend of the same
            # attribute with itself is that attribute
            pa, pb = self.passthrough(g, p.get("A"), scope), self.passthrough(g, p.get("B"), scope)
            mode = lambda k: str(p.get(k, "EMaterialAttributeBlend::Blend")).split("::")[-1]
            out = {}
            for a in self.carried:
                m = mode("VertexAttributeBlendType" if a in VERTEX_ATTRIBUTES else "PixelAttributeBlendType")
                src = pa.get(a) if m == "UseA" else pb.get(a) if m == "UseB" else \
                    (pa.get(a) if pa.get(a) is not None and pa.get(a) == pb.get(a) else None)
                if src is not None:
                    out[a] = src
            return out
        if t == "MaterialFunctionCall":
            # through a function: what it passes from its own inputs, mapped
            # back to what this call links there
            found = self.function_graph(x)
            if found is None:
                return {}
            fg = found[1]
            fo = self.function_output(fg, p.get("FunctionOutputs", []), ref.get("OutputIndex") or 0)
            if fo is None:
                return {}
            ins = {fi.get("ExpressionInputId"): _Lazy(g, fi.get("Input"), scope, self.section)
                   for fi in p.get("FunctionInputs", [])}
            inner = {"_fn": _Statics(self.function_statics(fg, ins)), "_id": ("pass", id(x))}
            out, mine = {}, {}
            for a, fid in self.passthrough(fg, fo["Properties"].get("A"), inner).items():
                lazy = ins.get(fid)
                if lazy is None or not linked(lazy.ref):
                    continue
                if fid not in mine:
                    mine[fid] = self.passthrough(g, lazy.ref, scope)
                if a in mine[fid]:
                    out[a] = mine[fid][a]
            return out
        if t == "MakeMaterialAttributes":
            # Make(Break(input)...): an attribute wired back to its own pin
            out = {}
            for pin, r in p.items():
                a = MAKE_PINS.get(pin)
                if a in self.carried and linked(r):
                    src = self.attribute_source(g, r, scope, a)
                    if src is not None:
                        out[a] = src
            return out
        return {}

    def attribute_source(self, g, ref, scope, name):
        """The input id whose attribute `name` a value is, unchanged (a Break
        or Get output of it, through reroutes), or None."""
        if not linked(ref):
            return None
        x = g.by.get(g.key(ref))
        if x is None:
            return None
        t, p = T(x), x.get("Properties") or {}
        out = ref.get("OutputIndex") or 0
        if t in ("Reroute", "NamedRerouteDeclaration"):
            return self.attribute_source(g, p.get("Input"), scope, name)
        if t == "NamedRerouteUsage":
            decl = self.declaration(g, p)
            return self.attribute_source(g, decl["Properties"].get("Input"), scope, name) if decl else None
        if t == "BreakMaterialAttributes" and out < len(BREAK_ORDER) and BREAK_ORDER[out] == name:
            return self.passthrough(g, p.get("MaterialAttributes"), scope).get(name)
        if t == "GetMaterialAttributes" and out > 0:
            types = p.get("AttributeGetTypes") or []
            outs = p.get("Outputs") or []
            label = outs[out].get("OutputName") if out < len(outs) and isinstance(outs[out], dict) else None
            if out - 1 < len(types) and attribute_name(types[out - 1], label) == name:
                return self.passthrough(g, p.get("MaterialAttributes"), scope).get(name)
        return None

    def attrs(self, g, ref, scope):
        """A Material Attributes input as Attrs (UE's defaults when unlinked)."""
        v = self.input(g, ref, scope, None)
        return v.s if v is not None and isinstance(v.s, Attrs) else Attrs()

    def evaluate_attributes(self, g, x, t, out, scope, p, P):
        if t == "MakeMaterialAttributes":
            thunks = {}
            for pin, ref in p.items():
                name = MAKE_PINS.get(pin)
                if name and linked(ref):
                    thunks[name] = self.deferred(lambda ref=ref, name=name: self.attribute_value(self.input(
                        g, ref, scope, attribute_default(name)), name))
            return Val(Attrs(None, thunks), 0)
        if t == "SetMaterialAttributes":
            ins = p.get("Inputs") or []
            base = self.attrs(g, ins[0], scope) if ins else Attrs()
            thunks = {}
            for k, guid in enumerate(p.get("AttributeSetTypes") or []):
                ref = ins[k + 1] if k + 1 < len(ins) else None
                if linked(ref):
                    name = attribute_name(guid, ref.get("InputName"))
                    thunks[name] = self.deferred(lambda ref=ref, name=name: self.attribute_value(self.input(
                        g, ref, scope, attribute_default(name)), name))
            return Val(Attrs(base, thunks), 0)
        if t == "GetMaterialAttributes":
            a = self.attrs(g, p.get("MaterialAttributes"), scope)
            if out == 0:
                return Val(a, 0)
            types = p.get("AttributeGetTypes") or []
            if out - 1 >= len(types):
                return self.const(0.0)
            outs = p.get("Outputs") or []
            label = outs[out].get("OutputName") if out < len(outs) and isinstance(outs[out], dict) else None
            return a.get(attribute_name(types[out - 1], label))
        if t == "BreakMaterialAttributes":
            a = self.attrs(g, p.get("MaterialAttributes"), scope)
            return a.get(BREAK_ORDER[out]) if out < len(BREAK_ORDER) else self.const(0.0)
        if t == "BlendMaterialAttributes":
            a = self.attrs(g, p.get("A"), scope)
            b = self.attrs(g, p.get("B"), scope)
            alpha = []

            def get_alpha():
                if not alpha:
                    alpha.append(self.mask(self.input(g, p.get("Alpha"), scope, self.const(0.0)), [0]))
                return alpha[0]
            mode = lambda k: str(p.get(k, "EMaterialAttributeBlend::Blend")).split("::")[-1]
            return Val(BlendAttrs(self, a, b, self.deferred(get_alpha),
                                  mode("PixelAttributeBlendType"), mode("VertexAttributeBlendType")), 0)
        if t == "ShadingModel":
            sm = str(p.get("ShadingModel", "EMaterialShadingModel::MSM_DefaultLit")).split("::")[-1]
            return self.const(float(SHADING_MODELS.index(sm)) if sm in SHADING_MODELS else 1.0)
        return None

    # ------------------------------------------------------------- maths
    def select(self, cond, if_false, if_true, label="if"):
        """cond (0 or 1) ? if_true : if_false."""
        if cond.const:
            return if_true if cond.s else if_false
        return self.lerp(if_false, if_true, cond, label=label)

    def _attrs_op(self, fn, *vals):
        """fn over Material Attributes, attribute by attribute."""
        return Val(MapAttrs(self, fn, [as_attrs(v) for v in vals]), 0)

    def percomp(self, op, v, b=None):
        """A Math operation component by component (Vector Math lacks it)."""
        if v.w == 1:
            return self.math(op, v, b)
        parts = [self.math(op, c, b) for c in self.comps(v)[:v.w]]
        r = self.combine(parts)
        if v.w == 4:
            r = self.with_alpha(r, self.math(op, self.alpha(v), b))
        return r

    def periodic(self, v, period):
        """UE's Period pin (Sine, Cosine, Tangent): x * 2 pi / period, if > 0."""
        return self.binop('MULTIPLY', v, self.const(2 * math.pi / period)) if period > 0 else v

    def as3(self, v):
        """A value as a float3 (float1 broadcast, float2 z = 0, alpha dropped)."""
        if v.w == 1:
            return self.combine([v, v, v])
        return self.zero_z(Val(v.s, min(v.w, 3)))

    def evaluate_math(self, g, x, t, out, scope, p, P):
        if t == "Clamp":
            v = P("Input")
            mn = self.input(g, p.get("Min"), scope, self.const(float(p.get("MinDefault", 0.0))))
            mx = self.input(g, p.get("Max"), scope, self.const(float(p.get("MaxDefault", 1.0))))
            mode = str(p.get("ClampMode", "CMODE_Clamp")).split("::")[-1]
            if mode != "CMODE_ClampMax":
                v = self.binop('MAXIMUM', v, mn, label="clamp min")
            if mode != "CMODE_ClampMin":
                v = self.binop('MINIMUM', v, mx, label="clamp max")
            return v
        if t == "If":
            # HLSL: A >= B ? Greater : Less; with an Equals pin,
            # |A - B| > threshold ? that : Equals
            a = self.mask(P("A"), [0])
            b = self.mask(self.input(g, p.get("B"), scope, self.const(float(p.get("ConstB", 0.0)))), [0])
            # a branch that culls (a NaN) isn't taken: the others stand in for it
            pins = {k: p.get(k) for k in ("AGreaterThanB", "ALessThanB", "AEqualsB")}
            culls = {k for k, r in pins.items() if self._culls(g, r)}
            if culls and len(culls) < sum(1 for r in pins.values() if linked(r)):
                keep = next(k for k in ("AEqualsB", "ALessThanB", "AGreaterThanB") if k not in culls and linked(pins[k]))
                for k in culls:
                    pins[k] = pins[keep]
                p = dict(p, **pins)
            gt = self.input(g, p.get("AGreaterThanB"), scope, self.const(0.0))
            lt = self.input(g, p.get("ALessThanB"), scope, self.const(0.0))
            eq = self.input(g, p.get("AEqualsB"), scope, None)
            if a.const and b.const:
                ge = self.const(1.0 if a.s >= b.s else 0.0)
            else:
                ge = self.binop('SUBTRACT', self.const(1.0), self.math('LESS_THAN', a, b), label="A >= B")
            v = self.select(ge, lt, gt)
            if eq is not None:
                thr = float(p.get("EqualsThreshold", 0.00001))
                if a.const and b.const:
                    far = self.const(1.0 if abs(a.s - b.s) > thr else 0.0)
                else:
                    far = self.math('GREATER_THAN', self.math('ABSOLUTE', self.binop('SUBTRACT', a, b)),
                                    self.const(thr), label="A != B")
                v = self.select(far, eq, v)
            return v
        if t == "IfThenElse":
            c = self.static_bool(g, p.get("Condition"), scope)
            if c is not None:
                return self.input(g, p.get("True" if c else "False"), scope, self.const(0.0))
            cv = self.mask(self.input(g, p.get("Condition"), scope, self.const(0.0)), [0])
            on = cv if cv.const else self.binop('SUBTRACT', self.const(1.0),
                                                self.math('COMPARE', cv, self.const(0.0), self.const(0.0)))
            if on.const:
                on = self.const(1.0 if on.s else 0.0)
            return self.select(on, self.input(g, p.get("False"), scope, self.const(0.0)),
                               self.input(g, p.get("True"), scope, self.const(0.0)))
        if t in ("Fmod", "Modulo"):
            # HLSL fmod: truncated, the sign of A (Blender's Modulo)
            return self.binop('MODULO', P("A"), P("B"))
        if t == "Cosine":
            return self.unary('COSINE', self.periodic(P("Input"), float(p.get("Period", 1.0))))
        if t == "Tangent":
            return self.percomp('TANGENT', self.periodic(P("Input"), float(p.get("Period", 1.0))))
        if t in ("Arcsine", "ArcsineFast", "Arccosine", "ArccosineFast", "Arctangent", "ArctangentFast"):
            op = {"Arcs": "ARCSINE", "Arcc": "ARCCOSINE", "Arct": "ARCTANGENT"}[t[:4]]
            return self.percomp(op, P("Input"))
        if t in ("Round", "Sign"):
            return self.unary(t.upper(), P("Input"))
        if t == "Truncate":
            return self.percomp('TRUNC', P("Input"))
        if t == "TruncateLWC":
            return P("Input")
        if t in ("Exponential", "Exponential2"):
            v = P("Input")
            return self.percomp('EXPONENT', v) if t == "Exponential" else \
                self.percomp('POWER', self.const(2.0), v) if v.w == 1 else \
                self.vmath('POWER', self.const((2.0, 2.0, 2.0), v.w), v, out_w=v.w)
        if t in ("Logarithm", "Logarithm2", "Logarithm10"):
            v = self.input(g, p.get("X") if "X" in p else p.get("Input"), scope, self.const(1.0))
            base = {"Logarithm": math.e, "Logarithm2": 2.0, "Logarithm10": 10.0}[t]
            return self.percomp('LOGARITHM', v, self.const(base))
        if t == "Length":
            v = P("Input")
            if v.w == 1:
                return self.math('ABSOLUTE', v)
            n = self.vmath('LENGTH', self.zero_z(Val(v.s, min(v.w, 3))))
            if v.w == 4:
                n = self.math('SQRT', self.binop('ADD', self.binop('MULTIPLY', n, n),
                                                 self.binop('MULTIPLY', self.alpha(v), self.alpha(v))))
            return n
        if t == "Desaturation":
            c = self.as3(P("Input"))
            lf = p.get("LuminanceFactors") or {}
            lum = (lf.get("R", 0.3), lf.get("G", 0.59), lf.get("B", 0.11))
            grey = self.vmath('DOT_PRODUCT', c, self.const(lum, 3), label="luminance")
            fr = self.input(g, p.get("Fraction"), scope, None)
            return grey if fr is None else self.lerp(c, grey, fr, label="desaturate")
        if t == "Panner":
            uv = self.input(g, p.get("Coordinate"), scope, None) or self.env.uv(int(p.get("ConstCoordinate", 0)))
            tm = self.input(g, p.get("Time"), scope, None) or self.env.time()
            sp = self.input(g, p.get("Speed"), scope, None)
            if sp is not None:
                sx, sy = self.mask(sp, [0]), self.mask(sp, [1])
            else:
                sx, sy = self.const(float(p.get("SpeedX", 0.0))), self.const(float(p.get("SpeedY", 0.0)))
            ax, ay = self.binop('MULTIPLY', tm, sx), self.binop('MULTIPLY', tm, sy)
            if p.get("bFractionalPart"):
                ax, ay = self.math('FRACT', ax), self.math('FRACT', ay)
            return self.binop('ADD', self.combine([ax, ay]), uv, label="panner")
        if t == "Fresnel":
            # pow(max(|1 - max(0, N . C)|, 1e-4), E) * (1 - F0) + F0
            n = self.input(g, p.get("Normal"), scope, None) or self.pixel_normal()
            d = self.math('MAXIMUM', self.vmath('DOT_PRODUCT', self.as3(n), self.env.camera_vector()), self.const(0.0))
            base = self.math('MAXIMUM', self.math('ABSOLUTE', self.binop('SUBTRACT', self.const(1.0), d)),
                             self.const(0.0001))
            ex = self.mask(self.input(g, p.get("ExponentIn"), scope, self.const(float(p.get("Exponent", 5.0)))), [0])
            f0 = self.input(g, p.get("BaseReflectFractionIn"), scope,
                            self.const(float(p.get("BaseReflectFraction", 0.04))))
            pw = self.math('POWER', base, ex, label="fresnel")
            return self.binop('ADD', self.binop('MULTIPLY', pw, self.binop('SUBTRACT', self.const(1.0), f0)), f0)
        if t == "RotateAboutAxis":
            # UE's RotateAboutAxis (Common.ush): the offset to the rotated position
            axis = self.as3(self.input(g, p.get("NormalizedRotationAxis"), scope, self.const((0.0, 0.0, 1.0), 3)))
            ang = self.periodic(self.mask(self.input(g, p.get("RotationAngle"), scope, self.const(0.0)), [0]),
                                float(p.get("Period", 1.0)))
            pivot = self.as3(self.input(g, p.get("PivotPoint"), scope, self.const((0.0, 0.0, 0.0), 3)))
            pos = self.as3(self.input(g, p.get("Position"), scope, self.const((0.0, 0.0, 0.0), 3)))
            along = self.vmath('DOT_PRODUCT', axis, self.vmath('SUBTRACT', pos, pivot, out_w=3))
            closest = self.vmath('ADD', pivot, self.vmath('SCALE', axis, along, out_w=3), out_w=3)
            u = self.vmath('SUBTRACT', pos, closest, out_w=3)
            v = self.vmath('CROSS_PRODUCT', axis, u, out_w=3)
            r = self.vmath('ADD', self.vmath('SCALE', u, self.math('COSINE', ang), out_w=3),
                           self.vmath('SCALE', v, self.math('SINE', ang), out_w=3), out_w=3)
            return self.vmath('SUBTRACT', self.vmath('ADD', closest, r, out_w=3), pos, label="rotate about axis", out_w=3)
        if t == "DeriveNormalZ":
            xy = P("InXY")
            nx, ny = self.comps(xy)[:2]
            dot = self.binop('ADD', self.binop('MULTIPLY', nx, nx), self.binop('MULTIPLY', ny, ny))
            return self.combine([nx, ny, self.math('SQRT', self.saturate(self.binop('SUBTRACT', self.const(1.0), dot)))])
        if t == "BumpOffset":
            uv = self.input(g, p.get("Coordinate"), scope, None) or self.env.uv(int(p.get("ConstCoordinate", 0)))
            h = self.mask(self.input(g, p.get("Height"), scope, self.const(0.0)), [0])
            ratio = self.input(g, p.get("HeightRatioInput"), scope, None)
            ratio = self.const(float(p.get("HeightRatio", 0.05))) if ratio is None else self.mask(ratio, [0])
            ref = float(p.get("ReferencePlane", 0.5))
            off = self.binop('SUBTRACT', self.binop('MULTIPLY', ratio, h), self.binop('MULTIPLY', ratio, self.const(ref)))
            cam = self.comps(self.transform(self.env.camera_vector(), "world", "tangent"))
            return self.binop('ADD', self.binop('MULTIPLY', self.combine(cam[:2]), off), uv, label="bump offset")
        if t in ("HsvToRgb", "RgbToHsv"):
            v = P("Input")
            if t == "RgbToHsv":
                n = self.node("ShaderNodeSeparateColor", "RGB to HSV", mode='HSV')
                self.link(self.as3(v), n.inputs[0])
                r = self.combine([Val(n.outputs[i], 1) for i in range(3)])
            else:
                n = self.node("ShaderNodeCombineColor", "HSV to RGB", mode='HSV')
                for i, c in enumerate(self.comps(v)):
                    self.link(c, n.inputs[i])
                r = Val(n.outputs[0], 3)
            return self.with_alpha(r, self.alpha(v)) if v.w == 4 else r
        if t == "BlackBody":
            n = self.node("ShaderNodeBlackbody", "black body")
            self.link(self.mask(P("Temp"), [0]), n.inputs[0])
            return Val(n.outputs[0], 3)
        if t == "MaterialXRemap":
            v = P("Input")
            il = self.input(g, p.get("InputLow"), scope, self.const(float(p.get("InputLowDefault", 0.0))))
            ih = self.input(g, p.get("InputHigh"), scope, self.const(float(p.get("InputHighDefault", 1.0))))
            tl = self.input(g, p.get("TargetLow"), scope, self.const(float(p.get("TargetLowDefault", 0.0))))
            th = self.input(g, p.get("TargetHigh"), scope, self.const(float(p.get("TargetHighDefault", 1.0))))
            k = self.binop('DIVIDE', self.binop('SUBTRACT', th, tl), self.binop('SUBTRACT', ih, il))
            return self.binop('ADD', tl, self.binop('MULTIPLY', self.binop('SUBTRACT', v, il), k), label="remap")
        if t == "MaterialXAppend3Vector":
            return self.combine([self.mask(P(k), [0]) for k in "ABC"])
        if t == "TextureProperty":
            ref = self.input(g, p.get("TextureObject"), scope, None)
            img = self.env.texture(ref.s.name, "") if ref is not None and isinstance(ref.s, TexRef) else None
            w, h = (img.size[0], img.size[1]) if img is not None and img.size[0] else (1, 1)
            if str(p.get("Property", "TMTM_TextureSize")).endswith("TexelSize"):
                return self.const((1.0 / w, 1.0 / h), 2)
            return self.const((float(w), float(h)), 2)
        if t == "Noise":
            return self.noise(g, p, scope)
        if t == "VectorNoise":
            return self.vector_noise(g, p, scope, out)
        return None

    def noise(self, g, p, scope):
        """UE's Noise, approximated by Blender's fBM noise: same position scale,
        octaves and lacunarity, mapped onto OutputMin..OutputMax."""
        pos = self.input(g, p.get("Position"), scope, None) or self.env.world_position(False)
        pos = self.vmath('SCALE', self.as3(pos), self.const(float(p.get("Scale", 1.0))), out_w=3)
        n = self.node("ShaderNodeTexNoise", "noise (approximate)", noise_dimensions='3D')
        self.link(pos, n.inputs["Vector"])
        n.inputs["Scale"].default_value = 1.0
        n.inputs["Detail"].default_value = max(0, int(p.get("Levels", 6)) - 1)
        n.inputs["Roughness"].default_value = 0.5
        n.inputs["Lacunarity"].default_value = float(p.get("LevelScale", 2.0))
        f = Val(n.outputs["Factor"], 1)
        if p.get("bTurbulence", True):
            f = self.math('ABSOLUTE', self.binop('SUBTRACT', self.binop('MULTIPLY', f, self.const(2.0)), self.const(1.0)))
        lo, hi = float(p.get("OutputMin", -1.0)), float(p.get("OutputMax", 1.0))
        self.warnings.append("approximate Noise (Blender fBM)")
        return self.binop('ADD', self.const(lo), self.binop('MULTIPLY', f, self.const(hi - lo)))

    def vector_noise(self, g, p, scope, out):
        """UE's VectorNoise, approximated: cell noise is Blender's white noise
        per cell, Voronoi its Voronoi, the gradient kinds its noise colour."""
        fn = str(p.get("NoiseFunction", "VNF_CellnoiseALU")).split("::")[-1]
        pos = self.as3(self.input(g, p.get("Position"), scope, None) or self.env.world_position(False))
        self.warnings.append("approximate VectorNoise (%s)" % fn)
        if fn == "VNF_CellnoiseALU":
            n = self.node("ShaderNodeTexWhiteNoise", "cell noise", noise_dimensions='3D')
            self.link(self.vmath('FLOOR', pos, out_w=3), n.inputs["Vector"])
            return Val(n.outputs["Color"], 3)
        if fn == "VNF_VoronoiALU":
            n = self.node("ShaderNodeTexVoronoi", "voronoi", voronoi_dimensions='3D')
            self.link(pos, n.inputs["Vector"])
            n.inputs["Scale"].default_value = 1.0
            if out == 1:
                return Val(n.outputs["Distance"], 1)
            return self.with_alpha(Val(n.outputs["Position"], 3), Val(n.outputs["Distance"], 1))
        n = self.node("ShaderNodeTexNoise", "vector noise (approximate)", noise_dimensions='3D')
        self.link(pos, n.inputs["Vector"])
        n.inputs["Scale"].default_value = 1.0
        n.inputs["Detail"].default_value = 0.0
        return self.vmath('SUBTRACT', self.vmath('SCALE', Val(n.outputs["Color"], 3), self.const(2.0), out_w=3),
                          self.const((1.0, 1.0, 1.0), 3), out_w=3)

    # ----------------------------------------------------------- spaces
    # UE space here, Blender's in the nodes: FP mirrors Y and scales by 0.01;
    # UE view space is x right, y up, z forward, Blender's camera -z forward.
    def to_blender(self, v, point=False, view=False):
        # (a shader's camera space is UE's view space: X right, Y up, Z forward - not the camera
        # object's, which looks down -Z)
        s = 0.01 if point else 1.0
        return self.vmath('MULTIPLY', self.as3(v), self.const((s, s, s) if view else (s, -s, s), 3), out_w=3)

    def from_blender(self, v, point=False, view=False):
        s = 100.0 if point else 1.0
        return self.vmath('MULTIPLY', v, self.const((s, s, s) if view else (s, -s, s), 3), out_w=3)

    def blender_transform(self, v, src, dst, point):
        n = self.node("ShaderNodeVectorTransform", "%s to %s" % (src.lower(), dst.lower()),
                      vector_type='POINT' if point else 'VECTOR', convert_from=src, convert_to=dst)
        self.link(v, n.inputs[0])
        return Val(n.outputs[0], 3)

    def tangent_frame(self):
        """UE's tangent basis in UE space: X along +U, Y along +V (UE's V runs
        down, Blender's up, so -bitangent), Z the normal."""
        def make():
            nb = self.to_blender(self.vertex_normal())
            tb = self.to_blender(self._hook("vertex_tangent", self._blender_tangent))
            bb = self.vmath('CROSS_PRODUCT', nb, tb, out_w=3)
            return (self.from_blender(tb), self.from_blender(self.vmath('SCALE', bb, self.const(-1.0), out_w=3)),
                    self.from_blender(nb))
        return self.shared("tangent frame", make)

    def to_world(self, v, space, point):
        if space == "world":
            return v
        if space == "translated":
            return self.vmath('ADD', self.as3(v), self.env.camera_position(), out_w=3) if point else v
        if space == "local":
            return self.from_blender(self.blender_transform(self.to_blender(v, point), 'OBJECT', 'WORLD', point), point)
        if space == "view":
            return self.from_blender(self.blender_transform(self.to_blender(v, point, view=True), 'CAMERA', 'WORLD',
                                                            point), point)
        if space == "tangent":
            t, b, n = self.tangent_frame()
            x, y, z = self.comps(v)
            return self.vmath('ADD', self.vmath('ADD', self.vmath('SCALE', t, x, out_w=3),
                                                self.vmath('SCALE', b, y, out_w=3), out_w=3),
                              self.vmath('SCALE', n, z, out_w=3), label="tangent to world", out_w=3)
        return v

    def from_world(self, v, space, point, tile=None):
        if space == "world":
            return v
        if space == "translated":
            return self.vmath('SUBTRACT', self.as3(v), self.env.camera_position(), out_w=3) if point else v
        if space == "periodic":
            if tile is None:
                return v
            return self.binop('SUBTRACT', self.as3(v),
                              self.binop('MULTIPLY', tile, self.unary('FLOOR', self.binop('DIVIDE', self.as3(v), tile))))
        if space == "local":
            return self.from_blender(self.blender_transform(self.to_blender(v, point), 'WORLD', 'OBJECT', point), point)
        if space == "view":
            return self.from_blender(self.blender_transform(self.to_blender(v, point), 'WORLD', 'CAMERA', point),
                                     point, view=True)
        if space == "tangent":
            t, b, n = self.tangent_frame()
            w = self.as3(v)
            return self.combine([self.vmath('DOT_PRODUCT', w, e) for e in (t, b, n)])
        return v

    def transform(self, v, src, dst, point=False, tile=None):
        if src == dst:
            return v
        r = self.from_world(self.to_world(v, src, point), dst, point, tile)
        return self.with_alpha(r, v.a) if v.w == 4 and v.a is not None else r

    # --------------------------------------------------- Blender inputs
    def _geometry(self, socket):
        n = self.shared("geometry", lambda: self.node("ShaderNodeNewGeometry", "geometry"))
        return Val(n.outputs[socket], 1 if socket in ("Backfacing", "Pointiness", "Random Per Island") else 3)

    def _blender_tangent(self):
        """Blender's UV tangent, back in UE space. Where Blender gives none (Cycles works out a
        displacement without tangents) the mesh's own "mp_tangent" attribute, which an effect's
        mesh carries (none elsewhere: there it adds nothing)."""
        def make():
            t = Val(self.node("ShaderNodeTangent", "UV tangent", direction_type='UV_MAP').outputs[0], 3)
            baked = self.node("ShaderNodeAttribute", "baked tangent", attribute_type='GEOMETRY', attribute_name="mp_tangent")
            none = self.math('LESS_THAN', self.vmath('LENGTH', t, out_w=1), self.const(1e-4))
            return self.vmath('ADD', t, self.vmath('SCALE', Val(baked.outputs["Vector"], 3), none, out_w=3), out_w=3)
        return self.from_blender(self.shared("tangent", make))

    def vertex_normal(self):
        return self._hook("vertex_normal", lambda: self.shared(
            "vertex normal", lambda: self.from_blender(self._geometry("Normal"))))

    def pixel_normal(self):
        """UE's PixelNormalWS: the material's own Normal as lit, its normal map applied (the vertex
        normal is VertexNormalWS). Where the env says how the Normal is read (env.normal_mode:
        (lit, tangent space)); else, and in an unlit material (UE compiles its Normal out), the
        vertex normal. In a function's group a socket the caller fills."""
        hooked = getattr(self.env, "pixel_normal", None)
        v = hooked() if hooked is not None else None
        if v is not None:
            return v
        mode = self._hook("normal_mode", lambda: None)
        if not mode or not mode[0]:
            return self.vertex_normal()
        if self.function is not None:
            return self.function.env_input(PIXEL_NORMAL, 'NodeSocketVector', (0.0, 0.0, 1.0),
                                           "UE PixelNormalWS: the material's normal, its normal map applied")
        src = getattr(self, "_normal_src", None)
        if src is None or getattr(self, "_normal_busy", False):
            # (asked while the Normal itself is made: UE won't compile that)
            return self.vertex_normal()

        def make():
            self._normal_busy = True
            try:
                n = src()
            except RuntimeError:
                n = None
            finally:
                self._normal_busy = False
            if n is None or n.const and tuple(_comps3(n.s)) == (0.0, 0.0, 1.0):
                return None
            return self.from_blender(self.material_normal(n, mode[1]))
        got = self.shared("pixel normal", make)
        return got if got is not None else self.vertex_normal()

    def material_normal(self, n, tangent=True):
        """A material's Normal as Blender's world normal, one per tree (the BSDF and PixelNormalWS
        read the same node): UE's tangent space is DirectX (green down) - a Normal Map node set so
        (Blender 5.2; before, green flipped here) - or a world-space normal in UE space."""
        def make():
            if not tangent:
                return self.vmath('NORMALIZE', self.vmath('MULTIPLY', n, self.const((1.0, -1.0, 1.0), 3), out_w=3), out_w=3)
            nm = self.node("ShaderNodeNormalMap", "UE normal", space='TANGENT', uv_map="UV0")
            green = 0.5
            if hasattr(nm, "convention"):
                nm.convention = 'DIRECTX'
            else:
                green = -0.5
            col = self.vmath('ADD', self.vmath('MULTIPLY', n, self.const((0.5, green, 0.5), 3), out_w=3),
                             self.const((0.5, 0.5, 0.5), 3), out_w=3)
            self.link(col, nm.inputs["Color"])
            return Val(nm.outputs["Normal"], 3)
        return self.shared("material normal", make)

    def object_position(self, rel=False):
        """UE's Object Position: the centre of the object's bounds, not its pivot (that's Actor
        Position): a sprite's pivot is at its feet, its screen-space glow centred on its body.
        The centre (local, Blender metres) is a property the import sets on each object
        (mp_bounds_centre: the material stays shared); an object without it: its pivot. An
        outfit's parts take the body's bounds in Fortnite (a head's ObjectRadius is the whole
        character's: Cyclo's sprite scales by it over an ActorRadius of 97 cm), which the joined
        mesh's are. UE world, cm."""
        env = self.env

        def centre():
            n = self.node("ShaderNodeAttribute", "bounds centre", attribute_type='OBJECT',
                          attribute_name=BOUNDS_CENTRE)
            local = Val(n.outputs["Vector"], 3)
            world = self.from_blender(self.blender_transform(local, 'OBJECT', 'WORLD', True), True)
            return self.vmath('SUBTRACT', world, env.camera_position(), out_w=3) if rel else world
        return self._hook("object_position", centre, rel)

    def head_socket(self):
        """The character's head in UE world cm (HEAD_SOCKET, the import's: its armature's head
        bone), else Object Position: a stand-in for a head socket position the game sets at run time."""
        def make():
            n = self.node("ShaderNodeAttribute", "head socket", attribute_type='OBJECT', attribute_name=HEAD_SOCKET)
            local = Val(n.outputs["Vector"], 3)
            has = self.binop('GREATER_THAN', self.vmath('LENGTH', local), self.const(1e-9))
            head = self.from_blender(self.blender_transform(local, 'OBJECT', 'WORLD', True), True)
            return self.lerp(self.object_position(), head, has, label="head socket")
        return self.shared("head socket", make)

    def local_position(self):
        def fallback():
            n = self.shared("texcoord", lambda: self.node("ShaderNodeTexCoord", "texture coordinate"))
            return self.shared("local position", lambda: self.from_blender(Val(n.outputs["Object"], 3), point=True))
        return self._hook("local_position", fallback)

    def preskinned_position(self):
        """UE's PreSkinnedPosition: the vertex where it is before skinning, which an animation
        doesn't move (a LEGO face's prints are projected from it). An env that knows the rest
        pose says; otherwise the local position (a static mesh's is the same)."""
        return self._hook("preskinned_position", self.local_position)

    def local_bounds(self):
        """(min, max), UE cm. Blender's shader nodes can't see an object's
        bounds: an env that knows the object says; otherwise +-1 m."""
        def fallback():
            self.warnings.append("object bounds assumed +-1 m")
            return self.const((-100.0, -100.0, -100.0), 3), self.const((100.0, 100.0, 100.0), 3)
        return self._hook("local_bounds", fallback)

    def reflection(self, n=None):
        """reflect(-C, N) = 2 (N . C) N - C, N the pixel normal by default."""
        n = self.pixel_normal() if n is None else self.as3(n)
        c = self.env.camera_vector()
        d = self.vmath('DOT_PRODUCT', n, c)
        return self.vmath('SUBTRACT', self.vmath('SCALE', n, self.binop('MULTIPLY', d, self.const(2.0)), out_w=3), c,
                          label="reflection", out_w=3)

    def view_size(self):
        def fallback():
            try:
                import bpy
                r = bpy.context.scene.render
                k = r.resolution_percentage / 100.0
                return self.const((r.resolution_x * k, r.resolution_y * k), 2)
            except Exception:
                return self.const((1920.0, 1080.0), 2)
        return self._hook("view_size", fallback)

    def view_property(self, name):
        """UE's ViewProperty: what a still frame has (no temporal jitter, full
        resolution), the camera's field of view."""
        v = self._hook("view_property", lambda: None, name)
        if v is not None:
            return v
        if name in ("ViewSize", "BufferSize"):
            return self.view_size()
        if name in ("FieldOfView", "TanHalfFieldOfView"):
            try:
                import bpy
                scene = bpy.context.scene
                tx, ty = render_tan_half_fov(scene.camera.data, scene.render)
                ax, ay = 2 * math.atan(tx), 2 * math.atan(ty)
            except Exception:
                ax, ay = math.radians(90.0), 2 * math.atan(math.tan(math.radians(45.0)) * 9 / 16)
            if name == "FieldOfView":
                return self.const((ax, ay), 2)
            return self.const((math.tan(ax / 2), math.tan(ay / 2)), 2)
        if name in ("WorldSpaceCameraPosition", "WorldSpaceViewPosition"):
            return self.env.camera_position()
        if name in ("ViewportOffset", "TemporalSampleOffset"):
            return self.const((0.0, 0.0), 2)
        return self.const({"TemporalSampleCount": 1.0, "ResolutionFraction": 1.0, "PreExposure": 1.0}.get(name, 0.0))

    def smoothstep(self, mn, mx, v):
        """HLSL's smoothstep(Min, Max, Value). Over an empty range (Min = Max: a softness of 0.5
        taken off both ends) its (Value - Min) / 0 is an infinity the saturate turns into a hard
        edge, 1 past Min and 0 before it; a Blender Map Range gives 0 everywhere (the embers drew
        nothing). Scalars: a Min and Max that are sockets are checked as the material runs."""
        w = max(mn.w, mx.w, v.w)
        if w == 1 and mn.const and mx.const and float(mn.s) == float(mx.s):
            return self.math('GREATER_THAN', v, mn)
        n = self.node("ShaderNodeMapRange", "smoothstep", interpolation_type='SMOOTHSTEP',
                      data_type='FLOAT' if w == 1 else 'FLOAT_VECTOR', clamp=True)
        if w == 1:
            self.link(v, n.inputs[0]); self.link(mn, n.inputs[1]); self.link(mx, n.inputs[2])
            n.inputs[3].default_value, n.inputs[4].default_value = 0.0, 1.0
            smooth = Val(n.outputs[0], 1)
            if mn.const and mx.const:
                return smooth
            # (1 where Min is Max) * (the hard edge - the Map Range's), added to the Map Range's
            empty = self.math('COMPARE', mn, mx, self.const(0.0))
            edge = self.math('GREATER_THAN', v, mn)
            return self.binop('ADD', smooth, self.binop('MULTIPLY', empty, self.binop('SUBTRACT', edge, smooth)))
        self.link(v, n.inputs[6]); self.link(mn, n.inputs[7]); self.link(mx, n.inputs[8])
        n.inputs[9].default_value = (0.0, 0.0, 0.0); n.inputs[10].default_value = (1.0, 1.0, 1.0)
        return Val(n.outputs[1], min(w, 3))

    def stand_in(self, what, v):
        self.warnings.append("stand-in: " + what)
        return v

    def light_color(self):
        return self._hook("light_color", lambda: self.stand_in("sun colour 1", self.const((1.0, 1.0, 1.0), 3)))

    def pixel_depth(self):
        def fallback():
            n = self.shared("camera data", lambda: self.node("ShaderNodeCameraData", "camera data"))
            return self.binop('MULTIPLY', Val(n.outputs["View Z Depth"], 1), self.const(100.0))
        return self._hook("pixel_depth", fallback)

    def water_depth(self):
        """How deep the water is under this pixel of its surface (UE cm, the
        surface's height less the ground's; below 0 where the ground rises
        over it - measured along the surface's normal where it isn't level).
        At run time the water info texture holds both heights; here the
        env's water_depth() answers, else WATER_DEPTH_DEFAULT."""
        return self.shared("water depth", lambda: self._hook("water_depth", lambda: self.stand_in(
            "water depth %g cm (the ground under the water unknown)" % WATER_DEPTH_DEFAULT,
            self.const(WATER_DEPTH_DEFAULT))))

    def water_path(self):
        """The view ray's way through the water to the ground behind it (UE
        cm, >= 0): the depth (along the surface's normal: down, for level
        water) over the ray's steepness to the surface, the ground taken
        parallel to it (what SceneDepthWithoutWater - PixelDepth measures)."""
        def make():
            # level water (normal within 60 degrees of up) is measured straight down
            n = self.vertex_normal()
            level = self.math('GREATER_THAN', self.math('ABSOLUTE', self.comps(n)[2]), self.const(0.5 - 1e-6))
            n = self.lerp(n, self.const((0.0, 0.0, 1.0), 3), level, label="level: up")
            up = self.math('ABSOLUTE', self.vmath('DOT_PRODUCT', self.env.camera_vector(), n))
            path = self.binop('DIVIDE', self.water_depth(), self.math('MAXIMUM', up, self.const(0.02)))
            return self.math('MAXIMUM', path, self.const(0.0), label="water path")
        return self.shared("water path", make)

    def sample_array(self, tname, coords, sampler):
        """A texture array at (u, v, slice): the env's slices, the nearest one
        (as UE rounds the slice index); float4 with alpha."""
        slices = self._hook("texture_slices", lambda: None, tname, sampler)
        if not slices:
            slices = [self.env.texture(tname, sampler)]
            self.warnings.append("stand-in: texture array %s as its first slice" % tname)
        c = self.comps(self.as3(coords)) if coords is not None else [self.const(0.0)] * 3
        uv = self.combine(c[:2])
        vals = []
        for img in slices:
            n = self.sample_node(tname, uv, sampler, img=img)
            if "Normal" in (sampler or ""):
                vals.append(self.with_alpha(*self.unpack_normal(Val(n.outputs["Color"], 3))))
            else:
                vals.append(self.with_alpha(Val(n.outputs["Color"], 3), Val(n.outputs["Alpha"], 1)))
        if len(vals) == 1:
            return vals[0]
        z = c[2]
        if z.const:
            return vals[max(0, min(len(vals) - 1, int(math.floor(z.s + 0.5))))]
        return self._pick(self.math('ROUND', z), vals)

    def evaluate_renderer(self, g, x, t, out, scope, p, P):
        env = self.env
        if t == "EyeAdaptation":
            return self._hook("exposure", lambda: self.const(1.0))
        if t == "EyeAdaptationInverse":
            # LightValue * lerp(1, 1 / EyeAdaptation, Alpha): at exposure 1, LightValue
            lv = self.input(g, p.get("LightValueInput"), scope, self.const(1.0))
            ea = self._hook("exposure", lambda: self.const(1.0))
            if ea.const and ea.s == 1.0:
                return lv
            a = self.input(g, p.get("AlphaInput"), scope, self.const(1.0))
            return self.binop('MULTIPLY', lv, self.lerp(self.const(1.0), self.binop('DIVIDE', self.const(1.0), ea), a))
        if t == "AtmosphericLightVector":
            return env.light_direction()
        if t == "AtmosphericLightColor":
            return self.light_color()
        if t == "SkyAtmosphereLightIlluminance":
            return self.light_color()
        if t == "SkyLightEnvMapSample":
            d = self.input(g, p.get("Direction"), scope, None) or self.pixel_normal()
            r = self.input(g, p.get("Roughness"), scope, self.const(0.0))
            return self._hook("sky_light", lambda: self.stand_in("sky light as a flat grey", self.const((0.5, 0.5, 0.5), 3)),
                              d, r)
        if t in ("DDX", "DDY"):
            # no screen derivatives in Blender's shader nodes: a tiny step
            # (the sharp, infinitely-resolved limit of what they're used for)
            v = P("Value")
            return self.stand_in("%s as 1e-4" % t, self.const(0.0001) if v.w == 1 else self.const((0.0001,) * 3, v.w))
        if t == "DepthFade":
            # soft-particle fade against the scene's depth: InOpacity x saturate((scene depth - pixel
            # depth) / FadeDistance). Where the env can cast a ray behind this pixel (env.depth_behind:
            # cm along the view ray, and whether it hit - a see-through material) it fades by that,
            # else not at all
            opacity = self.input(g, p.get("InOpacity"), scope, self.const(float(p.get("InOpacityDefault", 1.0))))
            behind = getattr(self.env, "depth_behind", None)
            got = behind() if behind is not None else None
            if got is None:
                return self.stand_in("DepthFade as its opacity", opacity)
            distance, known = got
            fade = self.input(g, p.get("FadeDistance"), scope, self.const(float(p.get("FadeDistanceDefault", 100.0))))
            # UE divides by max(FadeDistance, 0.0001): a 0 fade distance leaves it all drawn (Blender's
            # x / 0 is 0, which hid it wherever anything was behind - Elite Jules' crown)
            fade = self.math('MAXIMUM', fade, self.const(0.0001))
            near = self.saturate(self.binop('DIVIDE', distance, fade, label="depth fade"))
            factor = self.math('ADD', self.const(1.0), self.math('MULTIPLY', self.math('SUBTRACT', near, self.const(1.0)), known))
            return self.binop('MULTIPLY', opacity, factor, label="depth fade")
        if t == "SceneDepth":
            # the depth of the surface behind this pixel: where the env can cast a ray behind it
            # (env.depth_behind: a see-through material), this pixel's depth carried on along the
            # view ray by the distance found; else far
            behind = getattr(self.env, "depth_behind", None)
            got = behind() if behind is not None else None
            if got is None:
                return self.stand_in("SceneDepth as far (1e6)", self.const(1e6))
            distance, known = got
            n = self.shared("camera data", lambda: self.node("ShaderNodeCameraData", "camera data"))
            along = self.math('MULTIPLY', Val(n.outputs["View Distance"], 1), self.const(100.0))
            scene = self.binop('MULTIPLY', self.pixel_depth(), self.binop('DIVIDE', self.math('ADD', along, distance), along))
            return self.math('ADD', self.const(1e6), self.math('MULTIPLY', self.math('SUBTRACT', scene, self.const(1e6)), known), label="scene depth")
        if t == "SceneDepthWithoutWater":
            # the scene behind the water: its depth along this pixel's view ray
            return self.binop('ADD', self.pixel_depth(), self.water_path(), label="scene depth without water")
        if t == "SceneColor":
            return self.stand_in("SceneColor as black", self.const((0.0, 0.0, 0.0), 3))
        if t == "SceneTexture":
            if out in (1, 2):
                size = self.view_size()
                return size if out == 1 else self.binop('DIVIDE', self.const((1.0, 1.0), 2), size)
            sid = str(p.get("SceneTextureId", "ESceneTextureId::PPI_SceneColor")).split("::")[-1]
            if sid == "PPI_WorldNormal":
                rgb = self.pixel_normal()
            else:
                v = {"PPI_Roughness": 0.5, "PPI_Specular": 0.5, "PPI_BaseColor": 0.5, "PPI_DiffuseColor": 0.5,
                     "PPI_SceneDepth": 1e6, "PPI_CustomDepth": 1e6, "PPI_Opacity": 1.0,
                     "PPI_AmbientOcclusion": 1.0}.get(sid, 0.0)
                rgb = self.const((v, v, v), 3)
            return self.stand_in("SceneTexture %s" % sid, self.with_alpha(rgb, self.const(1.0)))
        if t == "DistanceFieldApproxAO":
            return self.stand_in("distance-field AO as 1", self.const(1.0))
        if t == "RecordTextureStreamingInfo":
            # a streaming-statistics tap: hands its texture on
            return self.input(g, p.get("TextureObject"), scope, self.const(0.0))
        if t == "CurveAtlasRowParameter":
            # a row of a curve atlas, the row a scalar parameter (the instance
            # picks the curve): u = time, v = (row + 0.5) / atlas height
            atlas = self.tex_key(p.get("Atlas"))
            row = env.scalar(p.get("ParameterName"), float(p.get("DefaultValue", 0.0)))
            img = env.texture(atlas, "SAMPLERTYPE_LinearColor")
            h = float(img.size[1]) if img is not None and img.size[1] > 1 else 256.0
            time = self.mask(self.input(g, p.get("InputTime"), scope, self.const(0.0)), [0])
            v = self.binop('DIVIDE', self.binop('ADD', row, self.const(0.5)), self.const(h))
            n = self.sample_node(atlas, self.combine([time, v]), "SAMPLERTYPE_LinearColor", img=img,
                                 address=("Clamp", "Clamp"))
            rgb = Val(n.outputs["Color"], 3)
            if out == 4:
                return Val(n.outputs["Alpha"], 1)
            return rgb if out == 0 else self.mask(rgb, [out - 1])
        if t in ("TextureSampleParameterSubUV", "ParticleSubUV"):
            # a flipbook's first frame: a plain mesh has no particle to pick one
            tex = self.tex_param(p, self.tex_key(p.get("Texture")))
            ref = self.input(g, p.get("TextureObject"), scope, None)
            if ref is not None and isinstance(ref.s, TexRef):
                tex = ref.s.name
            coords = self.input(g, p.get("Coordinates"), scope, None) or env.uv(0)
            if not getattr(env, "entry", {}).get("sprite"):
                self.warnings.append("stand-in: %s sampled whole (no particle sub-image)" % t)
            return self.sample(tex, coords, out, p.get("SamplerType", ""))
        if t == "TextureSampleParameter2DArray":
            tex = self.tex_param(p, self.tex_key(p.get("Texture")))
            v = self.sample_array(tex, self.input(g, p.get("Coordinates"), scope, None), p.get("SamplerType", ""))
            return self.rgba_out(Val(v.s, 3), v.a, out)
        if t in ("RuntimeVirtualTextureSampleParameter", "RuntimeVirtualTextureSample"):
            # the terrain's virtual texture under the object: none here - a
            # neutral surface, its height far below (height blends stay off)
            vals = [self.const((0.5, 0.5, 0.5), 3), self.const(0.5), self.const(0.5), self.const((0.0, 0.0, 1.0), 3),
                    self.const(-1e6), self.const(0.0), self.const(0.0)]
            return self.stand_in("runtime virtual texture", vals[min(out, len(vals) - 1)])
        if t == "ParticleColor":
            rgb, a = self._hook("particle_color", lambda: (self.const((1.0, 1.0, 1.0), 3), self.const(1.0)))
            return self.rgba_out(rgb, a, out)
        if t == "DecalColor":
            # a decal's colour (a Niagara decal's: its particle's DecalColor), RGBA
            rgb, a = self._hook("particle_color", lambda: (self.const((1.0, 1.0, 1.0), 3), self.const(1.0)))
            return self.with_alpha(rgb, a)
        if t == "DecalLifetimeOpacity":
            # a decal's fade over its life (a Niagara decal's: its particle's DecalFade); 1 on anything else
            return self._hook("decal_fade", lambda: self.const(1.0))
        if t == "DynamicParameter":
            d = p.get("DefaultValue") or {}
            dflt = self.const((d.get("R", 1.0), d.get("G", 1.0), d.get("B", 1.0), d.get("A", 1.0)), 4)
            v = self._hook("dynamic_parameter", lambda: dflt, int(p.get("ParameterIndex", 0)), dflt)
            if out < 4:
                return self.mask(v, [out])
            return Val(v.s, 3) if out == 4 else v
        if t == "ParticleRandom":
            return self._hook("particle_random", lambda: self.evaluate_geometry(g, x, "PerInstanceRandom", out, scope, p, P))
        if t == "ParticlePositionWS":
            return env.actor_position("CameraRelative" in str(p.get("OriginType", "")))
        if t == "ParticleRadius":
            return self.evaluate_geometry(g, x, "ObjectRadius", out, scope, p, P)
        if t == "ParticleMacroUV":
            return self.evaluate_geometry(g, x, "ScreenPosition", 0, scope, p, P)
        if t == "ParticleRelativeTime":
            return self._hook("particle_time", lambda: self.stand_in("ParticleRelativeTime as 0", self.const(0.0)))
        if t == "ParticleSpeed":
            return self._hook("particle_speed", lambda: self.stand_in("ParticleSpeed as 0", self.const(0.0)))
        if t == "PerInstanceFadeAmount":
            return self.stand_in("%s as 0" % t, self.const(0.0))
        if t in _SHELL_ATTRIBUTES:
            # the shell copy's layer (0 off the copies: the mesh itself, the base layer)
            name = _SHELL_ATTRIBUTES[t]
            return self.shared(name, lambda: Val(self.node("ShaderNodeAttribute", name, attribute_type='GEOMETRY',
                                                           attribute_name=name).outputs["Fac"], 1))
        if t in ("ParticleMotionBlurFade", "SphericalParticleOpacity"):
            return self.stand_in("%s as 1" % t, self.const(1.0))
        if t == "ParticleSize":
            return self._hook("particle_size", lambda: self.stand_in("ParticleSize as 1 m", self.const((100.0, 100.0), 2)))
        if t == "ParticleSpriteRotation":
            # a sprite's turn: radians, then degrees (the outputs mask one each)
            return self._hook("particle_rotation", lambda: self.stand_in("ParticleSpriteRotation as 0", self.const((0.0, 0.0), 2)))
        if t == "ParticleDirection":
            return self._hook("particle_direction", lambda: self.stand_in("ParticleDirection as 0", self.const((0.0, 0.0, 0.0), 3)))
        if t in _SHELL_VECTORS:
            # the shell copy's offset from its root (UE local cm): the material moves it there (WPO)
            name = _SHELL_VECTORS[t]
            return self.shared(name, lambda: self.from_blender(Val(self.node(
                "ShaderNodeAttribute", name, attribute_type='GEOMETRY', attribute_name=name).outputs["Vector"], 3), point=True))
        if t == "SamplePhysicsVectorField":
            return self.stand_in("%s as 0" % t, self.const((0.0, 0.0, 0.0), 3))
        if t == "LandscapeLayerCoords":
            # UE: the landscape's own texture coordinates (quads, landscape-wide:
            # an exported landscape carries them as UV0; XZ/YZ mappings read
            # UV1/UV2) over the mapping scale, rotated, panned
            # (UMaterialExpressionLandscapeLayerCoords::Compile)
            mapping = str(p.get("MappingType", ""))
            index = 1 if mapping.endswith("XZ") else 2 if mapping.endswith("YZ") else 0
            base = self._hook("landscape_uv", lambda: None, index)
            stand = base is None
            if stand:
                # not on a landscape: world XY in 1 m quads
                wp = self.comps(env.world_position(False))
                base = self.combine([self.binop('DIVIDE', wp[0], self.const(100.0)), self.binop('DIVIDE', wp[1], self.const(100.0))])
            bu, bv = self.comps(base)[:2]
            scale = 1.0 / (float(p.get("MappingScale", 0.0)) or 1.0)
            rot = math.radians(float(p.get("MappingRotation", 0.0)))
            c, s_ = math.cos(rot) * scale, math.sin(rot) * scale
            u = self.binop('ADD', self.binop('MULTIPLY', bu, self.const(c)), self.binop('MULTIPLY', bv, self.const(s_)))
            v = self.binop('ADD', self.binop('MULTIPLY', bu, self.const(-s_)), self.binop('MULTIPLY', bv, self.const(c)))
            u = self.binop('ADD', u, self.const(float(p.get("MappingPanU", 0.0))))
            v = self.binop('ADD', v, self.const(float(p.get("MappingPanV", 0.0))))
            uv = self.combine([u, v])
            return self.stand_in("landscape coordinates from world XY", uv) if stand else uv
        if t in ("LandscapeLayerSample", "LandscapeLayerWeight", "LandscapeVisibilityMask", "LandscapeLayerBlend"):
            return self.landscape_layers(g, t, scope, p)
        if t == "ScalarBlueNoise":
            n = self.node("ShaderNodeTexWhiteNoise", "blue noise (white)", noise_dimensions='2D')
            self.link(self.as3(self.evaluate_geometry(g, x, "ScreenPosition", 1, scope, p, P)), n.inputs["Vector"])
            return self.stand_in("blue noise as white noise", Val(n.outputs["Value"], 1))
        return None

    def layer_weight(self, name):
        """A landscape layer's painted weight here (env.landscape_weight: the
        exported landscape's colour layer of that name), else None."""
        return self._hook("landscape_weight", lambda: None, name) if name else None

    def landscape_layers(self, g, t, scope, p):
        """UE's landscape layer expressions, from the painted weights (layers
        a component doesn't paint weigh 0, as in UE)."""
        if t == "LandscapeLayerSample":
            w = self.layer_weight(p.get("ParameterName"))
            return w if w is not None else self.stand_in("landscape layer weight as 0", self.const(0.0))
        if t == "LandscapeVisibilityMask":
            w = self.layer_weight("__LANDSCAPE_VISIBILITY__")
            return self.const(1.0) if w is None else self.binop('SUBTRACT', self.const(1.0), w)
        if t == "LandscapeLayerWeight":
            # Base + Layer * weight (a layer not painted leaves Base)
            base = self.input(g, p.get("Base"), scope, None)
            if base is None:
                cb = p.get("ConstBase") or {}
                base = self.const((float(cb.get("X", 0.0)), float(cb.get("Y", 0.0)), float(cb.get("Z", 0.0))), 3)
            w = self.layer_weight(p.get("ParameterName"))
            if w is None:
                return base
            layer = self.input(g, p.get("Layer"), scope, None)
            if layer is None:
                return base
            return self.binop('ADD', base, self.binop('MULTIPLY', layer, w))
        # LandscapeLayerBlend: weight-blended layers add up; height-blended ones share
        # what their heights make of their weights; alpha-blended ones go over the result
        out, height_terms, alpha = None, [], []
        for layer in p.get("Layers") or []:
            name = layer.get("LayerName")
            w = self.layer_weight(name)
            if w is None:
                continue
            value = self.input(g, layer.get("LayerInput"), scope, None)
            if value is None:
                cl = layer.get("ConstLayerInput") or {}
                value = self.const((float(cl.get("X", 0.0)), float(cl.get("Y", 0.0)), float(cl.get("Z", 0.0))), 3)
            kind = str(layer.get("BlendType", ""))
            if kind.endswith("HeightBlend"):
                h = self.input(g, layer.get("HeightInput"), scope, None)
                if h is None:
                    h = self.const(float(layer.get("ConstHeightInput", 0.5)))
                h = self.mask(h, [0]) if h.w > 1 else h
                # clamp(lerp(-1, 1, weight) + height, 0.0001, 1)
                mw = self.math('ADD', self.math('MULTIPLY_ADD', w, self.const(2.0), self.const(-1.0)), h)
                mw = self.math('MAXIMUM', self.math('MINIMUM', mw, self.const(1.0)), self.const(0.0001))
                height_terms.append((value, mw))
            elif kind.endswith("AlphaBlend"):
                alpha.append((value, w))
            else:
                term = self.binop('MULTIPLY', value, w)
                out = term if out is None else self.binop('ADD', out, term)
        if height_terms:
            total = height_terms[0][1]
            for _, mw in height_terms[1:]:
                total = self.math('ADD', total, mw)
            for value, mw in height_terms:
                term = self.binop('MULTIPLY', value, self.math('DIVIDE', mw, total))
                out = term if out is None else self.binop('ADD', out, term)
        if out is None:
            out = self.const(0.0)
        for value, w in alpha:
            out = self.lerp(out, value, w)
        return out

    def evaluate_geometry(self, g, x, t, out, scope, p, P):
        env = self.env
        if t == "VertexNormalWS":
            return self.vertex_normal()
        if t == "PixelNormalWS":
            return self.pixel_normal()
        if t in ("VertexTangentWS",):
            return self.tangent_frame()[0]
        if t == "PixelDepth":
            return self.pixel_depth()
        if t == "ObjectPositionWS":
            return self.object_position("CameraRelative" in str(p.get("OriginType", "")))
        if t == "LocalPosition":
            return self.local_position()
        if t == "PreSkinnedPosition":
            return self.preskinned_position()
        if t == "PreSkinnedNormal":
            return self.vmath('NORMALIZE', self.from_world(self.vertex_normal(), "local", False), out_w=3)
        if t in ("PreSkinnedLocalBounds", "ObjectLocalBounds", "Bounds", "ObjectBounds"):
            mn, mx = self.local_bounds()
            full = self.vmath('SUBTRACT', mx, mn, out_w=3)
            if t == "ObjectBounds":
                return full
            return [self.vmath('SCALE', full, self.const(0.5), out_w=3), full, mn, mx][min(out, 3)]
        if t == "ObjectRadius":
            def fallback():
                mn, mx = self.local_bounds()
                return self.binop('MULTIPLY', self.vmath('DISTANCE', mn, mx), self.const(0.5))
            return self._hook("object_radius", fallback)
        if t == "ObjectOrientation":
            return self.vmath('NORMALIZE', self.to_world(self.const((0.0, 0.0, 1.0), 3), "local", False), out_w=3)
        if t == "ReflectionVectorWS":
            n = self.input(g, p.get("CustomWorldNormal"), scope, None)
            if n is not None and p.get("bNormalizeCustomWorldNormal", True):
                n = self.vmath('NORMALIZE', self.as3(n), out_w=3)
            return self.reflection(n)
        if t == "TwoSidedSign":
            return self._hook("two_sided_sign", lambda: self.binop(
                'SUBTRACT', self.const(1.0), self.binop('MULTIPLY', self._geometry("Backfacing"), self.const(2.0))))
        if t == "ScreenPosition":
            def fallback():
                n = self.shared("texcoord", lambda: self.node("ShaderNodeTexCoord", "texture coordinate"))
                u, v = self.comps(Val(n.outputs["Window"], 3))[:2]
                return self.combine([u, self.binop('SUBTRACT', self.const(1.0), v)])
            uv = self._hook("screen_uv", fallback)
            return uv if out == 0 else self.binop('MULTIPLY', uv, self.view_size())
        if t == "VertexInterpolator":
            return self.input(g, p.get("Input"), scope, self.const(0.0))
        if t == "PerInstanceRandom":
            def fallback():
                n = self.shared("object info", lambda: self.node("ShaderNodeObjectInfo", "object info"))
                return Val(n.outputs["Random"], 1)
            return self._hook("instance_random", fallback)
        if t in ("PerInstanceCustomData", "PerInstanceCustomData3Vector"):
            w = 3 if t.endswith("3Vector") else 1
            d = p.get("ConstDefaultValue", 0.0)
            dflt = self.const((d.get("R", 0.0), d.get("G", 0.0), d.get("B", 0.0)), 3) if isinstance(d, dict) \
                else self.const(float(d), w)
            dflt = self.input(g, p.get("DefaultValue"), scope, dflt)
            if w == 3:
                dflt = self.mask(dflt, [0, 1, 2]) if dflt.w >= 3 else self.combine([self.mask(dflt, [0])] * 3)
            else:
                dflt = self.mask(dflt, [0])
            # the instance's own floats where it has them (env), else the default
            return self._hook("instance_data", lambda: dflt, dflt, int(p.get("DataIndex", 0)), w)
        if t == "ViewSize":
            return self.view_size()
        if t == "SceneTexelSize":
            return self.binop('DIVIDE', self.const((1.0, 1.0), 2), self.view_size())
        if t == "ViewProperty":
            name = str(p.get("Property", "MEVP_FieldOfView")).split("::")[-1].replace("MEVP_", "")
            v = self.view_property(name)
            return v if out == 0 else self.binop('DIVIDE', self.const(1.0), v)
        if t == "IsOrthographic":
            return self._hook("is_orthographic", lambda: self.const(0.0))
        if t == "DeltaTime":
            return self._hook("delta_time", lambda: self.const(1.0 / 60.0))
        if t == "Transform":
            src = VECTOR_SPACES.get(str(p.get("TransformSourceType", "TRANSFORMSOURCE_Tangent")).split("_", 1)[-1], "tangent")
            dst = VECTOR_SPACES.get(str(p.get("TransformType", "TRANSFORM_World")).split("_", 1)[-1], "world")
            return self.transform(P("Input"), src, dst)
        if t == "TransformPosition":
            src = POSITION_SPACES.get(str(p.get("TransformSourceType", "TRANSFORMPOSSOURCE_Local")).split("_", 1)[-1], "local")
            dst = POSITION_SPACES.get(str(p.get("TransformType", "TRANSFORMPOSSOURCE_Local")).split("_", 1)[-1], "local")
            tile = self.input(g, p.get("PeriodicWorldTileSize"), scope, None)
            return self.transform(P("Input"), src, dst, point=True, tile=tile)
        return None

    # ------------------------------------------------------------ custom HLSL
    # Custom nodes carry HLSL; each known snippet is rebuilt here by hand
    # (whitespace-insensitive match), anything else is reported and passes
    # its first input through.
    def custom(self, g, x, scope, out=0):
        p = x.get("Properties") or {}
        handler = custom_handler(p)
        if handler in CUSTOM_LAZY:
            # reads only some inputs: the rest never become nodes
            ins = _LazyInputs(lambda ref: self.input(g, ref, scope, self.const(0.0)),
                              {i.get("InputName"): i.get("Input") for i in p.get("Inputs", [])})
        else:
            ins = {i.get("InputName"): self.input(g, i.get("Input"), scope, self.const(0.0))
                   for i in p.get("Inputs", [])}
        if handler is not None:
            # a snippet's AdditionalOutputs are output indices 1.. (0: its return value)
            self.custom_out = out
            return getattr(self, handler)(ins, p)
        # unknown: its first numeric input, else zeros of its output type
        # (never a texture: those can't go on)
        self.warnings.append("unknown Custom node %s in %s -> first input" % (x.get("Name"), g.name))
        w = {"CMOT_Float1": 1, "CMOT_Float2": 2, "CMOT_Float3": 3, "CMOT_Float4": 4}.get(
            str(p.get("OutputType", "CMOT_Float3")).split("::")[-1], 3)
        first = next((v for v in ins.values() if not isinstance(v.s, (TexRef, Attrs))), None)
        return first if first is not None else self.const(0.0) if w == 1 else self.const((0.0,) * w, w)

    def _work(self, ins):
        """(bool)bDoWork as 0 / 1; None when it's a constant true."""
        w = ins.get("bDoWork", self.const(1.0))
        if w.const:
            return None if w.s else self.const(0.0)
        return self.binop('SUBTRACT', self.const(1.0), self.math('COMPARE', w, self.const(0.0), self.const(0.0)),
                          label="do work")

    def _tex_name(self, ins, key="Tex"):
        t = ins.get(key)
        return t.s.name if t is not None and isinstance(t.s, TexRef) else ""

    def custom_conditional_color(self, ins, p):
        # bDoWork ? Tex.Sample(UVs) : 0 (a skipped layer has zero weight
        # anyway; the branch only saves the fetch)
        n = self.sample_node(self._tex_name(ins), ins.get("UVs") or self.env.uv(0), "SAMPLERTYPE_Color")
        rgb, a = Val(n.outputs["Color"], 3), Val(n.outputs["Alpha"], 1)
        w = self._work(ins)
        if w is not None:
            rgb, a = self.vmath('SCALE', rgb, w, out_w=3), self.binop('MULTIPLY', a, w)
        return self.with_alpha(rgb, a)

    def custom_conditional_normal(self, ins, p):
        # UnpackNormalMap (BC5 on PC): xy = rg * 2 - 1, z = sqrt(saturate(1 - xy.xy)), w 1;
        # a skipped layer is (0, 0, 1, 0)
        n = self.sample_node(self._tex_name(ins), ins.get("UVs") or self.env.uv(0), "SAMPLERTYPE_Normal")
        normal, a = self.unpack_normal(Val(n.outputs["Color"], 3))
        w = self._work(ins)
        if w is not None:
            normal = self.lerp(self.const((0.0, 0.0, 1.0), 3), normal, w, label="layer normal")
            a = w
        return self.with_alpha(normal, a)

    def custom_uv_box(self, ins, p):
        # 1 inside [0, 1) on both UV axes, 0 outside
        u, v = self.comps(ins.get("uv", self.const((0.0, 0.0), 2)))[:2]
        inside = lambda c: self.binop('SUBTRACT', self.binop('SUBTRACT', self.const(1.0), self.math('LESS_THAN', c, self.const(0.0))),
                                      self.binop('SUBTRACT', self.const(1.0), self.math('LESS_THAN', c, self.const(1.0))))
        return self.binop('MULTIPLY', self.binop('MULTIPLY', inside(u), inside(v)), ins.get("color", self.const(0.0)),
                          label="uv box")

    def _in(self, ins, key, default=0.0):
        v = ins.get(key)
        return v if v is not None else self.const(default)

    def custom_identity(self, ins, p):
        return next(iter(ins.values()), self.const(0.0))

    def _exp3(self, v):
        """exp() per component of a float3."""
        return self.combine([self.math('EXPONENT', c) for c in self.comps(self.as3(v))])

    def custom_cloud_transmittance(self, ins, p):
        sigma_e = self.vmath('SCALE', self.vmath('ADD', self.as3(self._in(ins, "ScatteringCoeff")),
                                                 self.as3(self._in(ins, "AbsorptionCoeff")), out_w=3),
                             self._in(ins, "CloudDensity"), out_w=3)
        t = self._exp3(self.vmath('SCALE', sigma_e, self.binop('MULTIPLY', self._in(ins, "CloudHeight"), self.const(-1.0)), out_w=3))
        return self.saturate(self.vmath('DOT_PRODUCT', t, self.const((1.0 / 3.0,) * 3, 3)))

    def custom_cloud_light(self, ins, p):
        # sigmaS = Scattering * Density, sigmaE = sigmaS + Absorption * Density, T = exp(-Height * sigmaE);
        # phase: 0.3 uniform + 0.7 Schlick (k 0.8) over 4 pi; S = Illuminance * phase * sigmaS;
        # return max(0, (S - S T) / (sigmaE + 1e-6) * T)
        dens = self._in(ins, "CloudDensity")
        sigma_s = self.vmath('SCALE', self.as3(self._in(ins, "ScatteringCoeff")), dens, out_w=3)
        sigma_e = self.vmath('ADD', sigma_s, self.vmath('SCALE', self.as3(self._in(ins, "AbsorptionCoeff")), dens, out_w=3), out_w=3)
        t = self._exp3(self.vmath('SCALE', sigma_e, self.binop('MULTIPLY', self._in(ins, "CloudHeight"), self.const(-1.0)), out_w=3))
        to_cam = self.vmath('NORMALIZE', self.vmath('SUBTRACT', self.as3(self._in(ins, "CameraPos")),
                                                   self.as3(self._in(ins, "WorldPos")), out_w=3), out_w=3)
        phase_in = self.saturate(self.vmath('DOT_PRODUCT', self.as3(self._in(ins, "SunLightDir")),
                                            self.vmath('SCALE', to_cam, self.const(-1.0), out_w=3)))
        factor = self.binop('SUBTRACT', self.const(1.0), self.binop('MULTIPLY', phase_in, self.const(0.8)))
        schlick = self.binop('DIVIDE', self.const(1.0 - 0.64),
                             self.binop('ADD', self.binop('MULTIPLY', factor, factor), self.const(1e-6)))
        phase = self.binop('DIVIDE', self.binop('ADD', self.const(0.3), self.binop('MULTIPLY', schlick, self.const(0.7))),
                           self.const(4.0 * math.pi))
        s_ = self.vmath('MULTIPLY', self.as3(self._in(ins, "SunLightIlluminance")),
                        self.vmath('SCALE', sigma_s, phase, out_w=3), out_w=3)
        scatt = self.vmath('DIVIDE', self.vmath('SUBTRACT', s_, self.vmath('MULTIPLY', s_, t, out_w=3), out_w=3),
                           self.vmath('ADD', sigma_e, self.const((1e-6,) * 3, 3), out_w=3), out_w=3)
        return self.vmath('MAXIMUM', self.vmath('MULTIPLY', scatt, t, out_w=3), self.const((0.0,) * 3, 3), out_w=3)

    def custom_clouds_aerial(self, ins, p):
        ap = self._in(ins, "AerialPerspective")
        opacity = self.binop('SUBTRACT', self.const(1.0), self._in(ins, "CloudTransmittance"))
        return self.vmath('ADD', self.vmath('SCALE', self.as3(ap), opacity, out_w=3),
                          self.vmath('SCALE', self.as3(self._in(ins, "CloudLuminance")), self.alpha(ap), out_w=3), out_w=3)

    def custom_height_fog_coverage(self, ins, p):
        # depth = density / falloff * exp(-camZ falloff) * (1 - exp(-distance dirZ falloff)) / dirZ
        dz = self.binop('ADD', self.comps(self.as3(self._in(ins, "cameraDir")))[2], self.const(1e-5))
        fall = self._in(ins, "heightFalloff")
        cam_z = self.comps(self.as3(self._in(ins, "cameraPos")))[2]
        depth = self.binop('MULTIPLY', self.binop('DIVIDE', self._in(ins, "density"), fall),
                           self.math('EXPONENT', self.binop('MULTIPLY', self.binop('MULTIPLY', cam_z, fall), self.const(-1.0))))
        far = self.math('EXPONENT', self.binop('MULTIPLY', self.binop('MULTIPLY', self.binop('MULTIPLY', self._in(ins, "distance"), dz), fall),
                                                self.const(-1.0)))
        depth = self.binop('DIVIDE', self.binop('MULTIPLY', depth, self.binop('SUBTRACT', self.const(1.0), far)), dz)
        return self.binop('SUBTRACT', self.const(1.0), self.math('EXPONENT', self.binop('MULTIPLY', depth, self.const(-1.0))))

    def custom_smin(self, ins, p):
        a, b, k = self._in(ins, "a"), self._in(ins, "b"), self._in(ins, "k")
        h = self.saturate(self.binop('ADD', self.const(0.5), self.binop('MULTIPLY', self.const(0.5),
                                                                         self.binop('DIVIDE', self.binop('SUBTRACT', b, a), k))))
        return self.binop('SUBTRACT', self.lerp(b, a, h),
                          self.binop('MULTIPLY', k, self.binop('MULTIPLY', h, self.binop('SUBTRACT', self.const(1.0), h))))

    def custom_cave_type(self, ins, p):
        c = self._in(ins, "CaveType")
        half = self.binop('ADD', self.math('COMPARE', c, self.const(0.0), self.const(0.0)),
                          self.math('COMPARE', c, self.const(2.0), self.const(0.0)))
        return self.binop('SUBTRACT', self.const(1.0), self.binop('MULTIPLY', half, self.const(0.5)))

    def custom_one(self, ins, p):
        return self.const(1.0)

    def custom_white4(self, ins, p):
        return self.with_alpha(self.const((1.0, 1.0, 1.0), 3), self.const(1.0))

    def custom_dither5(self, ins, p):
        # Mod((uint)p.x + 2 * (uint)p.y, 5): pixel coordinates are positive,
        # so the casts are floors and Mod is floored
        x, y = self.comps(self._in(ins, "p"))[:2]
        k = self.binop('ADD', self.math('FLOOR', x), self.binop('MULTIPLY', self.math('FLOOR', y), self.const(2.0)))
        return self.math('FLOORED_MODULO', k, self.const(5.0), label="dither 5")

    def custom_primitive_index(self, ins, p):
        # a per-object integer; Blender has no primitive index: the object's
        # random value, spread over 16 bits (only ever hashed further)
        def fallback():
            self.warnings.append("stand-in: primitive index from the object's random value")
            n = self.shared("object info", lambda: self.node("ShaderNodeObjectInfo", "object info"))
            return self.math('FLOOR', self.binop('MULTIPLY', Val(n.outputs["Random"], 1), self.const(65535.0)))
        return self._hook("primitive_index", fallback)

    def custom_triplanar_normals(self, ins, p):
        # SelectAndTransformNormals: a tangent-space normal swizzled onto one
        # of three world planes, then normalized
        t = self.comps(self._in(ins, "unpackedNormalValue"))
        w = self.comps(self._in(ins, "worldNormal"))
        add, mul = (lambda a, b: self.binop('ADD', a, b)), (lambda a, b: self.binop('MULTIPLY', a, b))
        planes = [
            self.combine([mul(t[2], w[0]), add(t[0], w[1]), add(t[1], w[2])]),   # (tN.yx + wN.zy, tN.z wN.x).zyx
            self.combine([add(t[0], w[0]), mul(t[2], w[1]), add(t[1], w[2])]),   # (tN.xy + wN.xz, tN.z wN.y).xzy
            self.combine([add(t[0], w[0]), add(t[1], w[1]), mul(t[2], w[2])]),   # (tN.xy + wN.xy, tN.z wN.z)
        ]
        sel = self._in(ins, "selection")
        if sel.const:
            i = int(math.trunc(sel.s + 0.001))
            v = planes[i] if 0 <= i <= 2 else planes[2]
        else:
            idx = self.math('TRUNC', self.binop('ADD', sel, self.const(0.001)))
            v = planes[2]
            for i in (1, 0):
                v = self.select(self.math('COMPARE', idx, self.const(float(i)), self.const(0.5)), v, planes[i])
        return self.vmath('NORMALIZE', v, label="triplanar normal", out_w=3)

    def custom_rain_occluder(self, ins, p):
        # In == 0 ? 1 : OccluderOn
        zero = self.math('COMPARE', self.mask(self._in(ins, "In"), [0]), self.const(0.0), self.const(0.0))
        return self.select(zero if not zero.const else self.const(1.0 if zero.s else 0.0),
                           self._in(ins, "OccluderOn"), self.const(1.0))

    def _pick(self, sel, values):
        """values[round(sel)] for a runtime sel (a chain of compares)."""
        v = values[-1]
        for i in range(len(values) - 2, -1, -1):
            v = self.select(self.math('COMPARE', sel, self.const(float(i)), self.const(0.5)), v, values[i])
        return v

    def custom_select_0_15(self, ins, p):
        s = self.mask(self._in(ins, "Select"), [0])
        a, b = self._in(ins, "A"), self._in(ins, "B")
        if s.const:
            return a if 0 <= s.s <= 15 else b
        inside = self.binop('MULTIPLY', self.binop('SUBTRACT', self.const(1.0), self.math('LESS_THAN', s, self.const(0.0))),
                             self.binop('SUBTRACT', self.const(1.0), self.math('GREATER_THAN', s, self.const(15.0))))
        return self.select(inside, b, a)

    def custom_select4(self, ins, p):
        # inputs[clamp(int(selection - 1), 0, 3)]
        vals = [self._in(ins, k) for k in "ABCD"]
        s = self.mask(self._in(ins, "selection"), [0])
        if s.const:
            return vals[max(0, min(3, int(math.trunc(s.s - 1))))]
        i = self.math('MINIMUM', self.math('MAXIMUM', self.math('TRUNC', self.binop('SUBTRACT', s, self.const(1.0))),
                                                    self.const(0.0)), self.const(3.0))
        return self._pick(i, vals)

    def custom_select3(self, ins, p):
        # Select == 1 ? A : Select == 2 ? B : C
        s = self.mask(self._in(ins, "Select"), [0])
        a, b, c = self._in(ins, "A"), self._in(ins, "B"), self._in(ins, "C")
        if s.const:
            return a if s.s == 1 else b if s.s == 2 else c
        v = self.select(self.math('COMPARE', s, self.const(2.0), self.const(0.0)), c, b)
        return self.select(self.math('COMPARE', s, self.const(1.0), self.const(0.0)), v, a)

    def custom_select_eq4(self, ins, p):
        # if (Select == 1) A; else if (Select == 2) B; else if (Select == 3) C; else D
        s = self.mask(self._in(ins, "Select"), [0])
        a, b, c, d = (self._in(ins, k) for k in "ABCD")
        if s.const:
            return {1: a, 2: b, 3: c}.get(s.s, d)
        v = self.select(self.math('COMPARE', s, self.const(3.0), self.const(0.0)), d, c)
        v = self.select(self.math('COMPARE', s, self.const(2.0), self.const(0.0)), v, b)
        return self.select(self.math('COMPARE', s, self.const(1.0), self.const(0.0)), v, a)

    def custom_array_sample(self, ins, p):
        v = self.sample_array(self._tex_name(ins, "Tex"), self._in(ins, "UV"), "SAMPLERTYPE_Color")
        return Val(v.s, 3)

    def custom_array_conditional(self, ins, p):
        # Mask < 0.0001 ? Default : the array's texel (derivatives: mip 0)
        v = self.sample_array(self._tex_name(ins, "Texture"), self._in(ins, "UV"), "SAMPLERTYPE_Color")
        m = self.mask(self._in(ins, "Mask"), [0])
        off = self.math('LESS_THAN', m, self.const(0.0001)) if not m.const else self.const(1.0 if m.s < 0.0001 else 0.0)
        return self.select(off, v, self._in(ins, "Default"))

    def _number(self, v, default):
        """A scalar's number where building the material knows it: a constant, a parameter's own
        value (its group input's default, a Value node's); the default otherwise."""
        if v is None:
            return default
        if v.const:
            try:
                return float(v.s)
            except (TypeError, ValueError):
                return default
        node = v.s.node
        if node.type == 'VALUE':
            return float(node.outputs[0].default_value)
        if node.type == 'GROUP_INPUT':
            item = next((i for i in node.id_data.interface.items_tree
                         if i.item_type == 'SOCKET' and i.in_out == 'INPUT' and i.identifier == v.s.identifier), None)
            try:
                return float(item.default_value)
            except (AttributeError, TypeError, ValueError):
                return default
        return default

    def custom_raymarch_2d(self, ins, p):
        # a light march through a density texture, in the sprite's plane: step k (0 .. numSteps - 1)
        # moves the UV on by marchDir * (k * marchDistance / numSteps) / numSteps, reads the density
        # there (the texel over (numSteps - contrast), against ChannelSelect) and dims the light by it;
        # LO + LightColor * light * density comes out. The loop is laid out step by step: as many
        # as NumSteps says when the material is built.
        steps = int(round(self._number(ins.get("numSteps"), 16.0)))
        if steps > 64:
            self.warnings.append("approximate: a %d-step light march laid out as 64 steps" % steps)
        steps = max(1, min(steps, 64))
        count = self._in(ins, "numSteps", float(steps))
        tex, uv, march = self._tex_name(ins, "Tex"), ins.get("UV") or self.env.uv(0), self._in(ins, "marchDir")
        select = self._in(ins, "ChannelSelect", 1.0)
        # what one more step adds to the UV, over the step's number
        unit = self.binop('DIVIDE', self._in(ins, "marchDistance"), self.binop('MULTIPLY', count, count))
        stride = self.vmath('SCALE', self.zero_z(Val(march.s, 2)) if march.w >= 2 else self.combine([march, march, self.const(0.0)]), unit, out_w=2)
        thin = self.binop('SUBTRACT', count, self._in(ins, "contrast"))
        light = self._in(ins, "TransmittedLight", 1.0)
        light = self.mask(light, [0]) if light.w > 1 else light
        for k in range(steps):
            at = uv if k == 0 else self.vmath('ADD', uv, self.vmath('SCALE', stride, self.const(k * (k + 1) / 2.0), out_w=2), out_w=2)
            n = self.sample_node(tex, at, "SAMPLERTYPE_Color")
            texel = Val(n.outputs["Color"], 3)
            if select.w == 1:
                # (a scalar against the float4 texel: every channel)
                density = self.binop('MULTIPLY', self.binop('ADD', self.vmath('DOT_PRODUCT', texel, self.const((1.0, 1.0, 1.0), 3)),
                                                            Val(n.outputs["Alpha"], 1)), select)
            else:
                density = self.vmath('DOT_PRODUCT', texel, self.as3(select))
                if select.w == 4:
                    density = self.binop('ADD', density, self.binop('MULTIPLY', Val(n.outputs["Alpha"], 1), self.alpha(select)))
            density = self.math('DIVIDE', density, thin, clamp=True)
            light = self.binop('MULTIPLY', light, self.math('SUBTRACT', self.const(1.0), density, clamp=True))
        lit = self.binop('MULTIPLY', self.binop('MULTIPLY', self._in(ins, "LightColor", 1.0), light), self._in(ins, "density", 1.0))
        return self.binop('ADD', self._in(ins, "LO"), lit)

    def custom_pcg3d16(self, ins, p):
        # an integer hash of the cell: Blender's white noise per cell has the
        # same use (a random vector per integer point), not the same bits
        self.warnings.append("stand-in: pcg3d16 hash as white noise")
        n = self.node("ShaderNodeTexWhiteNoise", "hash (white noise)", noise_dimensions='3D')
        self.link(self.vmath('FLOOR', self.as3(self._in(ins, "x")), out_w=3), n.inputs["Vector"])
        return Val(n.outputs["Color"], 3)

    def custom_light_direction(self, ins, p):
        return self.env.light_direction()

    def custom_light_color(self, ins, p):
        return self.with_alpha(self.light_color(), self.const(1.0))

    def custom_world_to_clip(self, ins, p):
        # UE's WorldToClip: view space, the camera's projection, reversed-Z
        # infinite far plane (clip z = the near plane, 10 cm)
        view = self.comps(self.transform(self.as3(self._in(ins, "In")), "world", "view", point=True))
        tan = self.view_property("TanHalfFieldOfView")
        tx, ty = self.comps(tan)[:2]
        x = self.binop('DIVIDE', view[0], tx)
        y = self.binop('DIVIDE', view[1], ty)
        return self.with_alpha(self.combine([x, y, self.const(10.0)]), view[2])

    def custom_smoothstep(self, ins, p):
        return self.smoothstep(self._in(ins, "varMin"), self._in(ins, "varMax"), self._in(ins, "varA"))

    def custom_zero(self, ins, p):
        return self.const(0.0)

    def custom_nan(self, ins, p):
        return self.const(0.0)

    def custom_ggx_d(self, ins, p):
        # NoH = dot(normalize(N + L), N); a2 = R^4; d = (NoH * a2 - NoH) * NoH + 1; a2 / (PI d d)
        n, l = self.as3(self._in(ins, "Normal")), self.as3(self._in(ins, "LightVector"))
        r = self.mask(self._in(ins, "Roughness"), [0])
        noh = self.vmath('DOT_PRODUCT', self.vmath('NORMALIZE', self.vmath('ADD', n, l, out_w=3), out_w=3), n)
        r2 = self.binop('MULTIPLY', r, r)
        a2 = self.binop('MULTIPLY', r2, r2)
        d = self.binop('ADD', self.binop('MULTIPLY', self.binop('SUBTRACT', self.binop('MULTIPLY', noh, a2), noh), noh),
                       self.const(1.0))
        return self.divide(a2, self.binop('MULTIPLY', self.const(3.14159265), self.binop('MULTIPLY', d, d)))

    def custom_fp_select(self, ins, p):
        fp = self.mask(self._in(ins, "FP"), [0])
        wpo, wpo_fp = self._in(ins, "WPO"), self._in(ins, "WPO_FP")
        if fp.const:
            return wpo_fp if fp.s else wpo
        on = self.binop('SUBTRACT', self.const(1.0), self.math('COMPARE', fp, self.const(0.0), self.const(0.0)))
        return self.select(on, wpo, wpo_fp)

    def _culls(self, g, ref):
        """Whether an input is a Custom node giving a NaN (a vertex UE drops: custom_nan)."""
        if not linked(ref):
            return False
        x = g.by.get(g.key(ref))
        return x is not None and x["Type"].endswith("Custom") and custom_handler(x.get("Properties") or {}) == "custom_nan"

    def custom_sign(self, ins, p):
        return self.unary('SIGN', self._in(ins, "x"))

    def custom_length(self, ins, p):
        v = self._in(ins, "x")
        return self.math('ABSOLUTE', v) if v.w == 1 else self.vmath('LENGTH', self.as3(v))

    def custom_atan2(self, ins, p):
        return self.math('ARCTAN2', self.mask(self._in(ins, "y"), [0]), self.mask(self._in(ins, "x"), [0]))

    def custom_bounds_min(self, ins, p):
        return self.local_bounds()[0]

    def custom_bounds_max(self, ins, p):
        return self.local_bounds()[1]

    def custom_bounds_extent(self, ins, p):
        mn, mx = self.local_bounds()
        return self.vmath('SCALE', self.vmath('SUBTRACT', mx, mn, out_w=3), self.const(0.5), out_w=3)

    def custom_bounds_center(self, ins, p):
        mn, mx = self.local_bounds()
        return self.vmath('SCALE', self.vmath('ADD', mx, mn, out_w=3), self.const(0.5), out_w=3)

    def custom_tan_half_fov(self, ins, p):
        return self.mask(self.view_property("TanHalfFieldOfView"), [0])

    def custom_fov(self, ins, p):
        return self.mask(self.view_property("FieldOfView"), [0])

    def custom_bitfield(self, ins, p):
        # (uint(Scalar) >> BitIndex) & ((1 << BitCount) - 1), exact below 2^24
        v = self.math('TRUNC', self.mask(self._in(ins, "Scalar"), [0]))
        idx, cnt = self.mask(self._in(ins, "BitIndex"), [0]), self.mask(self._in(ins, "BitCount"), [0])
        shifted = self.math('FLOOR', self.binop('DIVIDE', v, self.math('POWER', self.const(2.0), idx)))
        return self.math('FLOORED_MODULO', shifted, self.math('POWER', self.const(2.0), cnt), label="bit field")

    def float_fields(self, f):
        """asuint(f) as its three fields - sign (1 bit), exponent (8), mantissa
        (23) - each exact in float maths: a float can't hold all 32 bits at
        once, but every field fits in its 24-bit integers. Normal and
        subnormal floats (0 is all zeros)."""
        a = self.math('ABSOLUTE', f)
        sign = self.math('LESS_THAN', f, self.const(0.0))
        tiny = self.math('LESS_THAN', a, self.const(2.0 ** -126))
        e = self.math('FLOOR', self.math('LOGARITHM', self.math('MAXIMUM', a, self.const(2.0 ** -126)), self.const(2.0)))
        # log2 can land a hair off at exact powers of two: settle it
        e = self.binop('SUBTRACT', e, self.math('LESS_THAN', a, self.math('POWER', self.const(2.0), e)))
        e = self.binop('ADD', e, self.math('GREATER_THAN', a, self.binop('SUBTRACT', self.math(
            'POWER', self.const(2.0), self.binop('ADD', e, self.const(1.0))), self.const(0.0))))
        mant_n = self.binop('MULTIPLY', self.binop('SUBTRACT', self.binop('DIVIDE', a, self.math('POWER', self.const(2.0), e)),
                                                   self.const(1.0)), self.const(2.0 ** 23))
        mant_s = self.binop('MULTIPLY', self.binop('MULTIPLY', a, self.const(2.0 ** 100)), self.const(2.0 ** 49))
        exp = self.select(tiny, self.binop('ADD', e, self.const(127.0)), self.const(0.0))
        mant = self.math('ROUND', self.select(tiny, mant_n, mant_s))
        return sign, exp, mant

    def bits(self, f, index, count):
        """(asuint(f) >> index) & ((1 << count) - 1), for constant index and
        count: pieced together from the fields it spans."""
        sign, exp, mant = self.float_fields(f)
        high = self.binop('ADD', self.binop('MULTIPLY', sign, self.const(256.0)), exp)   # bits 23..31
        pieces = []
        if index < 23:
            take = min(count, 23 - index)
            low = self.math('FLOOR', self.binop('DIVIDE', mant, self.const(2.0 ** index)))
            pieces.append((self.math('FLOORED_MODULO', low, self.const(2.0 ** take)), 0))
        if index + count > 23:
            start = max(index, 23) - 23
            take = index + count - max(index, 23)
            hi = self.math('FLOORED_MODULO', self.math('FLOOR', self.binop('DIVIDE', high, self.const(2.0 ** start))),
                           self.const(2.0 ** take))
            pieces.append((hi, max(23 - index, 0)))
        v = None
        for piece, shift in pieces:
            piece = self.binop('MULTIPLY', piece, self.const(2.0 ** shift)) if shift else piece
            v = piece if v is None else self.binop('ADD', v, piece)
        return v if v is not None else self.const(0.0)

    def custom_bitfield_asuint(self, ins, p):
        idx, cnt = self.mask(self._in(ins, "BitIndex"), [0]), self.mask(self._in(ins, "BitCount"), [0])
        if not (idx.const and cnt.const):
            self.warnings.append("stand-in: asuint bit field with a varying range, on the value")
            return self.custom_bitfield(ins, p)
        return self.bits(self.mask(self._in(ins, "Scalar"), [0]), int(idx.s), int(cnt.s))

    def custom_packed_hsv(self, ins, p):
        # H: bits 20..31 / 360, S: bits 10..19 / 1023, V: bits 0..9 / 1023
        f = self.mask(self._in(ins, "PackedHSV"), [0])
        h = self.binop('DIVIDE', self.bits(f, 20, 12), self.const(360.0))
        s_ = self.binop('DIVIDE', self.bits(f, 10, 10), self.const(1023.0))
        v = self.binop('DIVIDE', self.bits(f, 0, 10), self.const(1023.0))
        return self.combine([h, s_, v])

    def custom_hue_to_rgb(self, ins, p):
        h = self.math('MODULO', self.mask(self._in(ins, "Hue"), [0]), self.const(1.0))
        h6 = self.binop('MULTIPLY', h, self.const(6.0))
        r = self.binop('SUBTRACT', self.math('ABSOLUTE', self.binop('SUBTRACT', h6, self.const(3.0))), self.const(1.0))
        g = self.binop('SUBTRACT', self.const(2.0), self.math('ABSOLUTE', self.binop('SUBTRACT', h6, self.const(2.0))))
        b = self.binop('SUBTRACT', self.const(2.0), self.math('ABSOLUTE', self.binop('SUBTRACT', h6, self.const(4.0))))
        return self.saturate(self.combine([r, g, b]))

    # ------------------------------------------------------------ water
    # The Water plugin draws each water body's surface mesh into its zone's
    # water info texture at run time (DrawWaterInfo: the vertex colour's flow,
    # the surface height, the ground height under it); materials decode it.
    # A material on the surface mesh itself reads the same things off the
    # pixel: its height, its vertex colour, the depth the env knows.
    def custom_water_info_z(self, ins, p):
        # DecodeWaterInfoZHeight: the water's height here - the surface's own
        return self.comps(self.env.world_position(False))[2]

    def custom_water_info_ground(self, ins, p):
        # DecodeWaterInfoGroundHeight: the ground under the surface
        return self.binop('SUBTRACT', self.comps(self.env.world_position(False))[2], self.water_depth(),
                          label="ground under the water")

    def custom_water_info_velocity(self, ins, p):
        # DecodeWaterInfoVelocity(sample, MaxVelocity) = (sample.xy - 0.5) * 2 * MaxVelocity, of
        # DrawWaterInfo's (Flow velocity / (2 * its MaxVelocity) + 0.5): the surface's flow
        return self._flow_velocity(self.water_flow(), self.mask(self._in(ins, "MaxVelocity", 1024.0), [0]))

    def custom_water_flow(self, ins, p):
        return self._flow_velocity(self._in(ins, "Flow"), self.mask(self._in(ins, "MaxVelocity", 1024.0), [0]))

    def _flow_velocity(self, flow, max_velocity):
        """float Magnitude = Flow.x * MaxVelocity; float Direction = Flow.y * 2 * PI;
        return float2(Magnitude * cos(Direction), Magnitude * sin(Direction));"""
        speed, turn = self.comps(flow)[:2]
        mag = self.binop('MULTIPLY', speed, max_velocity)
        ang = self.binop('MULTIPLY', turn, self.const(2.0 * math.pi))
        return self.combine([self.binop('MULTIPLY', mag, self.math('COSINE', ang)),
                             self.binop('MULTIPLY', mag, self.math('SINE', ang))])

    def water_flow(self):
        """The surface's flow as DrawWaterInfo reads it: vertex colour R =
        speed / MaxFlowVelocity, G = direction / 2 pi (a river's info mesh
        carries it; still water's is black)."""
        return self._hook("water_flow", lambda: self.mask(self.env.vertex_color()[0], [0, 1]))

    def custom_water_body_fixed(self, ins, p):
        # FixedVelocity / FixedZHeight / FixedWaterDepth of the body's runtime
        # data (read only behind the Use Fixed switches; the snippet returns 0)
        self.warnings.append("stand-in: water body's fixed velocity / height / depth as 0")
        return self.const((0.0, 0.0, 0.0), 3) if getattr(self, "custom_out", 0) == 1 else self.const(0.0)

    def custom_water_zone(self, ins, p):
        # where the zone's water info texture lies: only that texture's UVs
        # read it, and the decodes above don't sample it
        self.warnings.append("stand-in: water zone (location 0, extent 1)")
        return [self.const((0.0, 0.0), 2), self.const((1.0, 1.0), 2), self.const((1.0, 1.0), 2),
                self.const(0.0)][min(getattr(self, "custom_out", 0), 3)]

    def custom_gerstner_waves(self, ins, p):
        # the body's waves are generated at run time (its wave asset's
        # generator): still water - no offset, the surface's own normal
        out = getattr(self, "custom_out", 0)
        self.warnings.append("stand-in: Gerstner waves as still water")
        if out in (1, 2, 3):
            return self.const((0.0, 0.0, 1.0), 3)
        return self.const((0.0, 0.0, 0.0), 3) if out else self.const(0.0)

    def custom_hole_clip(self, ins, p):
        # if (Mask == 0) clip(-1); return PassThru: the pixel isn't drawn
        # where the mask is 0 - kept for the material's opacity mask
        names = [i.get("InputName") for i in p.get("Inputs", [])]
        mask = next((n for n in names if "Mask" in str(n)), names[-1])
        through = next((n for n in names if n != mask), names[0])
        hole = self.math('COMPARE', self.mask(self._in(ins, mask), [0]), self.const(0.0), self.const(0.0))
        self.clip(self.binop('SUBTRACT', self.const(1.0), hole, label="not a hole"))
        return self._in(ins, through)

    def custom_hit_proxy_clip(self, ins, p):
        # the clip is only compiled into editor hit-proxy shaders
        return self._in(ins, "PassThrough")

    def custom_dynamic_bounds(self, ins, p):
        # the water's dynamic bounds are set at run time (none: nothing clipped)
        self.warnings.append("stand-in: water dynamic bounds clip() not applied")
        return self._in(ins, "Color")

    def clip(self, keep):
        """A clip() in the material's own graph: where `keep` is 0 the pixel
        isn't drawn (the build multiplies its opacity mask by clips)."""
        if self.function is None:
            self.clips.append(keep)
        else:
            self.warnings.append("clip() inside %s: the pixels it discards are drawn" % self.function.fname)

    def custom_one_minus_exp(self, ins, p):
        # return 1 - exp(-x), per component
        x = self._in(ins, "x")
        w = {"CMOT_Float1": 1, "CMOT_Float2": 2, "CMOT_Float3": 3}.get(
            str(p.get("OutputType", "")).split("::")[-1], min(x.w, 3))
        return self.combine([self.binop('SUBTRACT', self.const(1.0),
                                        self.math('EXPONENT', self.binop('MULTIPLY', c, self.const(-1.0))))
                             for c in self.comps(x)[:w]])

    def custom_euler_to_quat(self, ins, p):
        # roll, pitch, yaw (Euler.xyz, degrees) -> q (xyz, w)
        e = self.comps(self._in(ins, "Euler"))
        k = self.binop('DIVIDE', self.mask(self._in(ins, "M_PI", math.pi), [0]), self.const(360.0))
        roll, pitch, yaw = (self.binop('MULTIPLY', c, k) for c in e)
        c1, s1 = self.math('COSINE', yaw), self.math('SINE', yaw)
        c2, s2 = self.math('COSINE', pitch), self.math('SINE', pitch)
        c3, s3 = self.math('COSINE', roll), self.math('SINE', roll)

        def m3(a, b, c):
            return self.binop('MULTIPLY', self.binop('MULTIPLY', a, b), c)
        w = self.binop('ADD', m3(c1, c2, c3), m3(s1, s2, s3))
        x = self.binop('SUBTRACT', m3(c1, c2, s3), m3(s1, s2, c3))
        y = self.binop('ADD', m3(c1, s2, c3), m3(s1, c2, s3))
        z = self.binop('SUBTRACT', m3(s1, c2, c3), m3(c1, s2, s3))
        return self.with_alpha(self.combine([x, y, z]), w)

    def custom_clip(self, ins, p):
        # clip() discards the pixel: as a value, 0 there
        o, th = self.mask(self._in(ins, "Opacity"), [0]), self.mask(self._in(ins, "Threshold"), [0])
        self.warnings.append("stand-in: clip() as zero opacity")
        return self.binop('MULTIPLY', o, self.binop('SUBTRACT', self.const(1.0), self.math('LESS_THAN', o, th)))

    def custom_eye_adaptation_inverse(self, ins, p):
        # LightValue * exp(-Alpha * ln(Adaptation)) = LightValue * Adaptation ^ -Alpha
        lv, a, ad = self._in(ins, "LightValue"), self._in(ins, "Alpha"), self._in(ins, "Adaptation", 1.0)
        if ad.const and ad.s == 1.0:
            return lv
        scale = self.math('EXPONENT', self.binop('MULTIPLY', self.binop('MULTIPLY', a, self.const(-1.0)),
                                                 self.math('LOGARITHM', ad, self.const(math.e))))
        return self.binop('MULTIPLY', lv, scale)

    def custom_oct_decode(self, ins, p):
        o = self.comps(self._in(ins, "Oct"))
        x = self.binop('MULTIPLY', self.binop('ADD', o[0], o[1]), self.const(0.5))
        y = self.binop('MULTIPLY', self.binop('SUBTRACT', o[0], o[1]), self.const(0.5))
        z = self.binop('SUBTRACT', self.const(1.0), self.binop('ADD', self.math('ABSOLUTE', x), self.math('ABSOLUTE', y)))
        return self.vmath('NORMALIZE', self.combine([x, y, z]), out_w=3)

    def custom_oct_encode(self, ins, p):
        n = self.comps(self._in(ins, "N"))
        d = self.binop('ADD', self.binop('ADD', self.math('ABSOLUTE', n[0]), self.math('ABSOLUTE', n[1])),
                       self.math('ABSOLUTE', n[2]))
        x, y = self.binop('DIVIDE', n[0], d), self.binop('DIVIDE', n[1], d)
        return self.combine([self.binop('ADD', x, y), self.binop('SUBTRACT', x, y)])

    def custom_taa_params(self, ins, p):
        # (sample index, sample count): a still frame, one sample
        return self.const((0.0, 1.0), 2)

    def custom_refract(self, ins, p):
        # HLSL refract(i, n, eta) is Vector Math's Refract (eta on its Scale)
        n = self.node("ShaderNodeVectorMath", "refract", operation='REFRACT')
        self.link(self.as3(self._in(ins, "Ray")), n.inputs[0])
        self.link(self.as3(self._in(ins, "Normal")), n.inputs[1])
        self.link(self.mask(self._in(ins, "Index", 1.0), [0]), n.inputs["Scale"])
        return Val(n.outputs["Vector"], 3)

    def custom_main_pass(self, ins, p):
        return self._in(ins, "Main")

    def custom_height_band(self, ins, p):
        n = ins["NormAltitude"]
        keep = self.binop('MULTIPLY', self.binop('SUBTRACT', self.const(1.0), self.math('LESS_THAN', n, self.const(0.05))),
                          self.binop('SUBTRACT', self.const(1.0), self.math('GREATER_THAN', n, self.const(0.95))))
        return self.binop('MULTIPLY', ins["Density"], keep, label="layer 5%..95%")

    def side_output(self, path, type_name, pins):
        """The inputs of a material's side output node (e.g.
        VolumetricAdvancedMaterialOutput), each translated or its default."""
        g = self.graph(path)
        x = next((y for y in g.o if T(y) == type_name), None)
        p = (x or {}).get("Properties") or {}
        out = {}
        for pin, (const_key, default) in pins.items():
            dflt = p.get(const_key, default) if const_key else default
            out[pin] = self.input(g, p.get(pin), {}, self.const(float(dflt)))
        return out

    # ---------------------------------------------------------- textures
    def sample_volume(self, tname, coords, out):
        """A volume texture, as UE samples one: trilinear, wrapping on all
        three axes. The texture is a vertical stack of its slices (CUE4Parse
        decodes it that way, slice 0 at the top); eight nearest taps weighted
        here, as a Linear image node would take Eevee's mipmaps."""
        img, size, depth = self.env.volume(tname)
        if coords is None:
            coords = self.const((0.0, 0.0, 0.0), 3)
        c = self.comps(coords)
        dims = (float(size), float(size), float(depth))
        corners = []
        for i in range(3):
            fr = self.math('FRACT', c[i])
            xi = self.binop('SUBTRACT', self.binop('MULTIPLY', fr, self.const(dims[i])), self.const(0.5))
            lo = self.math('FLOOR', xi)
            f = self.binop('SUBTRACT', xi, lo)
            lo_w = self.math('FLOORED_MODULO', lo, self.const(dims[i]))
            hi_w = self.math('FLOORED_MODULO', self.binop('ADD', lo, self.const(1.0)), self.const(dims[i]))
            corners.append(((lo_w, self.binop('SUBTRACT', self.const(1.0), f)), (hi_w, f)))
        rows = float(size * depth)
        rgb, alpha = None, None
        for xv, xw in corners[0]:
            for yv, yw in corners[1]:
                for zv, zw in corners[2]:
                    row = self.binop('ADD', self.binop('MULTIPLY', zv, self.const(float(size))), yv)
                    u = self.binop('DIVIDE', self.binop('ADD', xv, self.const(0.5)), self.const(float(size)))
                    v = self.binop('SUBTRACT', self.const(1.0),
                                   self.binop('DIVIDE', self.binop('ADD', row, self.const(0.5)), self.const(rows)))
                    n = self.node("ShaderNodeTexImage", tname, interpolation='Closest', extension='EXTEND')
                    n.image = img
                    self.link(self.combine([u, v, self.const(0.0)]), n.inputs[0])
                    w = self.binop('MULTIPLY', self.binop('MULTIPLY', xw, yw), zw)
                    tap = self.vmath('SCALE', Val(n.outputs["Color"], 3), w, out_w=3)
                    ta = self.binop('MULTIPLY', Val(n.outputs["Alpha"], 1), w)
                    rgb = tap if rgb is None else self.vmath('ADD', rgb, tap, out_w=3)
                    alpha = ta if alpha is None else self.binop('ADD', alpha, ta)
        if out == 5:
            return self.with_alpha(rgb, alpha)
        if out == 0:
            return rgb
        if out == 4:
            return alpha
        return self.mask(rgb, [out - 1])

    # UE's TextureAddress -> the image node's extension (TA_Clamp clamps to the edge texel: EXTEND)
    EXTENSION = {"Wrap": 'REPEAT', "Clamp": 'EXTEND', "Mirror": 'MIRROR'}

    def address_mode(self, tname, own, address, img):
        """(extension, per-axis fixes) for a texture's addressing: its own (env.texture_address,
        AddressX/AddressY) through its own sampler, else the shared sampler's. One extension
        serves both axes; an axis addressed otherwise is fixed on the coordinate: a clamped one
        held between the edge texels' centres (bilinear filtering then never reaches across),
        a mirrored one folded (ping-pong)."""
        if address is None:
            address = self._hook("texture_address", lambda: ("Wrap", "Wrap"), tname) if own else ("Wrap", "Wrap")
        ax, ay = (tuple(address) + ("Wrap", "Wrap"))[:2]
        if ax == ay:
            return self.EXTENSION.get(ax, 'REPEAT'), ()
        ext = 'REPEAT' if "Wrap" in (ax, ay) else 'MIRROR'
        size = tuple(img.size) if img is not None else (0, 0)
        fixes = []
        for i, a in enumerate((ax, ay)):
            if a == "Clamp":
                fixes.append((i, "clamp", 0.5 / size[i] if size[i] else 0.0))
            elif a == "Mirror" and ext == 'REPEAT':
                fixes.append((i, "mirror", 0.0))
        return ext, tuple(fixes)

    def addressed(self, vec, fixes):
        if not fixes:
            return vec
        c = list(self.comps(vec))
        for i, kind, half in fixes:
            if kind == "clamp":
                c[i] = self.math('MAXIMUM', self.math('MINIMUM', c[i], self.const(1.0 - half)), self.const(half),
                                 label="clamp (TA_Clamp)")
            else:
                c[i] = self.math('PINGPONG', c[i], self.const(1.0), label="mirror (TA_Mirror)")
        return self.combine(c)

    def texture_closure(self, tname, sampler, img, own, address):
        """The closure sampling a 2D texture (Vector -> Color, Alpha), one per texture and sampler:
        at the material's root a closure zone around the texture's image node, in the Textures
        frame; in a function's group a Closure input its caller fills (env.texture_closures)."""
        spec = (str(tname), getattr(tname, "param", None), sampler or "", img.name if img is not None else "",
                bool(own), tuple(address) if address else None)
        if self.function is not None:
            return self.function.texture_input(spec, tname, sampler, img, own, address)
        # the env may take it outside this tree (a material's group: a Closure input, the image
        # node in the material's own tree - env.root_texture)
        outside = getattr(self.env, "root_texture", None)
        got = outside(spec, tname, sampler, img, own, address) if outside is not None else None
        if got is not None:
            return got
        return self.shared(("texture", spec), lambda: self._texture_zone(tname, img, own, address))

    def _texture_zone(self, tname, img, own, address):
        """A closure zone around a texture's image node (in the Textures section); its Closure socket."""
        nearest = own and self._hook("texture_nearest", lambda: False, tname)
        ext, fixes = self.address_mode(tname, own, address, img)
        label = getattr(tname, "param", None) or short_name(str(tname))
        with self.at("Textures"):
            cin = self.node("NodeClosureInput", label)
            cout = self.node("NodeClosureOutput", label)
            cout.input_items.new('VECTOR', "Vector")
            cout.output_items.new('RGBA', "Color")
            cout.output_items.new('FLOAT', "Alpha")
            cin.pair_with_output(cout)
            for z in (cin, cout):
                # the zone's ends collapsed (as FortnitePorting draws its texture closures)
                z.hide = True
                z.width = 100
            n = self.node("ShaderNodeTexImage", short_name(str(tname)), interpolation='Closest' if nearest else 'Linear',
                          extension=ext)
            n.image = img
            # collapsed and narrow: a column of textures, one row each (its label names the image)
            n.hide = True
            n.width = 160
            if getattr(tname, "param", None):
                n["mp_tex_param"] = tname.param     # which parameter's texture this is (another instance swaps it)
            self.link(self.addressed(Val(cin.outputs[0], 3), fixes), n.inputs[0])
            self.L.new(n.outputs["Color"], cout.inputs["Color"])
            self.L.new(n.outputs["Alpha"], cout.inputs["Alpha"])
        return cout.outputs[0]

    def sample_node(self, tname, coords, sampler, img=None, own=True, address=None):
        """A node reading a 2D texture at UE UVs, with outputs Color and Alpha (unfiltered when the
        texture is, read through its own sampler: a LUT sampled at a texel's centre stays exact):
        its image node, or with env.texture_closures an Evaluate Closure of the texture's closure."""
        if img is None:
            img = self.env.texture(tname, sampler)
        u, v = self.comps(coords)[:2]
        # UE UVs run top-left; Blender samples bottom-left
        vec = self.combine([u, self.binop('SUBTRACT', self.const(1.0), v), self.const(0.0)])
        if getattr(self.env, "texture_closures", False):
            n = self.node("NodeEvaluateClosure", getattr(tname, "param", None) or short_name(str(tname)))
            n.input_items.new('VECTOR', "Vector")
            n.output_items.new('RGBA', "Color")
            n.output_items.new('FLOAT', "Alpha")
            self.L.new(self.texture_closure(tname, sampler, img, own, address), n.inputs[0])
            self.link(vec, n.inputs["Vector"])
            if img is not None:
                n["mp_image"] = img.name        # the image it reads (env._images_upstream)
            return n
        nearest = own and self._hook("texture_nearest", lambda: False, tname)
        ext, fixes = self.address_mode(tname, own, address, img)
        n = self.node("ShaderNodeTexImage", short_name(tname), interpolation='Closest' if nearest else 'Linear', extension=ext)
        n.image = img
        if getattr(tname, "param", None):
            n["mp_tex_param"] = tname.param     # which parameter's texture this is (another instance swaps it)
        self.link(self.addressed(vec, fixes), n.inputs[0])
        return n

    def unpack_normal(self, rgb):
        """UnpackNormalMap, what a Normal sampler returns (BC5 on PC): xy = rg * 2 - 1,
        z = sqrt(saturate(1 - xy.xy)); alpha 1. (rgb, alpha)"""
        r, gr = self.comps(rgb)[:2]
        x = self.binop('SUBTRACT', self.binop('MULTIPLY', r, self.const(2.0)), self.const(1.0))
        y = self.binop('SUBTRACT', self.binop('MULTIPLY', gr, self.const(2.0)), self.const(1.0))
        d = self.binop('ADD', self.binop('MULTIPLY', x, x), self.binop('MULTIPLY', y, y))
        z = self.math('SQRT', self.saturate(self.binop('SUBTRACT', self.const(1.0), d)))
        return self.combine([x, y, z]), self.const(1.0)

    def sample(self, tname, coords, out, sampler, own=True, address=None):
        n = self.sample_node(tname, coords, sampler, own=own, address=address)
        if "Normal" in (sampler or ""):
            return self.rgba_out(*self.unpack_normal(Val(n.outputs["Color"], 3)), out)
        rgb = Val(n.outputs["Color"], 3)
        if out == 5:
            return self.with_alpha(rgb, Val(n.outputs["Alpha"], 1))
        if out == 0:
            return rgb
        if out == 4:
            return Val(n.outputs["Alpha"], 1)
        sep = self.node("ShaderNodeSeparateColor", "rgb")
        self.L.new(n.outputs["Color"], sep.inputs[0])
        return Val(sep.outputs[out - 1], 1)

    def sample_cube(self, tname, direction, out):
        """Equirect lookup in UE space: u = atan2(y, x) / 2 pi + 0.5, v = asin(z) / pi + 0.5."""
        img = self.env.cube(tname)
        d = self.vmath('NORMALIZE', direction, out_w=3)
        x, y, z = self.comps(d)
        u = self.binop('ADD', self.binop('DIVIDE', self.math('ARCTAN2', y, x), self.const(2 * math.pi)), self.const(0.5))
        v = self.binop('ADD', self.binop('DIVIDE', self.math('ARCSINE', z), self.const(math.pi)), self.const(0.5))
        n = self.node("ShaderNodeTexImage", tname, interpolation='Linear', extension='EXTEND')
        n.image = img
        self.link(self.combine([u, v, self.const(0.0)]), n.inputs[0])
        rgb = Val(n.outputs["Color"], 3)
        if out == 5:
            return self.with_alpha(rgb, Val(n.outputs["Alpha"], 1))
        if out == 0:
            return rgb
        if out == 4:
            return Val(n.outputs["Alpha"], 1)
        sep = self.node("ShaderNodeSeparateColor", "rgb")
        self.L.new(n.outputs["Color"], sep.inputs[0])
        return Val(sep.outputs[out - 1], 1)

    # --------------------------------------------------------- functions
    _scope_id = [0]

    def function_graph(self, x):
        """(name, Graph) of the function a MaterialFunctionCall calls, or None."""
        mf = x["Properties"].get("MaterialFunction") or {}
        on = mf.get("ObjectName", "")
        fname = on.split("'")[1] if "'" in on else on
        try:
            path = self.env.function(fname, mf.get("ObjectPath", ""))
        except TypeError:
            # an env that only takes the name (names can repeat across folders)
            path = self.env.function(fname)
        return (fname, self.graph(path)) if path else None

    @staticmethod
    def function_output(fg, outs, out):
        """The FunctionOutput a call's output index reads."""
        out_id = outs[out]["ExpressionOutputId"] if out < len(outs) else None
        fo = fg.outputs.get(out_id)
        if fo is None:
            fo = list(fg.outputs.values())[out] if out < len(fg.outputs) else None
        return fo

    def call(self, g, x, out, scope):
        p = x["Properties"]
        fname = (p.get("MaterialFunction") or {}).get("ObjectName", "").split("'")[1]
        outs = p.get("FunctionOutputs", [])
        # Inputs bind lazily: UE compiles each function output on its own, so
        # an output that never reads an input must not evaluate it. The sky's
        # horizon-hills mask feeds the chain that ends in the same function's
        # colour input - eager binding turns that into a cycle.
        ins = {fi.get("ExpressionInputId"): _Lazy(g, fi.get("Input"), scope, self.section)
               for fi in p.get("FunctionInputs", [])}
        special = self.env.special_function(fname, _SpecialInputs(self, list(ins.values())))
        if special is not None:
            return special.get(out, self.const(0.0))
        found = self.function_graph(x)
        if found is None:
            self.warnings.append("no graph for function %s -> 0" % fname)
            return self.const(0.0)
        fg = found[1]
        # a texture can't cross a node-group socket: a function taking one
        # (Flowmaps_3D takes its noise volume) is inlined into its caller
        takes_texture = any("Texture" in str((x.get("Properties") or {}).get("InputType", ""))
                            for x in fg.inputs.values())
        if getattr(self.env, "nest_functions", False) and not takes_texture:
            return self.call_group(fname, fg, outs, out, ins, (id(x), g.path, scope.get("_id", 0)))
        Translator._scope_id[0] += 1
        sub = dict(ins)
        sub["_id"] = (id(x), g.path, scope.get("_id", 0))
        fo = self.function_output(fg, outs, out)
        if fo is None:
            return self.const(0.0)
        saved = self.section
        self.section = saved + [section_name(fname)]
        try:
            return self.input(fg, fo["Properties"].get("A"), sub, self.const(0.0))
        finally:
            self.section = saved


    def _closes_loop(self, node, src):
        """Whether a link from `src` (an output socket) into `node` would close a loop: `node`
        already reaches src's node."""
        target = src.node.name
        nxt = {}
        for l in self.L:
            nxt.setdefault(l.from_node.name, []).append(l.to_node.name)
        seen, todo = {node.name}, [node.name]
        while todo:
            a = todo.pop()
            if a == target:
                return True
            for b in nxt.get(a, ()):
                if b not in seen:
                    seen.add(b)
                    todo.append(b)
        return False

    def call_group(self, fname, fg, outs, out, ins, site=None):
        fo = self.function_output(fg, outs, out)
        if fo is None:
            return self.const(0.0)
        statics = self.function_statics(fg, ins)
        # by graph: two functions can share a name in different folders
        key = (fg.path, tuple(sorted(statics.items()))) if statics else fg.path
        ft = self.functions.get(key)
        if ft is None:
            ft = self.functions[key] = FunctionTree(self, fname, fg, statics, self.variant_label(fname, fg, statics))
            if getattr(self.env, "whole_functions", False):
                # every output, in the function's own order: two materials calling it build the same
                # group, which they then share (built as each asked, their groups differed by what
                # each read - a copy of the function per material). Unread outputs cost nothing at
                # render: Blender drops what a material's output doesn't reach.
                for each in fg.outputs.values():
                    try:
                        ft.output(each)
                    except RuntimeError as e:       # (an output UE would compile on its own: a loop here)
                        self.warnings.append("%s: output %s left out (%s)" % (fname, (each.get("Properties") or {}).get("OutputName"), e))
        name, w = ft.output(fo)

        def fresh():
            n = self.node("ShaderNodeGroup", section_name(fname))
            n.node_tree = ft.tree
            return n, set()

        # One node per call, whichever outputs are read: UE compiles each output on its own,
        # and a node per output read drew the same function three times over (Pre FX's M,
        # Distance Blend and Pre Skinned Local Position). Each output still links only the
        # inputs it reaches, as it's read; one whose input would come from the node's own
        # output (a loop UE never sees) gets a node of its own instead.
        if w == "attrs" and not any(o[0] == "socket" for o in ft.attr_outs[fo["Properties"].get("Id")].values()):
            node, linked = None, set()
        else:
            had = self.call_sites.get(site) if site is not None else None
            if had is not None and had[0].node_tree is ft.tree:
                node, linked = had
                self.shared_calls.add(node.name)
            else:
                node, linked = fresh()
                if site is not None:
                    self.call_sites[site] = (node, linked)

        def link_needs(needs, node, linked):
            # the env learns which function a parameter is reached through (a
            # material's parameters can be grouped by it)
            caller = getattr(self.env, "caller", None)
            if self.function is None:
                self.env.caller = section_name(fname)
            try:
                for sock in sorted(needs - linked):
                    linked.add(sock)
                    link_one(sock, node, linked)
            finally:
                self.env.caller = caller

        def attach(needs, node, linked):
            """Link `needs` into the call's node, or into a node of their own where that loops."""
            try:
                link_needs(needs, node, linked)
                return node
            except _Loop:
                own, mine = fresh()
                link_needs(needs, own, mine)
                return own

        def link_one(sock, node, linked):
            kind, key = ft.kind[sock]
            if kind == "tex":
                # the texture's closure: the root's zone, or this function's own Closure input
                self.L.new(self.texture_closure(*ft.textures[sock]), node.inputs[sock])
                return
            if kind == "ue_attr":
                fid, attr = key
                lazy = ins.get(fid)
                v = lazy.get(self) if lazy is not None else None
                attrs = v.s if v is not None and isinstance(v.s, Attrs) else Attrs()
                v = attrs.get(attr)
            elif kind in ("ue", "ue_alpha"):
                lazy = ins.get(key)
                v = lazy.get(self) if lazy is not None else None
                if v is None and sock in ft.previews:
                    v = self.input(fg, ft.previews[sock], {"_id": ("preview", fname, sock)}, None)
                if v is not None and kind == "ue_alpha":
                    v = self.alpha(v)
            else:
                v = self.env.group_input(key)
            if v is None:
                return
            if node.name in self.shared_calls and not v.const and not isinstance(v.s, (Attrs, TexRef))                     and self._closes_loop(node, v.s):
                linked.discard(sock)
                raise _Loop()
            self.link(v, node.inputs[sock])

        if w == "attrs":
            # each attribute links only the inputs it reaches, when something
            # reads it: UE compiles a Material Attributes output one property
            # at a time (InfoInvader's visor reads the Normal of the face's
            # attributes, whose Emissive needs the visor's UVs - linking every
            # attribute's inputs at once is a loop)
            souts = ft.attr_outs[fo["Properties"].get("Id")]
            passed = {}
            got = Attrs()
            for a, o in souts.items():
                if o[0] == "pass":
                    # unchanged by the function: the caller's own attribute,
                    # read only if something reads it
                    def own(fid=o[1], a=a):
                        if fid not in passed:
                            lazy = ins.get(fid)
                            passed[fid] = as_attrs(lazy.get(self) if lazy is not None else None)
                        return passed[fid].get(a)
                    got.thunks[a] = self.deferred(own)
                elif o[0] == "const":
                    got.vals[a] = o[1]
                else:
                    def made(sock=o[1], width=o[2]):
                        return Val(attach(ft.reached(sock), node, linked).outputs[sock], width)
                    got.thunks[a] = self.deferred(made)
            return Val(got, 0)
        at = attach(ft.reached(name) | ft.reached(socket_name(name + " (A)")) if w == 4 else ft.reached(name),
                    node, linked)
        if w == 4:
            return Val(at.outputs[name], 4, Val(at.outputs[socket_name(name + " (A)")], 1))
        return Val(at.outputs[name], w)

    def material_group(self, path, prop, name, finish=None):
        """A whole material's output as a node group (the sky's second slot)."""
        import bpy
        g = self.graph(path)
        key = ("material", path, prop)
        ft = self.functions.get(key)
        if ft is None:
            ft = self.functions[key] = FunctionTree(self, name, g)
            ft.tree.name = ft.prefix + name
            ft.tr.section = [name]
            prev = ft.tr.activate()
            try:
                v = ft.tr.input(g, g.editor_data()["Properties"][prop], {}, ft.tr.const(0.0))
                if finish is not None:
                    v = finish(ft.tr, v)
                ft.tree.interface.new_socket("Emissive Color", in_out='OUTPUT', socket_type='NodeSocketColor')
                if v.const:
                    v = ft.tr.solid(v)
                ft.tr.L.new(v.s, ft.go.inputs["Emissive Color"])
            finally:
                prev.activate()
            ft.outs[key] = ("Emissive Color", 3)
        node = self.node("ShaderNodeGroup", name)
        node.node_tree = ft.tree
        for sock in sorted(ft.reached("Emissive Color")):
            kind, k = ft.kind[sock]
            if kind == "env":
                self.link(self.env.group_input(k), node.inputs[sock])
            elif kind == "tex":
                self.L.new(self.texture_closure(*ft.textures[sock]), node.inputs[sock])
        return Val(node.outputs["Emissive Color"], 3)


class _Loop(Exception):
    """A link into a shared call node that would close a loop through it."""


class _Lazy:
    """A function input, evaluated the first time the function reads it."""
    __slots__ = ("g", "ref", "scope", "done", "val", "section")

    def __init__(self, g, ref, scope, section):
        self.g, self.ref, self.scope, self.done, self.val = g, ref, scope, False, None
        # an input is the caller's expression: its nodes go in the caller's frame
        self.section = list(section)

    def get(self, tr):
        if not self.done:
            saved = tr.section
            tr.section = self.section
            try:
                self.val = tr.input(self.g, self.ref, self.scope, None)
            finally:
                tr.section = saved
            self.done = True
        return self.val


class _Statics:
    """A function scope that knows only its static values (compile-time
    questions about a function, asked without building it)."""
    __slots__ = ("statics",)

    def __init__(self, statics):
        self.statics = statics


class _SpecialInputs(list):
    """Special functions read their inputs by index; evaluate on access."""

    def __init__(self, tr, lazies):
        super().__init__(lazies)
        self.tr = tr

    def __getitem__(self, i):
        return list.__getitem__(self, i).get(self.tr)

    def __iter__(self):
        return (x.get(self.tr) for x in list.__iter__(self))


# ------------------------------------------------------------------ duplicates
# Translation makes a node per expression pin and per call output: a texture read
# through R, G and A became three image nodes, a function called once and read
# through five outputs five group nodes. merge_duplicates() folds a finished tree.
_MERGE_SKIP = {"NodeFrame", "NodeReroute", "NodeGroupInput", "NodeGroupOutput", "ShaderNodeOutputMaterial",
               "ShaderNodeOutputAOV", "NodeClosureInput", "NodeClosureOutput"}
_MERGE_IGNORED = {"TexMapping", "ColorMapping", "ImageUser"}     # left at their defaults by the build
_MERGE_PROPS = {}


def _merge_props(n):
    """What besides its inputs decides a node's result: [(property, kind)], None when
    something can't be compared (a colour ramp's points, a curve)."""
    k = n.bl_idname
    if k not in _MERGE_PROPS:
        import bpy
        base = {p.identifier for t in (bpy.types.Node, bpy.types.ShaderNode) for p in t.bl_rna.properties}
        props = []
        for p in n.bl_rna.properties:
            ident = p.identifier
            if ident in base or ident.startswith("active_"):
                continue
            if p.type == 'POINTER':
                if ident in ("image", "node_tree", "object"):
                    props.append((ident, "id"))
                elif p.fixed_type.identifier not in _MERGE_IGNORED:
                    props = None
                    break
            else:
                props.append((ident, "items" if p.type == 'COLLECTION' else "value"))
        _MERGE_PROPS[k] = props
    return _MERGE_PROPS[k]


def _plain(v):
    if isinstance(v, float):
        return round(v, 6)
    if v is None or isinstance(v, (int, str, bool)):
        return v
    try:
        return tuple(_plain(x) for x in v)
    except TypeError:
        return repr(v)


def _group_deps(tree, memo):
    """{output socket identifier: {input socket identifiers it reads}} of a node group."""
    if tree.name in memo:
        return memo[tree.name]
    memo[tree.name] = {}        # a group inside itself can't be; guard anyway
    feeds, order, indeg = {}, [], {}
    nodes = {n.name: n for n in tree.nodes}
    for n in tree.nodes:
        indeg[n.name] = 0
    for l in tree.links:
        feeds.setdefault(l.to_node.name, []).append((l.to_socket.identifier, l.from_node.name, l.from_socket.identifier))
        indeg[l.to_node.name] += 1
    todo = [name for name, d in indeg.items() if d == 0]
    outs = {}
    for l in tree.links:
        outs.setdefault(l.from_node.name, []).append(l.to_node.name)
    while todo:
        name = todo.pop()
        order.append(name)
        for to in outs.get(name, ()):
            indeg[to] -= 1
            if indeg[to] == 0:
                todo.append(to)
    reads = {}      # node name -> {input identifier: {group inputs}}

    def out_set(name, ident):
        n = nodes[name]
        ins = reads.get(name, {})
        if n.bl_idname == "NodeGroupInput":
            return {ident}
        if n.bl_idname == "ShaderNodeGroup" and n.node_tree is not None:
            inner = _group_deps(n.node_tree, memo).get(ident)
            if inner is not None:
                return set().union(*(ins.get(i, set()) for i in inner))
        return set().union(*ins.values())
    for name in order:
        r = reads.setdefault(name, {})
        for to_ident, frm, from_ident in feeds.get(name, ()):
            r.setdefault(to_ident, set()).update(out_set(frm, from_ident))
    go = next((n for n in tree.nodes if n.bl_idname == "NodeGroupOutput" and n.is_active_output), None) \
        or next((n for n in tree.nodes if n.bl_idname == "NodeGroupOutput"), None)
    memo[tree.name] = dict(reads.get(go.name, {})) if go is not None else {}
    return memo[tree.name]


def merge_duplicates(tree, memo=None):
    """Fold nodes that compute the same thing into one: same type and settings, same inputs
    (the same upstream sockets, the same values). Group nodes of one group also merge when
    every input both read agrees - a call read through several outputs is one group node -
    unless that would close a loop (UE compiles each output of a call on its own: one
    output's inputs may need another's result). A vector split and put back together in
    order (UE's swizzles, free in HLSL, are nodes here) is the vector again, maths that
    hands a value on unchanged (x * 1, x + 0) goes, and so does what reaches no output.
    Returns how many nodes went."""
    memo = {} if memo is None else memo
    nodes = {n.as_pointer(): n for n in tree.nodes}
    ins, outs, indeg = {}, {}, dict.fromkeys(nodes, 0)
    for l in tree.links:
        a, b = l.from_node.as_pointer(), l.to_node.as_pointer()
        ins.setdefault(b, {})[l.to_socket.identifier] = (a, l.from_socket.identifier)
        outs.setdefault(a, []).append((l.from_socket.identifier, b, l.to_socket.identifier))
        indeg[b] += 1
    order, todo = [], [p for p, d in indeg.items() if d == 0]
    while todo:
        p = todo.pop()
        order.append(p)
        for _f, b, _t in outs.get(p, ()):
            indeg[b] -= 1
            if indeg[b] == 0:
                todo.append(b)
    canon = {}

    def root(p):
        while p in canon:
            p = canon[p]
        return p

    def socket(node, ident, output):
        return next(s for s in (node.outputs if output else node.inputs) if s.identifier == ident)

    def value(p, s):
        got = ins.get(p, {}).get(s.identifier)
        if got is not None:
            return ("link", root(got[0]), got[1])
        return _plain(getattr(s, "default_value", None))

    def signature(p, n, props):
        vals = []
        for ident, kind in props:
            v = getattr(n, ident)
            if kind == "id":
                v = v.name if v is not None else None
            elif kind == "items":
                v = tuple((it.name, getattr(it, "socket_type", getattr(it, "data_type", ""))) for it in v)
            vals.append(_plain(v))
        sig = [n.bl_idname, tuple(vals), tuple((s.identifier, value(p, s)) for s in n.inputs if s.enabled),
               tuple(sorted((k, _plain(n[k])) for k in n.keys() if k != SECTION_KEY))]
        if n.bl_idname in ("ShaderNodeValue", "ShaderNodeRGB"):
            sig.append(_plain(n.outputs[0].default_value))
        return tuple(sig)

    def upstream(target, starts):
        """Whether `target` feeds any of `starts`."""
        seen, todo = set(), list(starts)
        while todo:
            p = root(todo.pop())
            if p == target:
                return True
            if p in seen:
                continue
            seen.add(p)
            todo += [a for a, _i in ins.get(p, {}).values()]
        return False

    def needs(p, n):
        deps = _group_deps(n.node_tree, memo)
        every = {s.identifier for s in n.inputs}
        got = set()
        for f, _b, _t in outs.get(p, ()):
            got |= deps.get(f, every)
        return got

    def section(a, b):
        pa, pb = str(a.get(SECTION_KEY, "")).split("/"), str(b.get(SECTION_KEY, "")).split("/")
        # what the Normal's own pass shares with the rest stays with the rest
        if (pa[0] == NORMAL_PASS) != (pb[0] == NORMAL_PASS):
            return "/".join(pb if pa[0] == NORMAL_PASS else pa)
        common = []
        for x, y in zip(pa, pb):
            if x != y:
                break
            common.append(x)
        return "/".join(common)

    def fold(dup, keep):
        d, k = nodes[dup], nodes[keep]
        for f, b, t in outs.pop(dup, []):
            if b not in nodes:
                continue
            tree.links.new(socket(k, f, True), socket(nodes[b], t, False))
            outs.setdefault(keep, []).append((f, b, t))
            ins.setdefault(b, {})[t] = (keep, f)
        if SECTION_KEY in k:
            k[SECTION_KEY] = section(k, d)
        ins.pop(dup, None)
        del nodes[dup]
        tree.nodes.remove(d)
        canon[dup] = keep

    def try_group(p, n, kept):
        """Fold group node p into an earlier one of its group that agrees where both read."""
        need = needs(p, n)
        mine = {s.identifier: value(p, s) for s in n.inputs}
        my_srcs = [v[1] for i, v in mine.items() if i in need and isinstance(v, tuple) and v[:1] == ("link",)]
        for q in kept:
            if q not in nodes:
                continue
            m = nodes[q]
            need_q = needs(q, m)
            theirs = {s.identifier: value(q, s) for s in m.inputs}
            if any(mine[i] != theirs.get(i) for i in need & need_q):
                continue
            q_srcs = [v[1] for i, v in theirs.items() if i in need_q and isinstance(v, tuple) and v[:1] == ("link",)]
            if upstream(q, my_srcs) or upstream(p, q_srcs):
                continue
            for i in need - need_q:
                s = socket(m, i, False)
                v = mine[i]
                if isinstance(v, tuple) and v[:1] == ("link",):
                    tree.links.new(socket(nodes[v[1]], v[2], True), s)
                    ins.setdefault(q, {})[i] = (v[1], v[2])
                    outs.setdefault(v[1], []).append((v[2], q, i))
                else:
                    if i in ins.get(q, {}):
                        for l in s.links:
                            tree.links.remove(l)
                        del ins[q][i]
                    if hasattr(s, "default_value") and v is not None:
                        s.default_value = v
            fold(p, q)
            return q
        return None

    def round_trip(p, n):
        """A Combine XYZ of one Separate XYZ's X, Y and Z in order is its vector: its readers
        take that vector (the source itself), and the pair goes where nothing else reads it."""
        got = ins.get(p, {})
        src = [got.get(i) for i in ("X", "Y", "Z")]
        if any(v is None for v in src):
            return False
        sep = root(src[0][0])
        if any(root(v[0]) != sep or v[1] != i for v, i in zip(src, ("X", "Y", "Z"))) \
                or sep not in nodes or nodes[sep].bl_idname != "ShaderNodeSeparateXYZ":
            return False
        feed = ins.get(sep, {}).get("Vector")
        if feed is None:
            return False
        a, ia = root(feed[0]), feed[1]
        if a not in nodes:
            return False
        out = socket(nodes[a], ia, True)
        readers = [(b, t) for _f, b, t in outs.get(p, ()) if b in nodes]
        # a colour carries alpha and turns to a float by luminance, where the vector averages:
        # it stands in only where it's read as a vector
        if out.type not in ('VECTOR', 'VALUE') and not (
                out.type == 'RGBA' and all(socket(nodes[b], t, False).type == 'VECTOR' for b, t in readers)):
            return False
        for b, t in readers:
            tree.links.new(out, socket(nodes[b], t, False))
            outs.setdefault(a, []).append((ia, b, t))
            ins.setdefault(b, {})[t] = (a, ia)
        outs.pop(p, None)
        ins.pop(p, None)
        tree.nodes.remove(nodes.pop(p))
        rest = [e for e in outs.get(sep, ()) if e[1] != p and e[1] in nodes]
        outs[sep] = rest
        if not rest:
            ins.pop(sep, None)
            tree.nodes.remove(nodes.pop(sep))
            return 2
        return 1

    # (operation: (the value that hands the other input on, the inputs that value may sit on))
    no_op = {"ShaderNodeMath": {"MULTIPLY": (1.0, (0, 1)), "ADD": (0.0, (0, 1)), "SUBTRACT": (0.0, (1,)),
                                "DIVIDE": (1.0, (1,)), "POWER": (1.0, (1,))},
             "ShaderNodeVectorMath": {"MULTIPLY": ((1.0, 1.0, 1.0), (0, 1)), "ADD": ((0.0, 0.0, 0.0), (0, 1)),
                                      "SUBTRACT": ((0.0, 0.0, 0.0), (1,)), "DIVIDE": ((1.0, 1.0, 1.0), (1,))}}

    def passthrough(p, n):
        """x * 1, x + 0, x - 0, x / 1, x ^ 1 (and a vector scaled by 1): its readers read x, the
        node goes - where x is of the node's own type (Blender converts a vector to a float by
        its average, a colour by its luminance: a reader of another type would read it else)."""
        rules = no_op.get(n.bl_idname)
        if rules is None or getattr(n, "use_clamp", False):
            return False
        if n.bl_idname == "ShaderNodeVectorMath" and n.operation == 'SCALE':
            keep = 0 if not n.inputs["Scale"].is_linked and _plain(n.inputs["Scale"].default_value) == 1.0 else None
        else:
            rule = rules.get(n.operation)
            keep = None
            for i in (rule[1] if rule else ()):
                if n.inputs[i].identifier not in ins.get(p, {}) and _plain(n.inputs[i].default_value) == rule[0]:
                    keep = 1 - i
                    break
        if keep is None:
            return False
        feed = ins.get(p, {}).get(n.inputs[keep].identifier)
        out = n.outputs[0]
        if feed is None or any(f != out.identifier for f, _b, _t in outs.get(p, ())):
            return False
        a, ia = root(feed[0]), feed[1]
        if a not in nodes or socket(nodes[a], ia, True).type != out.type:
            return False
        src = socket(nodes[a], ia, True)
        for _f, b, t in outs.pop(p, []):
            if b in nodes:
                tree.links.new(src, socket(nodes[b], t, False))
                outs.setdefault(a, []).append((ia, b, t))
                ins.setdefault(b, {})[t] = (a, ia)
        ins.pop(p, None)
        tree.nodes.remove(nodes.pop(p))
        return True

    def const_in(p, s):
        """What an input holds when nothing feeds it (plain numbers), else None."""
        if s.identifier in ins.get(p, {}) or not hasattr(s, "default_value"):
            return None
        return _plain(s.default_value)

    def hand_on(p, feed, out):
        """p's readers read what feeds it (feed: (node, output)) instead; p goes - where that is
        of p's output's own type (Blender converts between types its own way)."""
        if any(f != out.identifier for f, b, _t in outs.get(p, ()) if b in nodes):
            return False
        a, ia = root(feed[0]), feed[1]
        if a not in nodes:
            return False
        src = socket(nodes[a], ia, True)
        if src.type != out.type:
            return False
        for _f, b, t in outs.pop(p, []):
            if b in nodes:
                tree.links.new(src, socket(nodes[b], t, False))
                outs.setdefault(a, []).append((ia, b, t))
                ins.setdefault(b, {})[t] = (a, ia)
        ins.pop(p, None)
        tree.nodes.remove(nodes.pop(p))
        return True

    def constant(p, values):
        """p's readers hold constants ({output identifier: float or 3-tuple}) where they read
        it; p goes. Not where a reader can't hold one."""
        plan = []
        for f, b, t in outs.get(p, ()):
            if b not in nodes:
                continue
            if f not in values:
                return False
            s = socket(nodes[b], t, False)
            v = _socket_value(values[f], s)
            if v is None:
                return False
            plan.append((b, t, s, v))
        for b, t, s, v in plan:
            for l in list(s.links):
                tree.links.remove(l)
            s.default_value = v
            ins.get(b, {}).pop(t, None)
        outs.pop(p, None)
        ins.pop(p, None)
        tree.nodes.remove(nodes.pop(p))
        return True

    def settle(p, n):
        """A node whose result is known as the tree is built - every input a constant, a
        product with 0, a mix whose factor is 0 or 1 - is that result: its readers take it (a
        game-only effect left off, its parameter built in at 0, folds away with what fed it)."""
        if n.mute:
            return False
        kind = n.bl_idname
        if kind == "ShaderNodeMix":
            dt = n.data_type
            key = {"FLOAT": "_Float", "VECTOR": "_Vector", "RGBA": "_Color"}.get(dt)
            if key is None or dt == 'RGBA' and n.clamp_result:
                return False
            fac = socket(n, "Factor_Vector" if dt == 'VECTOR' and n.factor_mode == 'NON_UNIFORM' else "Factor_Float", False)
            f = const_in(p, fac)
            if isinstance(f, tuple):
                f = f[0] if len(set(f)) == 1 else None
            out = socket(n, "Result" + key, True)
            a_in, b_in = socket(n, "A" + key, False), socket(n, "B" + key, False)
            fa, fb = ins.get(p, {}).get(a_in.identifier), ins.get(p, {}).get(b_in.identifier)
            if fa is not None and fb is not None and (root(fa[0]), fa[1]) == (root(fb[0]), fb[1]) \
                    and (dt != 'RGBA' or n.blend_type == 'MIX'):
                return hand_on(p, fa, out)       # a mix of a value with itself
            if f in (0.0, 1.0) and not (f == 1.0 and dt == 'RGBA' and n.blend_type != 'MIX'):
                pick = socket(n, ("B" if f == 1.0 else "A") + key, False)
                feed = ins.get(p, {}).get(pick.identifier)
                if feed is not None:
                    return hand_on(p, feed, out)
                return dt != 'RGBA' and constant(p, {out.identifier: const_in(p, pick)})
            if f is None or dt == 'RGBA':
                return False
            a, b = const_in(p, socket(n, "A" + key, False)), const_in(p, socket(n, "B" + key, False))
            if a is None or b is None:
                return False
            if n.clamp_factor:
                f = min(max(f, 0.0), 1.0)
            if dt == 'FLOAT':
                return constant(p, {out.identifier: a + (b - a) * f})
            return constant(p, {out.identifier: tuple(x + (y - x) * f for x, y in zip(a, b))})
        if kind == "ShaderNodeMath":
            k = _MATH_ARITY.get(n.operation)
            if k is None:
                return False
            vals = [const_in(p, n.inputs[i]) for i in range(k)]
            if n.use_clamp and n.operation == 'MULTIPLY' and 1.0 in vals:
                # a saturate of a value a clamped node made: that value
                feed = ins.get(p, {}).get(n.inputs[vals.index(1.0) ^ 1].identifier)
                src = nodes.get(root(feed[0])) if feed is not None else None
                if src is not None and src.bl_idname == "ShaderNodeMath" and src.use_clamp:
                    return hand_on(p, feed, n.outputs[0])
            if n.operation == 'MULTIPLY' and 0.0 in vals:
                return constant(p, {n.outputs[0].identifier: 0.0})
            if any(v is None for v in vals):
                return False
            r = _blender_math(n.operation, *vals)
            if r is None:
                return False
            if n.use_clamp:
                r = min(max(r, 0.0), 1.0)
            return constant(p, {n.outputs[0].identifier: r})
        if kind == "ShaderNodeVectorMath":
            op = n.operation
            if op == 'SCALE':
                vals = [const_in(p, n.inputs[0]), const_in(p, n.inputs["Scale"])]
            else:
                k = _VMATH_ARITY.get(op)
                if k is None:
                    return False
                vals = [const_in(p, n.inputs[i]) for i in range(k)]
            if op in ('MULTIPLY', 'SCALE') and any(v == 0.0 or v == (0.0, 0.0, 0.0) for v in vals):
                return constant(p, {n.outputs["Vector"].identifier: (0.0, 0.0, 0.0)})
            if any(v is None for v in vals):
                return False
            r = _blender_vmath(op, *vals)
            if r is None:
                return False
            out = n.outputs["Value"] if isinstance(r, float) else n.outputs["Vector"]
            return constant(p, {out.identifier: r})
        if kind == "ShaderNodeCombineXYZ":
            vals = [const_in(p, s) for s in n.inputs]
            if any(v is None for v in vals):
                return False
            return constant(p, {n.outputs[0].identifier: tuple(vals)})
        if kind == "ShaderNodeSeparateXYZ":
            v = const_in(p, n.inputs[0])
            if v is None:
                return False
            return constant(p, {s.identifier: v[i] for i, s in enumerate(n.outputs)})
        return False

    seen, sig_of, groups, gone = {}, {}, {}, 0
    for p in order:
        n = nodes.get(p)
        if n is None or n.bl_idname in _MERGE_SKIP:
            continue
        if settle(p, n):
            gone += 1
            continue
        if n.bl_idname == "ShaderNodeCombineXYZ":
            cut = round_trip(p, n)
            if cut:
                gone += cut
                continue
        if passthrough(p, n):
            gone += 1
            continue
        props = _merge_props(n)
        if props is None:
            continue
        sig = signature(p, n, props)
        twin = seen.get(sig)
        if twin is not None and twin in nodes:
            fold(p, twin)
            gone += 1
            continue
        if n.bl_idname == "ShaderNodeGroup" and n.node_tree is not None:
            kept = groups.setdefault(n.node_tree.name, [])
            q = try_group(p, n, kept)
            if q is not None:
                # its inputs changed: what it now matches
                if seen.get(sig_of.get(q)) == q:
                    del seen[sig_of[q]]
                sig_of[q] = signature(q, nodes[q], props)
                seen[sig_of[q]] = q
                gone += 1
                continue
            kept.append(p)
        seen[sig] = p
        sig_of[p] = sig
    # what reaches no output goes (a branch translation made that no attribute kept)
    outputs = ("NodeGroupOutput", "ShaderNodeOutputMaterial", "ShaderNodeOutputAOV", "ShaderNodeOutputWorld")
    live, todo = set(), [p for p, n in nodes.items() if n.bl_idname in outputs]
    if todo:
        while todo:
            p = todo.pop()
            if p not in live:
                live.add(p)
                todo += [root(a) for a, _i in ins.get(p, {}).values()]
        for p, n in list(nodes.items()):
            if p not in live and n.bl_idname not in ("NodeFrame", "NodeGroupInput"):
                tree.nodes.remove(n)
                del nodes[p]
                gone += 1
    return gone


_SHELL_ATTRIBUTES = {"ShellMeshShellLayerIndex": SHELL_LAYER, "ShellMeshNormalizedShellLayer": SHELL_LAYER_N,
                     "ShellMeshShellCount": SHELL_COUNT}
_SHELL_VECTORS = {"ShellMeshLocalShellOffset": SHELL_OFFSET, "ShellMeshLocalShellVector": SHELL_VECTOR}


# constant folding (merge_duplicates): Blender's maths, as its nodes do it
import math as _math

_MATH_ARITY = {"ADD": 2, "SUBTRACT": 2, "MULTIPLY": 2, "DIVIDE": 2, "MAXIMUM": 2, "MINIMUM": 2, "POWER": 2,
               "LESS_THAN": 2, "GREATER_THAN": 2, "MODULO": 2, "MULTIPLY_ADD": 3, "COMPARE": 3,
               "ABSOLUTE": 1, "SIGN": 1, "FLOOR": 1, "CEIL": 1, "FRACT": 1, "SQRT": 1, "SINE": 1, "COSINE": 1,
               "ROUND": 1, "TRUNC": 1}
_VMATH_ARITY = {"ADD": 2, "SUBTRACT": 2, "MULTIPLY": 2, "DIVIDE": 2, "MINIMUM": 2, "MAXIMUM": 2,
                "DOT_PRODUCT": 2, "DISTANCE": 2, "CROSS_PRODUCT": 2, "ABSOLUTE": 1, "LENGTH": 1, "NORMALIZE": 1}


def _blender_math(op, a, b=None, c=None):
    if op == "ADD": return a + b
    if op == "SUBTRACT": return a - b
    if op == "MULTIPLY": return a * b
    if op == "DIVIDE": return a / b if b != 0.0 else 0.0
    if op == "MAXIMUM": return max(a, b)
    if op == "MINIMUM": return min(a, b)
    if op == "POWER":
        if a >= 0.0 or b == _math.floor(b):
            try:
                return float(a ** b) if (a != 0.0 or b >= 0.0) else 0.0
            except (OverflowError, ZeroDivisionError):
                return None
        return 0.0
    if op == "LESS_THAN": return 1.0 if a < b else 0.0
    if op == "GREATER_THAN": return 1.0 if a > b else 0.0
    if op == "MODULO": return _math.fmod(a, b) if b != 0.0 else 0.0
    if op == "MULTIPLY_ADD": return a * b + c
    if op == "COMPARE": return 1.0 if abs(a - b) <= max(c, 1e-5) else 0.0
    if op == "ABSOLUTE": return abs(a)
    if op == "SIGN": return float((a > 0) - (a < 0))
    if op == "FLOOR": return float(_math.floor(a))
    if op == "CEIL": return float(_math.ceil(a))
    if op == "FRACT": return a - _math.floor(a)
    if op == "SQRT": return _math.sqrt(a) if a > 0.0 else 0.0
    if op == "SINE": return _math.sin(a)
    if op == "COSINE": return _math.cos(a)
    if op == "ROUND": return float(_math.floor(a + 0.5))
    if op == "TRUNC": return float(_math.trunc(a))
    return None


def _blender_vmath(op, a, b=None):
    if op == "ADD": return tuple(x + y for x, y in zip(a, b))
    if op == "SUBTRACT": return tuple(x - y for x, y in zip(a, b))
    if op == "MULTIPLY": return tuple(x * y for x, y in zip(a, b))
    if op == "DIVIDE": return tuple(x / y if y != 0.0 else 0.0 for x, y in zip(a, b))
    if op == "SCALE": return tuple(x * b for x in a)
    if op == "MINIMUM": return tuple(min(x, y) for x, y in zip(a, b))
    if op == "MAXIMUM": return tuple(max(x, y) for x, y in zip(a, b))
    if op == "ABSOLUTE": return tuple(abs(x) for x in a)
    if op == "DOT_PRODUCT": return float(sum(x * y for x, y in zip(a, b)))
    if op == "LENGTH": return _math.sqrt(sum(x * x for x in a))
    if op == "DISTANCE": return _math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))
    if op == "CROSS_PRODUCT":
        return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])
    if op == "NORMALIZE":
        n = _math.sqrt(sum(x * x for x in a))
        return tuple(x / n for x in a) if n > 0.0 else (0.0, 0.0, 0.0)
    return None


def _socket_value(v, s):
    """A constant (float or tuple) as an input socket holds it - Blender reads a vector as a
    float by its average, a float as a vector in every component, a vector as an opaque
    colour - or None where the socket holds no such value."""
    # (a reroute's socket has a type but nowhere to keep a value: writing one crashes Blender)
    if not hasattr(s, "default_value") or s.type not in ('VALUE', 'VECTOR', 'RGBA') or s.node.bl_idname == "NodeReroute":
        return None
    vec = isinstance(v, tuple)
    if vec:
        v = tuple(v[:3])
    if s.type == 'VALUE':
        return sum(v) / len(v) if vec else float(v)
    if s.type == 'RGBA':
        return (v if vec else (float(v),) * 3) + (1.0,)
    k = len(s.default_value)
    if not vec:
        return (float(v),) * k
    return (v + (0.0,) * k)[:k]


_PY = {
    "ADD": lambda a, b: a + b, "SUBTRACT": lambda a, b: a - b, "MULTIPLY": lambda a, b: a * b,
    "DIVIDE": lambda a, b: a / b if b else 0.0, "MAXIMUM": max, "MINIMUM": min,
    "POWER": lambda a, b: a ** b if a > 0 else 0.0,
}
